    const handleWhatsApp = useCallback((car: any) => {
        const phone = (session?.whatsappNumber || globalWhatsapp).replace(/\D/g, '');
        const price = formatPrice(
            currency === 'SAR' ? (car.priceSar || car.priceEstimate || 0)
