}

'use client';

import { useEffect } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import Link from 'next/link';
import { motion } from 'framer-motion';
import {
    LayoutGrid,
    ShoppingBag,
    Heart,
    Bell,
    Settings,
    User,
    Sparkles,
    LogOut,
    Car,
    Gavel,
    ChevronLeft,
