        name: '',
        email: '',
        phone: '',
        role: 'buyer'
    });
    const [passwordData, setPasswordData] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    // ─── 2FA State ───
    const [twoFaEnabled, setTwoFaEnabled] = useState(false);
    const [twoFaStep, setTwoFaStep] = useState<'idle' | 'setup' | 'verify' | 'done'>('idle');
    const [twoFaQR, setTwoFaQR] = useState('');
    const [twoFaSecret, setTwoFaSecret] = useState('');
    const [twoFaBackupCodes, setTwoFaBackupCodes] = useState<string[]>([]);
    const [twoFaCode, setTwoFaCode] = useState('');
    const [twoFaLoading, setTwoFaLoading] = useState(false);
    const [twoFaMsg, setTwoFaMsg] = useState('');

    useEffect(() => {
        if (typeof window !== 'undefined') {
            const user = localStorage.getItem('hm_user');
            if (user) {
                try {
                    const data = JSON.parse(user);
                    setUserData({
                        name: data.name || '',
                        email: data.email || '',
                        phone: data.phone || '',
                        role: data.role || 'buyer'
                    });
                    setTwoFaEnabled(!!data.twoFactorEnabled);
                } catch (e) {
                    console.error('Error parsing user data', e);
                }
            }
        }
    }, []);

    const handleProfileUpdate = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setMessage('');

        try {
            await api.users.updateProfile(userData);
            const currentUser = JSON.parse(localStorage.getItem('hm_user') || '{}');
            const updatedUser = { ...currentUser, ...userData };
            localStorage.setItem('hm_user', JSON.stringify(updatedUser));
            setMessage(isRTL ? 'تم تحديث البيانات بنجاح' : 'Profile updated successfully');
        } catch (err: any) {
            setMessage(err.message || (isRTL ? 'حدث خطأ' : 'An error occurred'));
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordChange = async (e: React.FormEvent) => {
        e.preventDefault();
        if (passwordData.newPassword !== passwordData.confirmPassword) {
            setMessage(isRTL ? 'كلمات المرور غير متطابقة' : 'Passwords do not match');
            return;
        }

        setLoading(true);
        setMessage('');

        try {
            const res = await api.auth.changePassword({
                currentPassword: passwordData.currentPassword,
                newPassword: passwordData.newPassword
            });
            
            if (res.success && res.token) {
                localStorage.setItem('hm_token', res.token);
                // Also set cookie for middleware
                document.cookie = `hm_token=${res.token}; path=/; max-age=${30 * 24 * 60 * 60}; SameSite=Lax`;
                
                setMessage(isRTL ? '✅ تم تغيير كلمة المرور بنجاح' : '✅ Password changed successfully');
                setPasswordData({ currentPassword: '', newPassword: '', confirmPassword: '' });
            } else {
                setMessage(res.message || (isRTL ? 'فشل تغيير كلمة المرور' : 'Failed to change password'));
            }
        } catch (err: any) {
            console.error('Password change error:', err);
            setMessage(err.message || (isRTL ? 'حدث خطأ في النظام' : 'Protocol error occurred'));
        } finally {
            setLoading(false);
        }
    };

    const handleLogout = () => { logout(); };

    // ─── 2FA Handlers ───
    const handleSetup2FA = async () => {
        setTwoFaLoading(true);
        setTwoFaMsg('');
        try {
            const res = await (api as any).auth.setup2FA?.() ??
                await fetch('/api/v2/auth/2fa/setup', {
                    method: 'POST',
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('hm_token')}`, 'Content-Type': 'application/json' }
                }).then(r => r.json());
            if (res.success) {
                setTwoFaQR(res.qrCode || res.qrDataURL || '');
                setTwoFaSecret(res.secret || '');
                setTwoFaStep('setup');
            } else {
                setTwoFaMsg(res.message || (isRTL ? 'فشل إعداد 2FA' : '2FA setup failed'));
            }
        } catch { setTwoFaMsg(isRTL ? 'خطأ في الاتصال' : 'Connection error'); }
        finally { setTwoFaLoading(false); }
    };

    const handleConfirm2FA = async () => {
        if (twoFaCode.length < 6) return;
        setTwoFaLoading(true);
        try {
            const res = await fetch('/api/v2/auth/2fa/enable', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${localStorage.getItem('hm_token')}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ code: twoFaCode, secret: twoFaSecret })
            }).then(r => r.json());
            if (res.success) {
                setTwoFaEnabled(true);
                setTwoFaBackupCodes(res.backupCodes || []);
                setTwoFaStep('done');
                const u = JSON.parse(localStorage.getItem('hm_user') || '{}');
                localStorage.setItem('hm_user', JSON.stringify({ ...u, twoFactorEnabled: true }));
                setTwoFaMsg(isRTL ? '✅ تم تفعيل التحقق بخطوتين' : '✅ 2FA enabled successfully');
            } else {
                setTwoFaMsg(res.message || (isRTL ? 'رمز خاطئ' : 'Invalid code'));
            }
        } catch { setTwoFaMsg(isRTL ? 'خطأ' : 'Error'); }
        finally { setTwoFaLoading(false); }
    };

    const handleDisable2FA = async () => {
        setTwoFaLoading(true);
        try {
            const res = await fetch('/api/v2/auth/2fa/disable', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${localStorage.getItem('hm_token')}`, 'Content-Type': 'application/json' }
            }).then(r => r.json());
            if (res.success) {
                setTwoFaEnabled(false);
                setTwoFaStep('idle');
                const u = JSON.parse(localStorage.getItem('hm_user') || '{}');
                localStorage.setItem('hm_user', JSON.stringify({ ...u, twoFactorEnabled: false }));
                setTwoFaMsg(isRTL ? '✅ تم إلغاء التحقق بخطوتين' : '✅ 2FA disabled');
            } else { setTwoFaMsg(res.message || (isRTL ? 'فشل' : 'Failed')); }
        } catch { setTwoFaMsg(isRTL ? 'خطأ' : 'Error'); }
        finally { setTwoFaLoading(false); }
    };

    return (
        <div className="flex flex-col h-full bg-[#080809]">
            <ClientPageHeader
                title={isRTL ? 'الملف الشخصي' : 'Profile Settings'}
                subtitle={isRTL ? 'إدارة معلوماتك الشخصية وإعدادات الحساب' : 'MANAGE ACCOUNT DETAILS'}
                icon={User}
            />

            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-8 space-y-8 pb-32 lg:pb-12">
                {/* Message Banner */}
                {message && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="p-4 bg-cinematic-neon-gold/10 border border-cinematic-neon-gold/20 rounded-2xl text-center"
                    >
                        <p className="text-xs font-bold text-cinematic-neon-gold">{message}</p>
                    </motion.div>
                )}

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">
                    {/* User Card */}
                    <div className="xl:col-span-4 space-y-6">
                        <div className="bg-white/3 border border-white/5 rounded-[2.5rem] p-8 text-center relative overflow-hidden group">
                           <div className="absolute inset-0 bg-cinematic-neon-gold/5 opacity-0 group-hover:opacity-100 transition-opacity duration-700 blur-3xl" />
                           <div className="relative">
                               <div className="w-24 h-24 mx-auto rounded-full bg-cinematic-neon-gold/10 border border-cinematic-neon-gold/20 flex items-center justify-center mb-6 shadow-2xl">
                                   <User className="w-10 h-10 text-cinematic-neon-gold" />
                               </div>
                               <h3 className="text-xl font-black text-white italic tracking-tight mb-2 uppercase">{userData.name || rawText('GUEST')}</h3>
                               <div className="text-[10px] text-white/30 font-black uppercase tracking-[0.4em] mb-8">{userData.role}</div>
                               
                               <button 
                                onClick={handleLogout}
                                className="w-full py-4 rounded-2xl bg-red-500/10 border border-red-500/20 text-red-500 text-[11px] font-black uppercase tracking-widest hover:bg-red-500/20 transition-all flex items-center justify-center gap-3"
                               >
                                   <LogOut className="w-4 h-4" />
                                   {isRTL ? 'تسجيل الخروج' : 'Sign Out'}
                               </button>
                           </div>
                        </div>

                        {/* Security Info */}
                        <div className="bg-cinematic-neon-gold/[0.02] border border-cinematic-neon-gold/10 rounded-[2rem] p-6 flex flex-col items-center text-center gap-3">
                            <Shield className="w-6 h-6 text-cinematic-neon-gold/40" />
                            <div className="text-[11px] font-black text-cinematic-neon-gold/60 uppercase tracking-widest">{isRTL ? 'اتصال مؤمن' : 'SECURE ENCRYPTION'}</div>
                            <p className="text-[10px] text-white/20 leading-relaxed">
                                {isRTL ? 'نظام التشفير لدينا يضمن حماية بياناتك الشخصية بالكامل' : 'END-TO-END AES-256 PROTECTION FOR ALL USER DATA'}
                            </p>
                        </div>
                    </div>

                    {/* Forms */}
                    <div className="xl:col-span-8 space-y-8">
                        {/* Personal Info */}
                        <section className="bg-white/3 border border-white/5 rounded-[2.5rem] p-8 lg:p-10">
                            <div className="flex items-center gap-4 mb-10">
                                <div className="w-10 h-10 rounded-2xl bg-white/5 flex items-center justify-center">
                                    <Edit3 className="w-5 h-5 text-cinematic-neon-gold" />
                                </div>
                                <div>
                                    <h2 className="text-[11px] font-black text-white uppercase tracking-[0.5em] mb-1">{isRTL ? 'المعلومات الشخصية' : 'PERSONAL DETAILS'}</h2>
                                    <div className="h-0.5 w-12 bg-cinematic-neon-gold/30 rounded-full" />
                                </div>
                            </div>

                            <form onSubmit={handleProfileUpdate} className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'اسم المستخدم' : 'NAME'}</label>
                                        <div className="relative">
                                            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-white/10" />
                                            <input 
                                                type="text"
                                                value={userData.name}
                                                onChange={(e) => setUserData({ ...userData, name: e.target.value })}
                                                placeholder={isRTL ? 'الاسم' : 'Name'}
                                                className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 flex pl-12 pr-6 text-sm font-bold text-white focus:outline-none focus:border-cinematic-neon-gold/40 transition-all"
                                            />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'البريد الإلكتروني' : 'EMAIL'}</label>
                                        <div className="relative">
                                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-white/10" />
                                            <input 
                                                type="email"
                                                value={userData.email}
                                                onChange={(e) => setUserData({ ...userData, email: e.target.value })}
                                                className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 pl-12 pr-6 text-sm font-bold text-white/60 focus:outline-none focus:border-cinematic-neon-gold/40 transition-all"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'رقم الهاتف' : 'PHONE'}</label>
                                    <div className="relative">
                                        <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-white/10" />
                                        <input 
                                            type="tel"
                                            value={userData.phone}
                                            onChange={(e) => setUserData({ ...userData, phone: e.target.value })}
                                            placeholder={isRTL ? 'رقم الهاتف' : 'Phone'}
                                            className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 pl-12 pr-6 text-sm font-bold text-white focus:outline-none focus:border-cinematic-neon-gold/40 transition-all"
                                        />
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={loading}
                                    className="w-full sm:w-auto px-10 py-4 bg-cinematic-neon-gold text-black rounded-2xl text-[11px] font-black uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-xl shadow-cinematic-neon-gold/10 flex items-center justify-center gap-3"
                                >
                                    <Save className="w-4.5 h-4.5" />
                                    {isRTL ? 'حفظ البيانات' : 'UPDATE PROFILE'}
                                </button>
                            </form>
                        </section>

                        {/* Password */}
                        <section className="bg-white/3 border border-white/5 rounded-[2.5rem] p-8 lg:p-10">
                            <div className="flex items-center gap-4 mb-10">
                                <div className="w-10 h-10 rounded-2xl bg-white/5 flex items-center justify-center text-red-500">
                                    <Lock className="w-5 h-5" />
                                </div>
                                <div>
                                    <h2 className="text-[11px] font-black text-white uppercase tracking-[0.5em] mb-1">{isRTL ? 'تعديل كلمة المرور' : 'SECURITY & PASS'}</h2>
                                    <div className="h-0.5 w-12 bg-red-500/30 rounded-full" />
                                </div>
                            </div>

                            <form onSubmit={handlePasswordChange} className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'كلمة المرور الحالية' : 'CURRENT PASSWORD'}</label>
                                    <div className="relative">
                                        <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-white/10" />
                                        <input 
                                            type="password"
                                            value={passwordData.currentPassword}
                                            onChange={(e) => setPasswordData({ ...passwordData, currentPassword: e.target.value })}
                                            placeholder="••••••••"
                                            className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 pl-12 pr-6 text-sm font-bold text-white focus:outline-none focus:border-red-500/40 transition-all"
                                        />
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'جديد' : 'NEW'}</label>
                                        <input 
                                            type="password"
                                            value={passwordData.newPassword}
                                            onChange={(e) => setPasswordData({ ...passwordData, newPassword: e.target.value })}
                                            placeholder="••••••••"
                                            className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 px-6 text-sm font-bold text-white focus:outline-none focus:border-red-500/40 transition-all"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] ml-2 rtl:mr-2 rtl:ml-0">{isRTL ? 'تأكيد' : 'CONFIRM'}</label>
                                        <input 
                                            type="password"
                                            value={passwordData.confirmPassword}
                                            onChange={(e) => setPasswordData({ ...passwordData, confirmPassword: e.target.value })}
                                            placeholder="••••••••"
                                            className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4 px-6 text-sm font-bold text-white focus:outline-none focus:border-red-500/40 transition-all"
                                        />
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={loading}
                                    className="w-full sm:w-auto px-10 py-4 bg-white text-black rounded-2xl text-[11px] font-black uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center justify-center gap-3"
                                >
                                    <Shield className="w-4.5 h-4.5" />
                                    {isRTL ? 'تغيير كلمة المرور' : 'CHANGE PASSWORD'}
                                </button>
                            </form>
                        </section>

                        {/* ─── 2FA Section ─── */}
                        <section className="bg-white/[0.02] border border-white/5 rounded-3xl p-6 sm:p-10 space-y-6">
                            <div className="flex items-center justify-between gap-4">
                                <div className="flex items-center gap-3">
                                    <div className={`p-2.5 rounded-xl ${twoFaEnabled ? 'bg-emerald-500/10 text-emerald-400' : 'bg-white/5 text-white/30'}`}>
                                        {twoFaEnabled ? <ShieldCheck className="w-5 h-5" /> : <ShieldOff className="w-5 h-5" />}
                                    </div>
                                    <div>
                                        <h2 className="text-[11px] font-black text-white uppercase tracking-[0.4em]">
                                            {isRTL ? 'التحقق بخطوتين (2FA)' : 'TWO-FACTOR AUTH'}
                                        </h2>
                                        <p className="text-[10px] text-white/30 mt-0.5">
                                            {twoFaEnabled
                                                ? (isRTL ? '✅ مُفعَّل — حسابك محمي' : '✅ Enabled — Account Protected')
                                                : (isRTL ? 'غير مُفعَّل — انقر لتفعيله' : 'Disabled — Click to enable')}
                                        </p>
                                    </div>
                                </div>
                                {twoFaEnabled ? (
                                    <button onClick={handleDisable2FA} disabled={twoFaLoading}
                                        className="px-4 py-2 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-[10px] font-black uppercase tracking-widest hover:bg-red-500/20 transition-all disabled:opacity-50">
                                        {twoFaLoading ? '...' : (isRTL ? 'إلغاء' : 'DISABLE')}
                                    </button>
                                ) : (
                                    twoFaStep === 'idle' && (
                                        <button onClick={handleSetup2FA} disabled={twoFaLoading}
                                            className="px-4 py-2 rounded-xl bg-[#C9A96E]/10 border border-[#C9A96E]/20 text-[#C9A96E] text-[10px] font-black uppercase tracking-widest hover:bg-[#C9A96E]/20 transition-all disabled:opacity-50">
                                            {twoFaLoading ? '...' : (isRTL ? 'تفعيل' : 'ENABLE')}
                                        </button>
                                    )
                                )}
                            </div>

                            {twoFaMsg && (
                                <div className={`p-3 rounded-xl text-xs text-center ${twoFaMsg.startsWith('✅') ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>
                                    {twoFaMsg}
                                </div>
                            )}

                            {/* QR Code Setup Step */}
                            {twoFaStep === 'setup' && (
                                <div className="space-y-4 border-t border-white/5 pt-6">
                                    <p className="text-xs text-white/50 text-center">
                                        {isRTL ? 'امسح هذا الرمز بتطبيق Google Authenticator أو Authy' : 'Scan with Google Authenticator or Authy'}
                                    </p>
                                    {twoFaQR && (
                                        <div className="flex justify-center">
                                            <img src={twoFaQR} alt="2FA QR" className="w-40 h-40 rounded-2xl border border-white/10 p-2 bg-white" />
                                        </div>
                                    )}
                                    {twoFaSecret && (
                                        <div className="flex items-center gap-2 p-3 bg-white/5 rounded-xl border border-white/10">
                                            <Key className="w-3.5 h-3.5 text-white/30 shrink-0" />
                                            <code className="text-[10px] text-white/50 font-mono flex-1 break-all">{twoFaSecret}</code>
                                            <button onClick={() => navigator.clipboard.writeText(twoFaSecret)}
                                                className="p-1 hover:text-[#C9A96E] text-white/30 transition-colors">
                                                <Copy className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                    )}
                                    <div className="flex gap-2">
                                        <input
                                            type="text" inputMode="numeric" maxLength={6}
                                            value={twoFaCode}
                                            onChange={e => setTwoFaCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                            placeholder="000000"
                                            className="flex-1 text-center text-xl font-black tracking-[0.4em] bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:outline-none focus:border-[#C9A96E]/40 transition-all"
                                        />
                                        <button onClick={handleConfirm2FA} disabled={twoFaLoading || twoFaCode.length < 6}
                                            className="px-6 py-3 rounded-xl bg-[#C9A96E] text-black font-black text-sm disabled:opacity-40 hover:bg-[#b8955b] transition-all">
                                            {twoFaLoading ? '...' : (isRTL ? 'تحقق' : 'VERIFY')}
                                        </button>
                                    </div>
                                </div>
                            )}

                            {/* Backup Codes after enabling */}
                            {twoFaStep === 'done' && twoFaBackupCodes.length > 0 && (
                                <div className="space-y-3 border-t border-white/5 pt-6">
                                    <p className="text-[10px] font-black text-amber-400 uppercase tracking-widest">
                                        {isRTL ? '⚠️ احفظ رموز الاحتياط هذه في مكان آمن' : '⚠️ Save these backup codes safely'}
                                    </p>
                                    <div className="grid grid-cols-2 gap-2">
                                        {twoFaBackupCodes.map((code, i) => (
                                            <div key={i} className="flex items-center gap-2 p-2 bg-white/5 rounded-lg border border-white/10">
                                                <CheckCircle2 className="w-3 h-3 text-emerald-400 shrink-0" />
                                                <code className="text-[10px] font-mono text-white/60">{code}</code>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </section>

                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { motion } from "framer-motion";
import { useState } from "react";
import {
    Bell, Palette, Globe,
    Save, Lock, Eye, EyeOff, Smartphone, Mail, Volume2, Moon, Check, Shield
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useLanguage } from "@/lib/LanguageContext";
import { api } from "@/lib/api-original";

export default function ClientSettingsPage() {
    const { isRTL, lang, toggleLanguage } = useLanguage();
    const [saving, setSaving] = useState(false);
    const [saved, setSaved] = useState(false);

    // 2FA State
    const [twoFactorStatus, setTwoFactorStatus] = useState<any>(null); // To store QR code and secret
    const [twoFactorCode, setTwoFactorCode] = useState('');
    const [twoFactorMessage, setTwoFactorMessage] = useState('');

    const [notifications, setNotifications] = useState({
        email: true,
        sms: false,
        auctionAlerts: true,
        priceDrops: true,
        newMessages: true,
    });

    const [appearance, setAppearance] = useState({
        animations: true,
        soundEffects: false,
    });

    const [passwords, setPasswords] = useState({ current: '', new: '', confirm: '' });
    const [showPwd, setShowPwd] = useState(false);
    const [pwdMessage, setPwdMessage] = useState('');

    const handleSave = async () => {
        setSaving(true);
        try {
            await new Promise(r => setTimeout(r, 800));
            setSaved(true);
            setTimeout(() => setSaved(false), 3000);
        } finally {
            setSaving(false);
        }
    };

    const handlePasswordChange = async (e: React.FormEvent) => {
        e.preventDefault();
        if (passwords.new !== passwords.confirm) {
            setPwdMessage(isRTL ? 'كلمتا المرور غير متطابقتين' : 'Passwords do not match');
            return;
        }
        if (passwords.new.length < 6) {
            setPwdMessage(isRTL ? 'كلمة المرور يجب أن تكون 6 أحرف على الأقل' : 'Password must be at least 6 characters');
            return;
        }
        setSaving(true);
        setPwdMessage('');
        try {
            await api.auth.changePassword({ currentPassword: passwords.current, newPassword: passwords.new });
            setPwdMessage(isRTL ? '✓ تم تغيير كلمة المرور بنجاح' : '✓ Password changed successfully');
            setPasswords({ current: '', new: '', confirm: '' });
        } catch (err: any) {
            const msg = err?.response?.data?.message || err?.message || (isRTL ? 'حدث خطأ، حاول مرة أخرى' : 'An error occurred, try again');
            setPwdMessage(`✗ ${msg}`);
        } finally {
            setSaving(false);
        }
    };

    const handleSetup2FA = async () => {
        try {
            setSaving(true);
            const token = localStorage.getItem('hm_token');
            const res = await fetch('/api/v2/auth/2fa/setup', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await res.json();
            if (data.success) {
                setTwoFactorStatus(data);
                setTwoFactorMessage(isRTL ? 'امسح رمز الاستجابة السريعة (QR) باستخدام تطبيق المصادقة (مثل Google Authenticator).' : 'Scan the QR code with your authenticator app.');
            } else {
                setTwoFactorMessage(data.message || (isRTL ? 'فشل إعداد المصادقة الثنائية' : 'Failed to setup 2FA'));
            }
        } catch (err) {
            setTwoFactorMessage(isRTL ? 'خطأ في الاتصال' : 'Connection error');
        } finally {
            setSaving(false);
        }
    };

    const handleEnable2FA = async () => {
        try {
            setSaving(true);
            const token = localStorage.getItem('hm_token');
            const res = await fetch('/api/v2/auth/2fa/enable', {
                method: 'POST',
                headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ token: twoFactorCode })
            });
            const data = await res.json();
            if (data.success) {
                setTwoFactorMessage(isRTL ? '✓ تم تفعيل المصادقة الثنائية بنجاح!' : '✓ 2FA enabled successfully!');
                setTwoFactorStatus(null);
            } else {
                setTwoFactorMessage(data.message || (isRTL ? 'رمز غير صحيح' : 'Invalid code'));
            }
        } catch (err) {
            setTwoFactorMessage(isRTL ? 'خطأ في الاتصال' : 'Connection error');
        } finally {
            setSaving(false);
        }
    };

    // مكوّن Toggle
    const Toggle = ({ value, onChange }: { value: boolean; onChange: () => void }) => (
        <button
            onClick={onChange}
            className={cn(
                'relative w-11 h-6 rounded-full transition-all duration-300 shrink-0',
                value ? 'bg-[#c9a96e]' : 'bg-white/10'
            )}
        >
            <div className={cn(
                'absolute top-1 w-4 h-4 bg-white rounded-full shadow-md transition-all duration-300',
                value ? (isRTL ? 'right-1' : 'left-6') : (isRTL ? 'right-6' : 'left-1')
            )} />
        </button>
    );

    // مكوّن صف الإعداد
    const SettingRow = ({ icon: Icon, title, subtitle, value, onChange, iconColor = '#c9a96e' }: {
        icon: any; title: string; subtitle?: string; value: boolean; onChange: () => void; iconColor?: string;
    }) => (
        <div className={cn(
            'flex items-center justify-between gap-4 p-4 rounded-xl bg-white/[0.02] hover:bg-white/[0.04] transition-all border border-white/[0.05]',
            isRTL && 'flex-row-reverse text-right'
        )}>
            <div className={cn('flex items-center gap-3', isRTL && 'flex-row-reverse')}>
                <div className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: `${iconColor}15` }}>
                    <Icon className="w-4 h-4" style={{ color: iconColor }} strokeWidth={1.8} />
                </div>
                <div>
                    <div className="text-[13px] font-semibold text-white">{title}</div>
                    {subtitle && <div className="text-[11px] text-white/35 mt-0.5">{subtitle}</div>}
                </div>
            </div>
            <Toggle value={value} onChange={onChange} />
        </div>
    );

    return (
        <div className={cn("min-h-full", isRTL && "rtl")}>
            <div className="px-5 lg:px-8 pt-6 lg:pt-8 pb-8 max-w-2xl mx-auto lg:mx-0">

                {/* Header */}
                <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="mb-7">
                    <p className="text-[11px] text-white/25 font-bold uppercase tracking-[0.3em] mb-1">
                        {isRTL ? 'تخصيص الحساب' : 'Customize Account'}
                    </p>
                    <h1 className="text-2xl lg:text-3xl font-bold text-white">
                        {isRTL ? 'الإعدادات' : 'Settings'}
                    </h1>
                </motion.div>

                {/* Success Banner */}
                {saved && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}
                        className="mb-5 p-4 rounded-xl bg-green-400/10 border border-green-400/20 flex items-center gap-3"
                    >
                        <div className="w-6 h-6 rounded-full bg-green-400/20 flex items-center justify-center shrink-0">
                            <Check className="w-3.5 h-3.5 text-green-400" />
                        </div>
                        <span className="text-[13px] font-semibold text-green-400">
                            {isRTL ? 'تم حفظ الإعدادات بنجاح' : 'Settings saved successfully'}
                        </span>
                    </motion.div>
                )}

                <div className="space-y-5">

                    {/* ─── اللغة ─── */}
                    <motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
                        <div className="rounded-2xl border border-white/[0.06] overflow-hidden">
                            <div className={cn('flex items-center gap-3 px-5 py-4 bg-white/[0.02] border-b border-white/[0.05]', isRTL && 'flex-row-reverse')}>
                                <Globe className="w-4 h-4 text-[#c9a96e]/70" strokeWidth={1.8} />
                                <span className="text-[12px] font-bold text-white/50 uppercase tracking-[0.25em]">
                                    {isRTL ? 'اللغة' : 'Language'}
                                </span>
                            </div>
                            <div className={cn('flex items-center justify-between gap-4 p-4', isRTL && 'flex-row-reverse')}>
                                <div>
                                    <div className="text-[13px] font-semibold text-white">
                                        {isRTL ? 'لغة التطبيق' : 'App Language'}
                                    </div>
                                    <div className="text-[11px] text-white/35 mt-0.5">
                                        {isRTL ? 'العربية / الإنجليزية' : 'Arabic / English'}
                                    </div>
                                </div>
                                <button
                                    onClick={toggleLanguage}
                                    className="px-4 py-2 rounded-lg border border-[#c9a96e]/30 bg-[#c9a96e]/10 text-[#c9a96e] text-[12px] font-black uppercase tracking-wider hover:bg-[#c9a96e]/20 transition-all"
                                >
                                    {lang === 'AR' ? 'EN' : 'AR'}
                                </button>
                            </div>
                        </div>
                    </motion.section>

                    {/* ─── الإشعارات ─── */}
                    <motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                        <div className="rounded-2xl border border-white/[0.06] overflow-hidden">
                            <div className={cn('flex items-center gap-3 px-5 py-4 bg-white/[0.02] border-b border-white/[0.05]', isRTL && 'flex-row-reverse')}>
                                <Bell className="w-4 h-4 text-[#c9a96e]/70" strokeWidth={1.8} />
                                <span className="text-[12px] font-bold text-white/50 uppercase tracking-[0.25em]">
                                    {isRTL ? 'الإشعارات' : 'Notifications'}
                                </span>
                            </div>
                            <div className="p-3 space-y-2">
                                <SettingRow
                                    icon={Mail}
                                    title={isRTL ? 'إشعارات البريد' : 'Email Notifications'}
                                    subtitle={isRTL ? 'تحديثات عبر البريد الإلكتروني' : 'Updates via email'}
                                    value={notifications.email}
                                    onChange={() => setNotifications(p => ({ ...p, email: !p.email }))}
                                />
                                <SettingRow
                                    icon={Smartphone}
                                    title={isRTL ? 'رسائل SMS' : 'SMS Messages'}
                                    subtitle={isRTL ? 'تنبيهات عبر الجوال' : 'Text message alerts'}
                                    value={notifications.sms}
                                    onChange={() => setNotifications(p => ({ ...p, sms: !p.sms }))}
                                />
                                <SettingRow
                                    icon={Bell}
                                    title={isRTL ? 'تنبيهات المزادات' : 'Auction Alerts'}
                                    subtitle={isRTL ? 'عند بدء أو انتهاء مزاد' : 'Auction start & end alerts'}
                                    value={notifications.auctionAlerts}
                                    onChange={() => setNotifications(p => ({ ...p, auctionAlerts: !p.auctionAlerts }))}
                                />
                                <SettingRow
                                    icon={Bell}
                                    title={isRTL ? 'تنبيهات انخفاض الأسعار' : 'Price Drop Alerts'}
                                    subtitle={isRTL ? 'عند تخفيض سعر سيارة محفوظة' : 'When saved car price drops'}
                                    value={notifications.priceDrops}
                                    onChange={() => setNotifications(p => ({ ...p, priceDrops: !p.priceDrops }))}
                                />
                                <SettingRow
                                    icon={Mail}
                                    title={isRTL ? 'رسائل جديدة' : 'New Messages'}
                                    subtitle={isRTL ? 'عند وصول رسالة جديدة' : 'When you receive a message'}
                                    value={notifications.newMessages}
                                    onChange={() => setNotifications(p => ({ ...p, newMessages: !p.newMessages }))}
                                />
                            </div>
                        </div>
                    </motion.section>

                    {/* ─── المظهر ─── */}
                    <motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                        <div className="rounded-2xl border border-white/[0.06] overflow-hidden">
                            <div className={cn('flex items-center gap-3 px-5 py-4 bg-white/[0.02] border-b border-white/[0.05]', isRTL && 'flex-row-reverse')}>
                                <Palette className="w-4 h-4 text-[#c9a96e]/70" strokeWidth={1.8} />
                                <span className="text-[12px] font-bold text-white/50 uppercase tracking-[0.25em]">
                                    {isRTL ? 'المظهر' : 'Appearance'}
                                </span>
                            </div>
                            <div className="p-3 space-y-2">
                                <SettingRow
                                    icon={Moon}
                                    title={isRTL ? 'الحركات والتأثيرات' : 'Animations'}
                                    subtitle={isRTL ? 'تأثيرات بصرية عند التنقل' : 'Visual effects while navigating'}
                                    value={appearance.animations}
                                    onChange={() => setAppearance(p => ({ ...p, animations: !p.animations }))}
                                    iconColor="#a78bfa"
                                />
                                <SettingRow
                                    icon={Volume2}
                                    title={isRTL ? 'المؤثرات الصوتية' : 'Sound Effects'}
                                    subtitle={isRTL ? 'أصوات عند الإجراءات' : 'Audio feedback on actions'}
                                    value={appearance.soundEffects}
                                    onChange={() => setAppearance(p => ({ ...p, soundEffects: !p.soundEffects }))}
                                    iconColor="#a78bfa"
                                />
                            </div>
                        </div>
                    </motion.section>

                    {/* ─── تغيير كلمة المرور ─── */}
                    <motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                        <div className="rounded-2xl border border-white/[0.06] overflow-hidden">
                            <div className={cn('flex items-center gap-3 px-5 py-4 bg-white/[0.02] border-b border-white/[0.05]', isRTL && 'flex-row-reverse')}>
                                <Lock className="w-4 h-4 text-[#c9a96e]/70" strokeWidth={1.8} />
                                <span className="text-[12px] font-bold text-white/50 uppercase tracking-[0.25em]">
                                    {isRTL ? 'تغيير كلمة المرور' : 'Change Password'}
                                </span>
                            </div>
                            <div className="p-5">
                                {pwdMessage && (
                                    <div className={cn(
                                        'mb-4 p-3.5 rounded-xl text-[12px] font-semibold flex items-center gap-2',
                                        pwdMessage.includes('✓')
                                            ? 'bg-green-400/10 border border-green-400/20 text-green-400'
                                            : 'bg-red-400/10 border border-red-400/20 text-red-400'
                                    )}>
                                        {pwdMessage}
                                    </div>
                                )}
                                <form onSubmit={handlePasswordChange} className="space-y-4">
                                    {[
                                        { key: 'current', label: isRTL ? 'كلمة المرور الحالية' : 'Current Password' },
                                        { key: 'new', label: isRTL ? 'كلمة المرور الجديدة' : 'New Password' },
                                        { key: 'confirm', label: isRTL ? 'تأكيد كلمة المرور' : 'Confirm Password' },
                                    ].map((field) => (
                                        <div key={field.key}>
                                            <label className="block text-[11px] font-semibold text-white/40 mb-2">
                                                {field.label}
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type={showPwd ? 'text' : 'password'}
                                                    value={passwords[field.key as keyof typeof passwords]}
                                                    onChange={e => setPasswords(p => ({ ...p, [field.key]: e.target.value }))}
                                                    className="w-full bg-white/[0.03] border border-white/[0.08] rounded-xl py-3.5 px-4 text-[14px] text-white focus:outline-none focus:border-[#c9a96e]/40 transition-all placeholder:text-white/20"
                                                    placeholder="••••••••"
                                                />
                                                {field.key === 'confirm' && (
                                                    <button
                                                        type="button"
                                                        onClick={() => setShowPwd(v => !v)}
                                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-white/25 hover:text-white/60 transition-colors"
                                                    >
                                                        {showPwd ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    <button
                                        type="submit"
                                        disabled={saving}
                                        className="w-full py-3.5 rounded-xl bg-white/[0.05] border border-white/10 text-white/70 hover:text-white hover:bg-white/[0.08] font-semibold text-[13px] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                                    >
                                        <Lock className="w-4 h-4" strokeWidth={1.8} />
                                        {isRTL ? 'تحديث كلمة المرور' : 'Update Password'}
                                    </button>
                                </form>
                            </div>
                        </div>
                    </motion.section>

                    {/* ─── المصادقة الثنائية (2FA) ─── */}
                    <motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.22 }}>
                        <div className="rounded-2xl border border-white/[0.06] overflow-hidden">
                            <div className={cn('flex items-center gap-3 px-5 py-4 bg-white/[0.02] border-b border-white/[0.05]', isRTL && 'flex-row-reverse')}>
                                <Shield className="w-4 h-4 text-[#c9a96e]/70" strokeWidth={1.8} />
                                <span className="text-[12px] font-bold text-white/50 uppercase tracking-[0.25em]">
                                    {isRTL ? 'المصادقة الثنائية (2FA)' : 'Two-Factor Authentication'}
                                </span>
                            </div>
                            <div className="p-5">
                                {twoFactorMessage && (
                                    <div className={cn(
                                        'mb-4 p-3.5 rounded-xl text-[12px] font-semibold flex items-center gap-2',
                                        twoFactorMessage.includes('✓')
                                            ? 'bg-green-400/10 border border-green-400/20 text-green-400'
                                            : 'bg-red-400/10 border border-red-400/20 text-red-400'
                                    )}>
                                        {twoFactorMessage}
                                    </div>
                                )}
                                
                                {!twoFactorStatus ? (
                                    <button
                                        onClick={handleSetup2FA}
                                        disabled={saving}
                                        className="w-full py-3.5 rounded-xl bg-white/[0.05] border border-white/10 text-white/70 hover:text-white hover:bg-white/[0.08] font-semibold text-[13px] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                                    >
                                        <Shield className="w-4 h-4" strokeWidth={1.8} />
                                        {isRTL ? 'إعداد المصادقة الثنائية لحماية أقوى' : 'Setup 2FA for Extra Security'}
                                    </button>
                                ) : (
                                    <div className="flex flex-col items-center space-y-4">
                                        <img src={twoFactorStatus.qrCode} alt="2FA QR Code" className="w-40 h-40 rounded-xl border border-white/20 p-2 bg-white" />
                                        <p className="text-sm text-gray-400">Secret: <span className="font-mono text-white">{twoFactorStatus.secret}</span></p>
                                        <div className="w-full relative mt-4">
                                            <input
                                                type="text"
                                                value={twoFactorCode}
                                                onChange={e => setTwoFactorCode(e.target.value)}
                                                className="w-full bg-white/[0.03] border border-white/[0.08] rounded-xl py-3.5 px-4 text-center text-[18px] tracking-[0.5em] font-mono text-white focus:outline-none focus:border-[#c9a96e]/40 transition-all placeholder:text-white/20"
                                                placeholder="123456"
                                                maxLength={6}
                                            />
                                        </div>
                                        <button
                                            onClick={handleEnable2FA}
                                            disabled={saving || twoFactorCode.length < 6}
                                            className="w-full py-3.5 rounded-xl bg-[#c9a96e] text-black font-bold text-[13px] transition-all disabled:opacity-50 flex items-center justify-center gap-2 mt-2"
                                        >
                                            {isRTL ? 'تأكيد التفعيل' : 'Confirm Enable'}
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </motion.section>

                    {/* ─── زر الحفظ ─── */}
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.25 }}>
                        <button
                            onClick={handleSave}
                            disabled={saving}
                            className="w-full py-4 rounded-2xl bg-[#c9a96e] text-black font-bold text-[14px] tracking-wide transition-all disabled:opacity-50 flex items-center justify-center gap-2.5 hover:bg-[#d4b57a] active:scale-[0.98]"
                        >
                            {saving ? (
                                <motion.div
                                    animate={{ rotate: 360 }}
                                    transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}
                                    className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full"
                                />
                            ) : (
                                <>
                                    <Save className="w-4.5 h-4.5" strokeWidth={2} />
                                    {isRTL ? 'حفظ الإعدادات' : 'Save Settings'}
                                </>
                            )}
                        </button>
                    </motion.div>

                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bell, Plus, Trash2, Edit3, ChevronLeft, ChevronRight,
    Zap, Target, Check, X, AlertCircle, ToggleLeft, ToggleRight,
    Filter, Sparkles, Clock, TrendingUp
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useLanguage } from '@/lib/LanguageContext';
import { useAuth } from '@/lib/AuthContext';
import { api } from '@/lib/api-original';
import { useRouter } from 'next/navigation';
import Navbar from '@/components/Navbar';

// ===================== Types =====================
interface SmartAlertCriteria {
    make?: string;
    model?: string;
    yearMin?: number | null;
    yearMax?: number | null;
    priceMin?: number | null;
    priceMax?: number | null;
    fuelType?: string;
    transmission?: string;
    category?: string;
    condition?: string;
    listingType?: string;
}

interface SmartAlert {
    _id: string;
    name: string;
    isActive: boolean;
    criteria: SmartAlertCriteria;
    channels: { inApp: boolean; email: boolean };
    frequency: 'immediate' | 'daily';
    triggerCount: number;
    lastTriggeredAt?: string;
    createdAt: string;
}

interface FormData extends SmartAlertCriteria {
    name: string;
    inApp: boolean;
    email: boolean;
    frequency: 'immediate' | 'daily';
}

const EMPTY_FORM: FormData = {
    name: '',
    make: '',
    model: '',
    yearMin: null,
    yearMax: null,
    priceMin: null,
    priceMax: null,
    fuelType: '',
    transmission: '',
    category: '',
    condition: '',
    listingType: '',
    inApp: true,
    email: false,
    frequency: 'immediate'
};

// ===================== Form Field Components =====================
type FieldSetter = (key: keyof FormData, value: string | boolean | number | null) => void;

const InputField = ({ label, field, type = 'text', placeholder = '', form, set }: {
    label: string; field: keyof FormData; type?: string; placeholder?: string;
    form: FormData; set: FieldSetter;
}) => (
    <div>
        <label className="block text-[10px] font-black uppercase tracking-[0.25em] text-white/40 mb-2">{label}</label>
        <input
            type={type}
            value={(form[field] as string) || ''}
            onChange={e => set(field, type === 'number' ? (e.target.value ? +e.target.value : null) : e.target.value)}
            placeholder={placeholder}
            className="w-full bg-white/[0.03] border border-white/10 rounded-xl px-4 py-3 text-sm text-white font-medium focus:outline-none focus:border-cyan-400/40 transition-all placeholder:text-white/20"
        />
    </div>
);

const SelectField = ({ label, field, options, form, set, isRTL }: {
    label: string; field: keyof FormData;
    options: { value: string; label: string }[];
    form: FormData; set: FieldSetter;
    isRTL: boolean;
}) => (
    <div>
        <label className="block text-[10px] font-black uppercase tracking-[0.25em] text-white/40 mb-2">{label}</label>
        <select
            value={(form[field] as string) || ''}
            onChange={e => set(field, e.target.value)}
            aria-label={label}
            title={label}
            className="w-full bg-[#0a0a0f] border border-white/10 rounded-xl px-4 py-3 text-sm text-white font-medium focus:outline-none focus:border-cyan-400/40 transition-all"
        >
            <option value="">— {isRTL ? 'الكل' : 'Any'} —</option>
            {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
        </select>
    </div>
);

const ToggleField = ({ field, label, color = 'bg-cyan-400', form, set }: { 
    field: 'inApp' | 'email'; label: string; color?: string;
    form: FormData; set: FieldSetter;
}) => (
    <div className="flex items-center justify-between p-4 rounded-xl bg-white/[0.02] border border-white/5">
        <span className="text-[11px] font-bold text-white/60">{label}</span>
        <button
            type="button"
            aria-label={label}
            title={label}
            onClick={() => set(field, !form[field])}
            className={cn(
                "w-11 h-6 rounded-full transition-all relative",
                form[field] ? `${color} shadow-[0_0_12px_rgba(0,240,255,0.3)]` : "bg-white/10"
            )}
        >
            <div className={cn(
                "absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-all",
                form[field] ? "left-6" : "left-1"
            )} />
        </button>
    </div>
);

// ===================== Badge Component =====================
const CriteriaBadge = ({ label, value }: { label: string; value?: string | number | null }) => {
    if (!value && value !== 0) return null;
    return (
        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-[10px] font-bold text-white/60">
            <span className="text-white/30">{label}:</span>
            <span className="text-white/80">{value}</span>
        </span>
    );
};

// ===================== Modal Component =====================
const AlertModal = ({
    open, onClose, onSave, initial, isRTL, loading
}: {
    open: boolean;
    onClose: () => void;
    onSave: (data: FormData) => Promise<void>;
    initial?: SmartAlert | null;
    isRTL: boolean;
    loading: boolean;
}) => {
    const [form, setForm] = useState<FormData>(() => initial ? {
        name: initial.name,
        make: initial.criteria.make || '',
        model: initial.criteria.model || '',
        yearMin: initial.criteria.yearMin || null,
        yearMax: initial.criteria.yearMax || null,
        priceMin: initial.criteria.priceMin || null,
        priceMax: initial.criteria.priceMax || null,
        fuelType: initial.criteria.fuelType || '',
        transmission: initial.criteria.transmission || '',
        category: initial.criteria.category || '',
        condition: initial.criteria.condition || '',
        listingType: initial.criteria.listingType || '',
        inApp: initial.channels?.inApp !== false,
        email: initial.channels?.email === true,
        frequency: initial.frequency || 'immediate'
    } : EMPTY_FORM);
    const [error, setError] = useState('');

    const set: FieldSetter = (key, value) => setForm(p => ({ ...p, [key]: value }));

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        try {
            await onSave(form);
        } catch (err: unknown) {
            if (err instanceof Error) {
                setError(err.message || 'حدث خطأ');
            } else {
                setError('حدث خطأ');
            }
        }
    };

    if (!open) return null;

    return (
        <AnimatePresence>
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 z-50 flex items-center justify-center p-4"
                onClick={onClose}
            >
                <div className="absolute inset-0 bg-black/80 backdrop-blur-md" />
                <motion.div
                    initial={{ scale: 0.9, opacity: 0, y: 20 }}
                    animate={{ scale: 1, opacity: 1, y: 0 }}
                    exit={{ scale: 0.9, opacity: 0, y: 20 }}
                    transition={{ type: 'spring', stiffness: 300, damping: 30 }}
                    className="relative w-full max-w-2xl bg-[#09090f] border border-white/10 rounded-3xl overflow-hidden shadow-2xl"
                    onClick={e => e.stopPropagation()}
                >
                    {/* Header */}
                    <div className="relative p-8 border-b border-white/5">
                        <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/5 to-violet-500/5" />
                        <div className="relative flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="p-2.5 rounded-xl bg-cyan-400/10 border border-cyan-400/20">
                                    <Target className="w-5 h-5 text-cyan-400" />
                                </div>
                                <div>
                                    <h3 className="font-black text-white text-lg">
                                        {initial
                                            ? (isRTL ? 'تعديل التنبيه' : 'Edit Alert')
                                            : (isRTL ? 'تنبيه ذكي جديد' : 'New Smart Alert')}
                                    </h3>
                                    <p className="text-[10px] text-white/30 font-bold uppercase tracking-widest mt-0.5">
                                        {isRTL ? 'حدد معايير السيارة التي تبحث عنها' : 'Set your car search criteria'}
                                    </p>
                                </div>
                            </div>
                            <button onClick={onClose} aria-label="إغلاق" title="إغلاق" className="p-2 rounded-xl hover:bg-white/5 text-white/30 hover:text-white transition-all">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {/* Form */}
                    <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[65vh] overflow-y-auto">
                        {/* Alert Name */}
                        <div>
                            <label className="block text-[10px] font-black uppercase tracking-[0.25em] text-cyan-400/70 mb-2">
                                {isRTL ? 'اسم التنبيه *' : 'Alert Name *'}
                            </label>
                            <input
                                type="text"
                                value={form.name}
                                onChange={e => set('name', e.target.value)}
                                placeholder={isRTL ? 'مثال: أبحث عن تويوتا كورولا' : 'e.g. Looking for Toyota Corolla'}
                                required
                                className="w-full bg-cyan-400/5 border border-cyan-400/20 rounded-xl px-4 py-3.5 text-sm text-white font-medium focus:outline-none focus:border-cyan-400/50 transition-all placeholder:text-white/20"
                            />
                        </div>

                        {/* Divider */}
                        <div className="flex items-center gap-3">
                            <div className="flex-1 h-px bg-white/5" />
                            <span className="text-[10px] font-black text-white/20 uppercase tracking-widest flex items-center gap-2">
                                <Filter className="w-3 h-3" />
                                {isRTL ? 'معايير البحث' : 'Search Criteria'}
                            </span>
                            <div className="flex-1 h-px bg-white/5" />
                        </div>

                        {/* Make & Model */}
                        <div className="grid grid-cols-2 gap-4">
                            <InputField label={isRTL ? 'الماركة' : 'Make'} field="make" placeholder="Toyota, BMW..." form={form} set={set} />
                            <InputField label={isRTL ? 'الموديل' : 'Model'} field="model" placeholder="Corolla, X5..." form={form} set={set} />
                        </div>

                        {/* Year Range */}
                        <div className="grid grid-cols-2 gap-4">
                            <InputField label={isRTL ? 'سنة من' : 'Year From'} field="yearMin" type="number" placeholder="2018" form={form} set={set} />
                            <InputField label={isRTL ? 'سنة إلى' : 'Year To'} field="yearMax" type="number" placeholder="2024" form={form} set={set} />
                        </div>

                        {/* Price Range */}
                        <div className="grid grid-cols-2 gap-4">
                            <InputField label={isRTL ? 'السعر من (ر.س)' : 'Price From (SAR)'} field="priceMin" type="number" placeholder="50000" form={form} set={set} />
                            <InputField label={isRTL ? 'السعر إلى (ر.س)' : 'Price To (SAR)'} field="priceMax" type="number" placeholder="200000" form={form} set={set} />
                        </div>

                        {/* Dropdowns */}
                        <div className="grid grid-cols-2 gap-4">
                            <SelectField label={isRTL ? 'نوع الوقود' : 'Fuel Type'} field="fuelType" options={[
                                { value: 'Petrol', label: isRTL ? 'بنزين' : 'Petrol' },
                                { value: 'Diesel', label: isRTL ? 'ديزل' : 'Diesel' },
                                { value: 'Electric', label: isRTL ? 'كهربائي' : 'Electric' },
                                { value: 'Hybrid', label: isRTL ? 'هجين' : 'Hybrid' },
                            ]} form={form} set={set} isRTL={isRTL} />
                            <SelectField label={isRTL ? 'ناقل الحركة' : 'Transmission'} field="transmission" options={[
                                { value: 'Automatic', label: isRTL ? 'أوتوماتيك' : 'Automatic' },
                                { value: 'Manual', label: isRTL ? 'يدوي' : 'Manual' },
                            ]} form={form} set={set} isRTL={isRTL} />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <SelectField label={isRTL ? 'الفئة' : 'Category'} field="category" options={[
                                { value: 'sedan', label: isRTL ? 'سيدان' : 'Sedan' },
                                { value: 'suv', label: 'SUV' },
                                { value: 'truck', label: isRTL ? 'شاحنة' : 'Truck' },
                                { value: 'coupe', label: 'Coupe' },
                                { value: 'van', label: 'Van' },
                            ]} form={form} set={set} isRTL={isRTL} />
                            <SelectField label={isRTL ? 'الحالة' : 'Condition'} field="condition" options={[
                                { value: 'excellent', label: isRTL ? 'ممتازة' : 'Excellent' },
                                { value: 'good', label: isRTL ? 'جيدة' : 'Good' },
                                { value: 'fair', label: isRTL ? 'مقبولة' : 'Fair' },
                            ]} form={form} set={set} isRTL={isRTL} />
                        </div>

                        <SelectField label={isRTL ? 'نوع الإعلان' : 'Listing Type'} field="listingType" options={[
                            { value: 'store', label: isRTL ? 'معرض' : 'Store' },
                            { value: 'auction', label: isRTL ? 'مزاد' : 'Auction' },
                        ]} form={form} set={set} isRTL={isRTL} />

                        {/* Divider */}
                        <div className="flex items-center gap-3">
                            <div className="flex-1 h-px bg-white/5" />
                            <span className="text-[10px] font-black text-white/20 uppercase tracking-widest flex items-center gap-2">
                                <Bell className="w-3 h-3" />
                                {isRTL ? 'قنوات التنبيه' : 'Alert Channels'}
                            </span>
                            <div className="flex-1 h-px bg-white/5" />
                        </div>

                        <div className="space-y-3">
                            <ToggleField field="inApp" label={isRTL ? '🔔 إشعار داخل التطبيق' : '🔔 In-App Notification'} color="bg-cyan-400" form={form} set={set} />
                            <ToggleField field="email" label={isRTL ? '📧 إشعار عبر البريد الإلكتروني' : '📧 Email Notification'} color="bg-violet-400" form={form} set={set} />
                        </div>

                        {/* Frequency */}
                        <div>
                            <label className="block text-[10px] font-black uppercase tracking-[0.25em] text-white/40 mb-3">
                                {isRTL ? 'تكرار الإشعار' : 'Notification Frequency'}
                            </label>
                            <div className="grid grid-cols-2 gap-3">
                                {[
                                    { value: 'immediate', label: isRTL ? '⚡ فوري' : '⚡ Immediate', sub: isRTL ? 'تنبيه فور إضافة سيارة' : 'Alert when car is added' },
                                    { value: 'daily', label: isRTL ? '📅 يومي' : '📅 Daily', sub: isRTL ? 'ملخص يومي' : 'Daily summary' },
                                ].map(opt => (
                                    <button
                                        key={opt.value}
                                        type="button"
                                        onClick={() => set('frequency', opt.value)}
                                        className={cn(
                                            "p-4 rounded-xl border text-left transition-all",
                                            form.frequency === opt.value
                                                ? "border-cyan-400/40 bg-cyan-400/10 text-cyan-400"
                                                : "border-white/5 bg-white/[0.02] text-white/40 hover:border-white/10"
                                        )}
                                    >
                                        <div className="text-[12px] font-black">{opt.label}</div>
                                        <div className="text-[10px] opacity-60 mt-0.5">{opt.sub}</div>
                                    </button>
                                ))}
                            </div>
                        </div>

                        {error && (
                            <div className="p-4 rounded-xl bg-red-400/10 border border-red-400/20 text-red-400 text-[11px] font-bold flex items-center gap-2">
                                <AlertCircle className="w-4 h-4 shrink-0" />
                                {error}
                            </div>
                        )}
                    </form>

                    {/* Footer */}
                    <div className="p-8 pt-0 flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 py-4 rounded-xl border border-white/10 text-white/40 text-[11px] font-black uppercase tracking-widest hover:bg-white/5 transition-all"
                        >
                            {isRTL ? 'إلغاء' : 'Cancel'}
                        </button>
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={handleSubmit}
                            disabled={loading}
                            className="flex-1 py-4 rounded-xl bg-cyan-400 text-black text-[11px] font-black uppercase tracking-widest shadow-[0_0_30px_rgba(0,240,255,0.3)] hover:shadow-[0_0_40px_rgba(0,240,255,0.5)] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            {loading ? (
                                <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 0.8, ease: 'linear' }}
                                    className="w-4 h-4 border-2 border-black border-t-transparent rounded-full" />
                            ) : (
                                <>
                                    <Check className="w-4 h-4" />
                                    {initial ? (isRTL ? 'حفظ التعديلات' : 'Save Changes') : (isRTL ? 'إنشاء التنبيه' : 'Create Alert')}
                                </>
                            )}
                        </motion.button>
                    </div>
                </motion.div>
            </motion.div>
        </AnimatePresence>
    );
};

// ===================== Alert Card =====================
const AlertCard = ({
    alert, onToggle, onEdit, onDelete, isRTL
}: {
    alert: SmartAlert;
    onToggle: () => void;
    onEdit: () => void;
    onDelete: () => void;
    isRTL: boolean;
}) => {
    const { criteria } = alert;

    const formatDate = (d?: string) => {
        if (!d) return null;
        return new Date(d).toLocaleDateString(isRTL ? 'ar-SA' : 'en-US', { month: 'short', day: 'numeric' });
    };

    return (
        <motion.div
            layout
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className={cn(
                "relative group rounded-2xl border p-6 transition-all duration-300",
                alert.isActive
                    ? "border-cyan-400/20 bg-white/[0.02] hover:border-cyan-400/30 hover:bg-white/[0.03]"
                    : "border-white/5 bg-white/[0.01] opacity-60"
            )}
        >
            {/* Active glow */}
            {alert.isActive && (
                <div className="absolute -inset-px rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none bg-gradient-to-br from-cyan-400/5 to-violet-400/5" />
            )}

            <div className="relative">
                {/* Header Row */}
                <div className="flex items-start justify-between gap-4 mb-4">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                        <div className={cn(
                            "p-2.5 rounded-xl shrink-0 transition-colors",
                            alert.isActive ? "bg-cyan-400/10 text-cyan-400" : "bg-white/5 text-white/20"
                        )}>
                            <Target className="w-4 h-4" />
                        </div>
                        <div className="min-w-0 flex-1">
                            <h3 className="font-black text-white text-[13px] truncate">{alert.name}</h3>
                            <div className="flex items-center gap-3 mt-0.5">
                                <span className={cn(
                                    "text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full",
                                    alert.isActive
                                        ? "bg-cyan-400/10 text-cyan-400"
                                        : "bg-white/5 text-white/20"
                                )}>
                                    {alert.isActive ? (isRTL ? 'نشط' : 'ACTIVE') : (isRTL ? 'متوقف' : 'PAUSED')}
                                </span>
                                <span className="text-[9px] text-white/20 uppercase font-bold tracking-widest">
                                    {alert.frequency === 'immediate' ? (isRTL ? 'فوري' : 'INSTANT') : (isRTL ? 'يومي' : 'DAILY')}
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-2 shrink-0">
                        <button
                            onClick={onToggle}
                            className={cn(
                                "p-2 rounded-xl transition-all",
                                alert.isActive
                                    ? "text-cyan-400 hover:bg-cyan-400/10"
                                    : "text-white/20 hover:bg-white/5 hover:text-white/40"
                            )}
                            title={alert.isActive ? 'إيقاف' : 'تفعيل'}
                        >
                            {alert.isActive
                                ? <ToggleRight className="w-5 h-5" />
                                : <ToggleLeft className="w-5 h-5" />}
                        </button>
                        <button
                            onClick={onEdit}
                            className="p-2 rounded-xl text-white/20 hover:text-white hover:bg-white/5 transition-all"
                            title="تعديل"
                        >
                            <Edit3 className="w-4 h-4" />
                        </button>
                        <button
                            onClick={onDelete}
                            className="p-2 rounded-xl text-white/20 hover:text-red-400 hover:bg-red-400/10 transition-all"
                            title="حذف"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                {/* Criteria Badges */}
                <div className="flex flex-wrap gap-1.5 mb-4">
                    <CriteriaBadge label={isRTL ? 'ماركة' : 'Make'} value={criteria.make} />
                    <CriteriaBadge label={isRTL ? 'موديل' : 'Model'} value={criteria.model} />
                    <CriteriaBadge label={isRTL ? 'السنة' : 'Year'} value={
                        criteria.yearMin && criteria.yearMax
                            ? `${criteria.yearMin} - ${criteria.yearMax}`
                            : criteria.yearMin || criteria.yearMax
                    } />
                    <CriteriaBadge label={isRTL ? 'السعر' : 'Price'} value={
                        criteria.priceMin && criteria.priceMax
                            ? `${criteria.priceMin?.toLocaleString()} - ${criteria.priceMax?.toLocaleString()}`
                            : criteria.priceMin
                                ? `${criteria.priceMin?.toLocaleString()}+`
                                : criteria.priceMax
                                    ? `≤ ${criteria.priceMax?.toLocaleString()}`
                                    : null
                    } />
                    <CriteriaBadge label={isRTL ? 'وقود' : 'Fuel'} value={criteria.fuelType} />
                    <CriteriaBadge label={isRTL ? 'ناقل' : 'Trans'} value={criteria.transmission} />
                    <CriteriaBadge label={isRTL ? 'فئة' : 'Cat'} value={criteria.category} />
                    <CriteriaBadge label={isRTL ? 'حالة' : 'Cond'} value={criteria.condition} />
                    <CriteriaBadge label={isRTL ? 'نوع' : 'Type'} value={criteria.listingType} />
                </div>

                {/* Stats */}
                <div className="flex items-center gap-4 pt-4 border-t border-white/5">
                    <div className="flex items-center gap-1.5 text-white/30">
                        <Zap className="w-3 h-3" />
                        <span className="text-[10px] font-bold">
                            {alert.triggerCount} {isRTL ? 'إشعار' : 'alerts'}
                        </span>
                    </div>
                    {alert.lastTriggeredAt && (
                        <div className="flex items-center gap-1.5 text-white/30">
                            <Clock className="w-3 h-3" />
                            <span className="text-[10px] font-bold">
                                {isRTL ? 'آخر إشعار:' : 'Last:'} {formatDate(alert.lastTriggeredAt)}
                            </span>
                        </div>
                    )}
                    <div className="flex items-center gap-1.5 text-white/20 mr-auto">
                        {alert.channels?.inApp && <span title="In-App">🔔</span>}
                        {alert.channels?.email && <span title="Email">📧</span>}
                    </div>
                </div>
            </div>
        </motion.div>
    );
};

// ===================== Main Page =====================
export default function SmartAlertsPage() {
    const router = useRouter();
    const { isRTL } = useLanguage();
    const { user, isLoading: authLoading } = useAuth();

    // [[FIX]] Auth guard — redirect to login if not authenticated
    useEffect(() => {
        if (!authLoading && !user) {
            router.replace('/login?redirect=/client/smart-alerts');
        }
    }, [user, authLoading, router]);

    const [alerts, setAlerts] = useState<SmartAlert[]>([]);
    const [stats, setStats] = useState({ total: 0, active: 0, totalTriggers: 0 });
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [modalOpen, setModalOpen] = useState(false);
    const [editAlert, setEditAlert] = useState<SmartAlert | null>(null);
    const [toast, setToast] = useState<{ msg: string; type: 'success' | 'error' } | null>(null);
    const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);

    const showToast = (msg: string, type: 'success' | 'error' = 'success') => {
        setToast({ msg, type });
        setTimeout(() => setToast(null), 3500);
    };

    const loadData = useCallback(async () => {
        try {
            setLoading(true);
            const [alertsRes, statsRes] = await Promise.all([
                api.smartAlerts.list(),
                api.smartAlerts.stats()
            ]);
            setAlerts(alertsRes.data || []);
            setStats(statsRes.data || { total: 0, active: 0, totalTriggers: 0 });
        } catch {
            showToast(isRTL ? 'تعذّر تحميل التنبيهات' : 'Failed to load alerts', 'error');
        } finally {
            setLoading(false);
        }
    }, [isRTL]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (form: FormData) => {
        setSaving(true);
        try {
            if (editAlert) {
                await api.smartAlerts.update(editAlert._id, {
                    name: form.name,
                    frequency: form.frequency,
                    channels: { inApp: form.inApp, email: form.email },
                    criteria: {
                        make: form.make, model: form.model,
                        yearMin: form.yearMin, yearMax: form.yearMax,
                        priceMin: form.priceMin, priceMax: form.priceMax,
                        fuelType: form.fuelType, transmission: form.transmission,
                        category: form.category, condition: form.condition,
                        listingType: form.listingType
                    }
                });
                showToast(isRTL ? '✓ تم تحديث التنبيه' : '✓ Alert updated');
            } else {
                await api.smartAlerts.create(form as unknown as Record<string, unknown>);
                showToast(isRTL ? '✓ تم إنشاء التنبيه الذكي!' : '✓ Smart alert created!');
            }
            setModalOpen(false);
            setEditAlert(null);
            await loadData();
        } finally {
            setSaving(false);
        }
    };

    const handleToggle = async (id: string) => {
        try {
            const res = await api.smartAlerts.toggle(id);
            setAlerts(prev => prev.map(a => a._id === id ? { ...a, isActive: res.data.isActive } : a));
            showToast(res.message || (isRTL ? 'تم التحديث' : 'Updated'));
        } catch {
            showToast(isRTL ? 'حدث خطأ' : 'Error occurred', 'error');
        }
    };

    const handleDelete = async (id: string) => {
        try {
            await api.smartAlerts.delete(id);
            setAlerts(prev => prev.filter(a => a._id !== id));
            showToast(isRTL ? '✓ تم حذف التنبيه' : '✓ Alert deleted');
            setDeleteConfirm(null);
            await loadData();
        } catch {
            showToast(isRTL ? 'حدث خطأ في الحذف' : 'Delete error', 'error');
        }
    };

    return (
        <div className="relative min-h-screen text-white font-sans" dir={isRTL ? 'rtl' : 'ltr'}>

            {/* Background */}
            <div className="fixed inset-0 pointer-events-none">
                <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_rgba(0,240,255,0.04),_transparent_60%)]" />
                <div className="absolute top-1/3 right-1/4 w-96 h-96 rounded-full bg-violet-500/5 blur-3xl" />
                <div className="absolute bottom-1/3 left-1/4 w-96 h-96 rounded-full bg-cyan-500/5 blur-3xl" />
            </div>

            <main className="relative z-10 pt-6 pb-8 px-5 lg:px-8 max-w-4xl">

                {/* Back */}
                <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="mb-10">
                    <button
                        onClick={() => router.back()}
                        title={isRTL ? 'رجوع' : 'Back'}
                        aria-label={isRTL ? 'رجوع' : 'Back'}
                        className="inline-flex items-center justify-center w-11 h-11 rounded-xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-white/10 transition-all group"
                    >
                        {isRTL ? <ChevronRight className="w-5 h-5" /> : <ChevronLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />}
                    </button>
                </motion.div>

                {/* Header */}
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="mb-12">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                        <div className="flex items-center gap-5">
                            <div className="relative">
                                <div className="p-4 rounded-2xl bg-cyan-400/10 border border-cyan-400/20">
                                    <Sparkles className="w-8 h-8 text-cyan-400" />
                                </div>
                                <motion.div
                                    animate={{ scale: [1, 1.3, 1], opacity: [0.5, 1, 0.5] }}
                                    transition={{ repeat: Infinity, duration: 2 }}
                                    className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-cyan-400"
                                />
                            </div>
                            <div>
                                <h1 className="text-4xl md:text-5xl font-black uppercase tracking-tighter bg-gradient-to-r from-white to-cyan-400 bg-clip-text text-transparent">
                                    {isRTL ? 'تنبيهاتي الذكية' : 'Smart Alerts'}
                                </h1>
                                <p className="text-white/30 text-[11px] uppercase tracking-[0.3em] mt-1 font-bold">
                                    {isRTL ? 'احصل على إشعار فور توفر سيارة مناسبة لك' : 'Get notified the moment your dream car arrives'}
                                </p>
                            </div>
                        </div>
                        <motion.button
                            whileHover={{ scale: 1.05, boxShadow: '0 0 30px rgba(0,240,255,0.4)' }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => { setEditAlert(null); setModalOpen(true); }}
                            disabled={stats.total >= 10}
                            className="flex items-center gap-3 px-7 py-4 bg-cyan-400 text-black font-black uppercase text-[11px] tracking-[0.3em] rounded-2xl shadow-[0_0_25px_rgba(0,240,255,0.3)] transition-all disabled:opacity-40 disabled:cursor-not-allowed"
                        >
                            <Plus className="w-5 h-5" />
                            {isRTL ? 'تنبيه جديد' : 'New Alert'}
                        </motion.button>
                    </div>
                </motion.div>

                {/* Stats */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
                    className="grid grid-cols-3 gap-4 mb-10"
                >
                    {[
                        { label: isRTL ? 'إجمالي التنبيهات' : 'Total Alerts', value: stats.total, max: 10, icon: Target, color: 'text-white' },
                        { label: isRTL ? 'التنبيهات النشطة' : 'Active Alerts', value: stats.active, icon: Zap, color: 'text-cyan-400' },
                        { label: isRTL ? 'إجمالي الإشعارات' : 'Total Fired', value: stats.totalTriggers, icon: TrendingUp, color: 'text-violet-400' },
                    ].map((s, i) => (
                        <motion.div
                            key={i}
                            initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: 0.1 + i * 0.05 }}
                            className="p-5 rounded-2xl bg-white/[0.02] border border-white/5 hover:border-white/10 transition-all"
                        >
                            <div className="flex items-center gap-2 mb-3">
                                <s.icon className={cn("w-4 h-4", s.color)} />
                                <span className="text-[9px] font-black text-white/30 uppercase tracking-widest">{s.label}</span>
                            </div>
                            <div className={cn("text-3xl font-black", s.color)}>
                                {s.value}
                                {s.max && <span className="text-white/20 text-lg">/{s.max}</span>}
                            </div>
                        </motion.div>
                    ))}
                </motion.div>

                {/* Limit warning */}
                {stats.total >= 10 && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                        className="mb-6 p-4 rounded-xl bg-amber-400/10 border border-amber-400/20 flex items-center gap-3">
                        <AlertCircle className="w-4 h-4 text-amber-400 shrink-0" />
                        <span className="text-[11px] font-bold text-amber-400">
                            {isRTL ? 'وصلت إلى الحد الأقصى (10 تنبيهات). احذف تنبيهاً لإضافة جديد.' : 'Maximum limit reached (10 alerts). Delete one to add more.'}
                        </span>
                    </motion.div>
                )}

                {/* Alerts List */}
                {loading ? (
                    <div className="flex items-center justify-center py-24">
                        <motion.div
                            animate={{ rotate: 360 }}
                            transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}
                            className="w-10 h-10 border-2 border-cyan-400/30 border-t-cyan-400 rounded-full"
                        />
                    </div>
                ) : alerts.length === 0 ? (
                    <motion.div
                        initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}
                        className="text-center py-24"
                    >
                        <div className="w-24 h-24 rounded-3xl bg-cyan-400/5 border border-cyan-400/10 flex items-center justify-center mx-auto mb-6">
                            <Bell className="w-10 h-10 text-cyan-400/30" />
                        </div>
                        <h3 className="text-xl font-black text-white mb-3">
                            {isRTL ? 'لا توجد تنبيهات بعد' : 'No Smart Alerts Yet'}
                        </h3>
                        <p className="text-white/30 text-[12px] font-bold mb-8 max-w-sm mx-auto">
                            {isRTL
                                ? 'أنشئ تنبيهاً ذكياً وسنخبرك عند توفر السيارة التي تبحث عنها'
                                : 'Create a smart alert and we\'ll notify you the moment your dream car is listed'}
                        </p>
                        <motion.button
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => setModalOpen(true)}
                            className="px-8 py-4 bg-cyan-400/10 border border-cyan-400/30 text-cyan-400 font-black uppercase text-[11px] tracking-[0.3em] rounded-2xl hover:bg-cyan-400/20 transition-all flex items-center gap-3 mx-auto"
                        >
                            <Plus className="w-5 h-5" />
                            {isRTL ? 'إنشاء أول تنبيه' : 'Create First Alert'}
                        </motion.button>
                    </motion.div>
                ) : (
                    <div className="space-y-4">
                        <AnimatePresence mode="popLayout">
                            {alerts.map(alert => (
                                <AlertCard
                                    key={alert._id}
                                    alert={alert}
                                    isRTL={isRTL}
                                    onToggle={() => handleToggle(alert._id)}
                                    onEdit={() => { setEditAlert(alert); setModalOpen(true); }}
                                    onDelete={() => setDeleteConfirm(alert._id)}
                                />
                            ))}
                        </AnimatePresence>
                    </div>
                )}
            </main>

            {/* Modal */}
            <AlertModal
                key={`${editAlert?._id ?? 'new'}-${String(modalOpen)}`}
                open={modalOpen}
                onClose={() => { setModalOpen(false); setEditAlert(null); }}
                onSave={handleSave}
                initial={editAlert}
                isRTL={isRTL}
                loading={saving}
            />

            {/* Delete Confirm Dialog */}
            <AnimatePresence>
                {deleteConfirm && (
                    <motion.div
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center p-4"
                        onClick={() => setDeleteConfirm(null)}
                    >
                        <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
                        <motion.div
                            initial={{ scale: 0.9 }} animate={{ scale: 1 }} exit={{ scale: 0.9 }}
                            className="relative bg-[#09090f] border border-red-400/20 rounded-2xl p-8 max-w-sm w-full text-center"
                            onClick={e => e.stopPropagation()}
                        >
                            <div className="w-14 h-14 rounded-2xl bg-red-400/10 border border-red-400/20 flex items-center justify-center mx-auto mb-5">
                                <Trash2 className="w-6 h-6 text-red-400" />
                            </div>
                            <h3 className="font-black text-white text-lg mb-2">
                                {isRTL ? 'حذف التنبيه؟' : 'Delete Alert?'}
                            </h3>
                            <p className="text-white/30 text-[12px] mb-7">
                                {isRTL ? 'لن يمكنك التراجع عن هذا الإجراء' : 'This action cannot be undone'}
                            </p>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setDeleteConfirm(null)}
                                    className="flex-1 py-3.5 rounded-xl border border-white/10 text-white/40 text-[11px] font-black uppercase hover:bg-white/5 transition-all"
                                >
                                    {isRTL ? 'إلغاء' : 'Cancel'}
                                </button>
                                <button
                                    onClick={() => handleDelete(deleteConfirm)}
                                    className="flex-1 py-3.5 rounded-xl bg-red-400/10 border border-red-400/30 text-red-400 text-[11px] font-black uppercase hover:bg-red-400/20 transition-all"
                                >
                                    {isRTL ? 'حذف' : 'Delete'}
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Toast */}
            <AnimatePresence>
                {toast && (
                    <motion.div
                        initial={{ opacity: 0, y: 50, x: '-50%' }}
                        animate={{ opacity: 1, y: 0, x: '-50%' }}
                        exit={{ opacity: 0, y: 20, x: '-50%' }}
                        className={cn(
                            "fixed bottom-8 left-1/2 z-[100] px-6 py-3.5 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-2xl flex items-center gap-2",
                            toast.type === 'success'
                                ? "bg-cyan-400 text-black shadow-[0_0_30px_rgba(0,240,255,0.4)]"
                                : "bg-red-400 text-white shadow-[0_0_30px_rgba(248,113,113,0.4)]"
                        )}
                    >
                        {toast.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
                        {toast.msg}
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { motion } from 'framer-motion';
import {
    Scale, X, Plus, Car, Gauge, Fuel, Settings,
    Calendar, Trash2
} from 'lucide-react';
import { api } from '@/lib/api-original';
import { useLocale } from '@/hooks/useLocale';
import ClientPageHeader from '@/components/ClientPageHeader';
import { useSettings } from '@/lib/SettingsContext';
import { cn } from '@/lib/utils';

const rawText = (value: string) => value;

interface CarData {
    _id: string;
    title: string;
    make: string;
    model: string;
    year: number;
    price: number;
    mileage?: number;
    fuelType?: string;
    transmission?: string;
    color?: string;
    description?: string;
    images: string[];
}

export default function ComparisonsPageWrapper() {
    return (
        <Suspense fallback={
            <div className="min-h-screen bg-black flex items-center justify-center">
                <div className="w-16 h-16 border-4 border-cinematic-neon-gold border-t-transparent rounded-full animate-spin" />
            </div>
        }>
            <ComparisonsPage />
        </Suspense>
    );
}

function ComparisonsPage() {
    const searchParams = useSearchParams();
    const { isRTL } = useLocale();
    const { formatPrice: formatGlobalPrice } = useSettings();
    const [cars, setCars] = useState<CarData[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchComparisons();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // ─── LocalStorage helpers ───
    const LS_KEY = 'hm_comparisons';

    const saveToLS = (data: CarData[]) => {
        try { localStorage.setItem(LS_KEY, JSON.stringify(data.map(c => c._id))); } catch {}
    };

    const loadFromLS = (): string[] => {
        try { return JSON.parse(localStorage.getItem(LS_KEY) || '[]'); } catch { return []; }
    };

    const fetchComparisons = useCallback(async () => {
        try {
            setLoading(true);

            // Check if there are car IDs in URL params
            const carIds = searchParams.get('ids')?.split(',') || loadFromLS();

            if (carIds && carIds.length > 0) {
                const response = await api.comparisons.compare(carIds);
                if (response.success && Array.isArray(response.data) && response.data.length > 0) {
                    setCars(response.data);
                    saveToLS(response.data);
                    return;
                }
            }

            // Fallback: جلب المقارنات المحفوظة في الـ API
            const response = await api.comparisons.get();
            if (response.success && Array.isArray(response.data)) {
                setCars(response.data);
                saveToLS(response.data);
            }
        } catch (err) {
            // Fallback أخير: localStorage المحلي
            const cachedIds = loadFromLS();
            if (cachedIds.length > 0) {
                try {
                    const res = await api.comparisons.compare(cachedIds);
                    if (res.success) setCars(res.data);
                } catch { /* silent */ }
            }
            console.error('Failed to fetch comparisons:', err);
        } finally {
            setLoading(false);
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [searchParams]);

    const removeCar = async (carId: string) => {
        try {
            await api.comparisons.remove(carId);
            const updated = cars.filter(car => car._id !== carId);
            setCars(updated);
            saveToLS(updated);
        } catch (err) {
            // Optimistic update even if API fails
            const updated = cars.filter(car => car._id !== carId);
            setCars(updated);
            saveToLS(updated);
            console.error('Failed to remove car (local updated):', err);
        }
    };

    const clearAll = async () => {
        try {
            await api.comparisons.clear();
            setCars([]);
            saveToLS([]);
        } catch (err) {
            // Optimistic clear
            setCars([]);
            saveToLS([]);
            console.error('Failed to clear comparisons (local cleared):', err);
        }
    };

    const formatPrice = (price: number) => formatGlobalPrice(Number(price || 0));

    // تحديد أفضل وأسوأ قيمة في صف معين
    const getBestIdx = (key: string, lower = true): number => {
        const vals = cars.map(c => Number((c as unknown as Record<string, unknown>)[key]) || 0);
        if (vals.every(v => v === 0)) return -1;
        return lower
            ? vals.indexOf(Math.min(...vals.filter(v => v > 0)))
            : vals.indexOf(Math.max(...vals));
    };

    const specs = [
        { key: 'price', label: isRTL ? 'السعر' : 'Price', icon: null,
            format: (v: unknown) => formatPrice(v as number),
            bestType: 'lower' as const },
        { key: 'year', label: isRTL ? 'السنة' : 'Year', icon: Calendar,
            bestType: 'higher' as const },
        { key: 'mileage', label: isRTL ? 'المسافة' : 'Mileage', icon: Gauge,
            format: (v: unknown) => v ? `${Number(v).toLocaleString()} ${isRTL ? rawText('كم') : rawText('km')}` : rawText('-'),
            bestType: 'lower' as const },
        { key: 'fuelType', label: isRTL ? 'الوقود' : 'Fuel', icon: Fuel },
        { key: 'transmission', label: isRTL ? 'ناقل الحركة' : 'Transmission', icon: Settings },
        { key: 'color', label: isRTL ? 'اللون' : 'Color', icon: null },
        { key: 'description', label: isRTL ? 'الوصف' : 'Description', icon: null },
    ];

    const getBadge = (key: string, carIdx: number, bestType?: 'higher' | 'lower') => {
        if (!bestType) return null;
        const bestIdx = getBestIdx(key, bestType === 'lower');
        if (bestIdx === -1 || cars.length < 2) return null;
        if (carIdx === bestIdx) return (
            <span className="ml-1 text-[8px] font-black text-emerald-400 bg-emerald-400/10 border border-emerald-400/20 rounded px-1">
                {isRTL ? rawText('أفضل') : rawText('BEST')}
            </span>
        );
        const vals = cars.map(c => Number((c as unknown as Record<string, unknown>)[key]) || 0).filter(v => v > 0);
        const unique = new Set(vals);
        if (unique.size > 1) {
            const worst = bestType === 'lower' ? Math.max(...vals) : Math.min(...vals.filter(v => v > 0));
            const carVal = Number((cars[carIdx] as unknown as Record<string, unknown>)[key]) || 0;
            if (carVal === worst) return (
                <span className="ml-1 text-[8px] font-black text-red-400/70 bg-red-400/10 border border-red-400/20 rounded px-1">
                    {isRTL ? rawText('أعلى') : rawText('HIGH')}
                </span>
            );
        }
        return null;
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-black flex items-center justify-center">
                <div className="w-16 h-16 border-4 border-cinematic-neon-gold border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    return (
        <div className={`min-h-screen bg-black text-white ${isRTL ? 'rtl' : 'ltr'}`} dir={isRTL ? 'rtl' : 'ltr'}>
            <section className="pt-32 pb-10 px-4">
                <div className="max-w-7xl mx-auto">
                    <div className="flex items-center justify-between mb-6">
                        <ClientPageHeader title={isRTL ? 'مقارنة السيارات' : 'Compare Cars'} icon={Scale} />

                        {cars.length > 0 && (
                            <button
                                onClick={clearAll}
                                className="flex items-center gap-2 text-red-400 hover:text-red-300 transition-colors"
                            >
                                <Trash2 className="w-5 h-5" />
                                <span>{isRTL ? rawText('مسح الكل') : rawText('Clear All')}</span>
                            </button>
                        )}
                    </div>

                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-center"
                    >
                        <div className="w-20 h-20 bg-cinematic-neon-gold/20 rounded-full flex items-center justify-center mx-auto mb-6">
                            <Scale className="w-10 h-10 text-cinematic-neon-gold" />
                        </div>
                        <h1 className="text-5xl font-black mb-4">
                            {isRTL ? rawText('مقارنة السيارات') : rawText('Compare Cars')}
                        </h1>
                        <p className="text-xl text-white/60">
                            {cars.length > 0
                                ? (isRTL ? `مقارنة ${cars.length} سيارات` : `Comparing ${cars.length} cars`)
                                : (isRTL ? rawText('أضف سيارات للمقارنة') : rawText('Add cars to compare'))}
                        </p>
                    </motion.div>
                </div>
            </section>

            <main className="max-w-7xl mx-auto px-4 pb-20">
                {cars.length === 0 ? (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-center py-20"
                    >
                        <Car className="w-24 h-24 text-white/20 mx-auto mb-6" />
                        <h2 className="text-2xl font-bold mb-4">
                            {isRTL ? rawText('لا توجد سيارات للمقارنة') : rawText('No cars to compare')}
                        </h2>
                        <p className="text-white/60 mb-8">
                            {isRTL
                                ? rawText('ابحث عن سيارات وأضفها للمقارنة')
                                : rawText('Search for cars and add them to compare')}
                        </p>
                        <Link
                            href="/cars"
                            className="inline-flex items-center gap-2 px-8 py-4 bg-cinematic-neon-gold text-black font-bold rounded-xl hover:bg-[#d4af68] transition-all"
                        >
                            <Plus className="w-5 h-5" />
                            {isRTL ? rawText('معرض HM CAR') : rawText('HM CAR Showroom')}
                        </Link>
                    </motion.div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full min-w-200">
                            {/* Car Images & Titles */}
                            <thead>
                                <tr>
                                    <th className="p-4 text-left w-48"></th>
                                    {cars.map((car, index) => (
                                        <th key={car._id} className="p-4 min-w-70">
                                            <motion.div
                                                initial={{ opacity: 0, y: 20 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                transition={{ delay: index * 0.1 }}
                                                className="relative bg-white/5 rounded-2xl border border-white/10 overflow-hidden group"
                                            >
                                                {/* Remove Button */}
                                                <button
                                                    onClick={() => removeCar(car._id)}
                                                    aria-label="Remove car"
                                                    className="absolute top-3 right-3 z-10 w-8 h-8 bg-red-500/80 backdrop-blur-xl rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                                                >
                                                    <X className="w-4 h-4" />
                                                </button>

                                                {/* Image */}
                                                <div className="aspect-video">
                                                    {car.images && car.images.length > 0 ? (
                                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img src={car.images[0]} alt={car.title} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center bg-white/5">
                                                            <Car className="w-16 h-16 text-white/20" />
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Title */}
                                                <div className="p-4">
                                                    <div className="text-cinematic-neon-gold text-xs font-bold uppercase mb-1">
                                                        {car.make} {rawText('•')} {car.year}
                                                    </div>
                                                    <Link
                                                        href={`/cars/${car._id}`}
                                                        className="font-bold hover:text-cinematic-neon-gold transition-colors"
                                                    >
                                                        {car.title || `${car.make} ${car.model}`}
                                                    </Link>
                                                </div>
                                            </motion.div>
                                        </th>
                                    ))}
                                    {/* Add More Button */}
                                    {cars.length < 4 && (
                                        <th className="p-4 min-w-50">
                                            <Link
                                                href="/showroom"
                                                className="flex flex-col items-center justify-center h-full min-h-62.5 bg-white/5 rounded-2xl border border-dashed border-white/20 hover:border-cinematic-neon-gold transition-all group"
                                            >
                                                <Plus className="w-12 h-12 text-white/40 group-hover:text-cinematic-neon-gold transition-colors mb-3" />
                                                <span className="text-white/40 group-hover:text-cinematic-neon-gold transition-colors">
                                                    {isRTL ? rawText('أضف سيارة') : rawText('Add Car')}
                                                </span>
                                            </Link>
                                        </th>
                                    )}
                                </tr>
                            </thead>

                            {/* Specs Rows */}
                            <tbody>
                                {specs.map((spec, specIndex) => (
                                    <tr key={spec.key} className={cn(
                                        'border-b border-white/5 transition-colors',
                                        specIndex % 2 === 0 ? 'bg-white/[0.02]' : ''
                                    )}>
                                        <td className="p-4 font-bold text-white/60">
                                            <div className="flex items-center gap-3">
                                                {spec.icon && <spec.icon className="w-5 h-5 text-cinematic-neon-gold" />}
                                                <span className="text-sm">{spec.label}</span>
                                            </div>
                                        </td>
                                        {cars.map((car, carIdx) => {
                                            const val = (car as unknown as Record<string, unknown>)[spec.key];
                                            const badge = spec.bestType ? getBadge(spec.key, carIdx, spec.bestType) : null;
                                            return (
                                                <td key={car._id} className="p-4 text-center">
                                                    <span className={[
                                                        spec.key === 'price' ? 'text-cinematic-neon-gold font-bold text-xl' : 'text-white/80',
                                                    ].join(' ')}>
                                                        {spec.format
                                                            ? spec.format(val)
                                                            : (String(val || '-'))}
                                                    </span>
                                                    {badge}
                                                </td>
                                            );
                                        })}
                                        {cars.length < 4 && <td />}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </main>
        </div>
    );
}

"use client";

/**
 * المكون الرئيسي للصفحة الرئيسية (HomeClient)
 * يتحكم في عرض الموقع بناءً على المنصة (متصفح أو PWA مثبت).
 * يتضمن الخلفية السينمائية، شريط الإعلانات، وعرض السيارات الأحدث.
 */

import React, { useRef, useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Sparkles, Smartphone, Download, Link as LinkIcon,
  ArrowRight, Car, X, Shield, Award, Globe, Truck, HelpCircle,
  Wrench, Layers, Package, Zap, Cog, TrendingUp, Gavel, Timer, Star
} from "lucide-react";
import { SocialIconMap, SocialColorMap } from "@/components/SocialIcons";

const lucideIcons = { Shield, Award, Globe, Truck, HelpCircle, Wrench, Layers, Package, Zap, Cog, TrendingUp, Gavel, Timer };
import Link from "next/link";
import Image from "next/image";
import Navbar from "@/components/Navbar";
import CinematicVideoBackground from "@/components/CinematicVideoBackground";
import { useLanguage } from "@/lib/LanguageContext";
import { api } from "@/lib/api-original";

import dynamic from "next/dynamic";
const LandingShowcase = dynamic(() => import("@/components/LandingShowcase"), { ssr: false });
const AppHome = dynamic(() => import("@/components/AppHome"), { ssr: false });
const SmartAdBanner = dynamic(() => import("@/components/SmartAdBanner"), { ssr: false });
const CarXHome = dynamic(() => import("@/components/CarXHome"), { ssr: false });

import { useRouter } from "next/navigation";
import { useSocket } from "@/lib/SocketContext";
import CurrencySwitcher from "@/components/CurrencySwitcher";
import { useAuth } from "@/lib/AuthContext";
import { useSettings } from "@/lib/SettingsContext";
import { cn } from "@/lib/utils";
import { useStandalone } from "@/lib/useStandalone";
import { useTenant } from "@/lib/TenantContext";
import ModernCarCard from "@/components/ModernCarCard";

export type CarType = {
  id?: string;
  name?: string;
  title?: string;
  images?: string[];
  year?: number | string;
  make?: { name?: string } | string;
  price?: number | string;
  model?: string;
  mileage?: number;
  fuelType?: string;
  transmission?: string;
  priceSar?: number;
  priceUsd?: number;
};

interface HomeClientProps {
  latestCars: CarType[];
}

// ── مكون زر التطبيق العائم ──
function PWAFloatingButton({ isRTL, deferredInstall, onInstall }: { isRTL: boolean; deferredInstall: any; onInstall: () => void }) {
  const [showPopup, setShowPopup] = useState(false);
  const [showIOSGuide, setShowIOSGuide] = useState(false);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    // إظهار البطاقة تلقائياً بعد 3 ثوانٍ
    const alreadyDismissed = localStorage.getItem('pwa_popup_dismissed');
    if (alreadyDismissed) return;
    const timer = setTimeout(() => setShowPopup(true), 3000);
    return () => clearTimeout(timer);
  }, []);

  // إغلاق نهائي عند الضغط على X
  const handleClose = () => {
    setShowPopup(false);
    setDismissed(true);
    localStorage.setItem('pwa_popup_dismissed', 'true');
  };

  if (dismissed) return null;

  return (
    <div className="relative">
      {/* أيقونة الهاتف الثابتة */}
      <motion.button
        id="pwa-float-btn"
        onClick={() => setShowPopup(!showPopup)}
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        whileTap={{ scale: 0.9 }}
        className="w-10 h-10 rounded-xl bg-black/40 backdrop-blur-md border border-white/10 flex items-center justify-center hover:scale-110 hover:border-accent-gold/50 transition-transform text-accent-gold shadow-[0_0_15px_rgba(201,169,110,0.2)]"
        title={isRTL ? 'تطبيق HM CAR' : 'HM CAR App'}
      >
        <Smartphone className="w-4 h-4" />
      </motion.button>

      {/* Popup مصغّر وأنيق */}
      <AnimatePresence>
        {showPopup && (
          <motion.div
            initial={{ opacity: 0, scale: 0.85, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.85, y: 10 }}
            transition={{ type: "spring", damping: 22, stiffness: 220 }}
            className="fixed bottom-24 left-4 z-[199] w-64 rounded-2xl bg-gradient-to-br from-[#1a1a1a] to-[#0a0a0a] border border-accent-gold/30 shadow-[0_16px_40px_rgba(201,169,110,0.2)] overflow-hidden"
            dir={isRTL ? 'rtl' : 'ltr'}
          >
            {/* زر الإغلاق X في الركن */}
            <button
              onClick={handleClose}
              aria-label={isRTL ? "إغلاق" : "Close"}
              title={isRTL ? "إغلاق" : "Close"}
              className={`absolute top-2 ${isRTL ? 'left-2' : 'right-2'} z-10 w-6 h-6 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 text-white/50 hover:text-white transition-all`}
            >
              <X className="w-3 h-3" />
            </button>

            <div className="p-4">
              {/* Header مصغّر */}
              <div className="flex items-center gap-3 mb-3">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-accent-gold to-[#a98544] text-black flex items-center justify-center shrink-0">
                  <Smartphone className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-white font-black text-sm uppercase">HM CAR</h3>
                  <div className="flex items-center gap-0.5 mt-0.5">
                    {[1,2,3,4,5].map(i => <Star key={i} className="w-2.5 h-2.5 text-accent-gold fill-accent-gold" />)}
                  </div>
                </div>
              </div>

              <p className="text-white/70 text-xs font-bold leading-relaxed mb-3">
                {isRTL ? 'احصل على تنبيهات فورية للمزادات!' : 'Get instant auction alerts!'}
              </p>

              <button
                onClick={() => {
                  if (deferredInstall) { onInstall(); handleClose(); }
                  else setShowIOSGuide(!showIOSGuide);
                }}
                className="w-full py-2.5 bg-gradient-to-r from-accent-gold to-[#e8c97a] text-black rounded-xl font-black text-xs flex items-center justify-center gap-2"
              >
                <Download className="w-3.5 h-3.5" />
                {isRTL ? 'تثبيت مجاناً' : 'Install Free'}
              </button>

              {showIOSGuide && !deferredInstall && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="mt-3 text-[10px] text-white/50 space-y-1 bg-black/30 p-3 rounded-xl"
                >
                  <p>⬆️ {isRTL ? 'اضغط زر المشاركة' : 'Tap Share button'}</p>
                  <p>➕ {isRTL ? 'إضافة للشاشة الرئيسية' : 'Add to Home Screen'}</p>
                </motion.div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}


export default function HomeClient({ latestCars: initialLatestCars }: HomeClientProps) {
  const [latestCars, setLatestCars] = useState<CarType[]>(initialLatestCars || []);
  const [loadingCars, setLoadingCars] = useState(initialLatestCars?.length === 0);

  useEffect(() => {
    if (latestCars.length === 0) {
      setLoadingCars(true);
      api.cars.list({ limit: 8, sort: 'createdAt:desc' })
        .then(res => {
          const data = res?.data || res;
          if (Array.isArray(data)) setLatestCars(data);
          else if (Array.isArray(data?.data)) setLatestCars(data.data);
        })
        .catch(err => console.error("Error fetching cars:", err))
        .finally(() => setLoadingCars(false));
    }
  }, []);

  const { isRTL } = useLanguage();
  const { user, isLoggedIn } = useAuth();
  const { socket, isConnected } = useSocket();
  const { siteInfo, homeContent, formatPrice, features } = useSettings();
  const { tenant } = useTenant();
  const isCarX = tenant?.id === 'carx';
  const containerRef = useRef<HTMLDivElement>(null);
  const liveRef = useRef<HTMLDivElement>(null);
  const [videoHeight, setVideoHeight] = useState<string>("55vh");
  const [deferredInstall, setDeferredInstall] = useState<any>(null);
  const [isInstalled, setIsInstalled] = useState(false);

  useEffect(() => {
    // التحقق مما إذا كان التطبيق مسجلاً كمثبت في التخزين المحلي بعد تحميل الصفحة لتجنب خطأ Hydration
    if (typeof window !== 'undefined') {
      setIsInstalled(!!localStorage.getItem('pwa_installed'));
    }
  }, []);

  useEffect(() => {
    const handler = (e: Event) => { e.preventDefault(); setDeferredInstall(e); };
    const installedHandler = () => { setIsInstalled(true); localStorage.setItem('pwa_installed', '1'); };
    window.addEventListener('beforeinstallprompt', handler);
    window.addEventListener('appinstalled', installedHandler);
    // ✅ cleanup — يمنع memory leak عند إلغاء تحميل المكون
    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('appinstalled', installedHandler);
    };
  }, []);



  const handleInstallPWA = async () => {
    if (!deferredInstall) return;
    deferredInstall.prompt();
    const { outcome } = await deferredInstall.userChoice;
    if (outcome === 'accepted') { setIsInstalled(true); localStorage.setItem('pwa_installed', '1'); }
    setDeferredInstall(null);
  };

  const router = useRouter();
  const isStandalone = useStandalone();

  useEffect(() => {
    // تم إيقاف التحويل التلقائي لكي يبقى العميل في واجهة التطبيق المجملة (AppHome)
    // if (isStandalone && isLoggedIn) {
    //   router.replace('/client/dashboard');
    // }
  }, [isStandalone, isLoggedIn, router]);

  useEffect(() => {
    if (isLoggedIn && user && socket && isConnected) {
      const userId = (user as any)._id || (user as any).id;
      socket.emit('user_navigation', {
        userId,
        userName: user.name,
        page: isRTL ? 'الصفحة الرئيسية' : 'Home Page',
        timestamp: new Date()
      });
    }
  }, [isLoggedIn, user, socket, isConnected, isRTL]);

  useEffect(() => {
    const updateHeight = () => {
      const top = liveRef.current ? liveRef.current.offsetTop : 0;
      if (top > 0) setVideoHeight(`${top}px`);
      else setVideoHeight("85vh");
    };
    updateHeight();
    window.addEventListener("resize", updateHeight);
    return () => window.removeEventListener("resize", updateHeight);
  }, []);

  const txt = {
    rights: isRTL ? "جميع الحقوق محفوظة" : "All Rights Reserved",
    privacy: isRTL ? "سياسة الخصوصية" : "Privacy Policy",
    terms: isRTL ? "شروط الاستخدام" : "Terms of Use",
  };

  // lucideIcons removed — icons now imported directly where needed


  const [socialConfig, setSocialConfig] = useState<{ whatsapp?: string; links: { platform: string; url: string }[] }>({
    whatsapp: '+821080880014',
    links: [
      { platform: 'instagram', url: 'https://instagram.com' },
      { platform: 'tiktok', url: 'https://tiktok.com' },
      { platform: 'snapchat', url: 'https://snapchat.com' },
    ]
  });

  useEffect(() => {
    const DEFAULT_WHATSAPP = '+821080880014';
    const DEFAULT_SOCIAL_LINKS = [
      { platform: 'instagram', url: 'https://instagram.com' },
      { platform: 'tiktok', url: 'https://tiktok.com' },
      { platform: 'snapchat', url: 'https://snapchat.com' },
    ];

    const fetchSocialLinks = async () => {
      try {
        const response = await api.settings.getPublic();
        if (response.success && response.data.socialLinks) {
          const sl = response.data.socialLinks;
          const linksArray = Object.entries(sl)
            .filter(([k, v]) => k !== 'whatsapp' && v && String(v).startsWith('http'))
            .map(([k, v]) => ({ platform: k, url: v as string }));

          setSocialConfig({
            whatsapp: sl.whatsapp || DEFAULT_WHATSAPP,
            links: linksArray.length > 0 ? linksArray : DEFAULT_SOCIAL_LINKS
          });
        }
      } catch (err) {
        console.error("Failed to fetch social links", err);
      }
    };
    fetchSocialLinks();
  }, []);

  // Social icons are now imported from @/components/SocialIcons

  const whatsappUrl = socialConfig.whatsapp ? `https://wa.me/${String(socialConfig.whatsapp).replace(/\D/g, '')}` : "#";

  if (isCarX) {
    return <CarXHome />;
  }

  return (
    <main ref={containerRef} className="relative min-h-screen overflow-x-hidden bg-black text-white" dir={isRTL ? "rtl" : "ltr"}>
      <div className="hide-in-app">
        <Navbar />
      </div>

      {/* ── STICKY SOCIAL BAR (Visible only in Web) ── */}
      {!isStandalone && (
        <div className={cn(
          "fixed z-[90] flex flex-col gap-3 top-1/3",
          isRTL ? "right-4" : "left-4"
        )}>
          {socialConfig.whatsapp && (
            <a href={whatsappUrl} target="_blank" rel="noreferrer" className="w-12 h-12 rounded-full bg-black/40 backdrop-blur-md border border-green-500/30 flex items-center justify-center text-green-500 hover:scale-110 transition-transform shadow-[0_0_15px_rgba(34,197,94,0.3)]" title="WhatsApp">
              <SocialIconMap.whatsapp className="w-6 h-6" />
            </a>
          )}
          {socialConfig.links.map((link, i) => {
            const SvgIcon = SocialIconMap[link.platform];
            const colorClass = SocialColorMap[link.platform] || 'text-white/80';
            return (
              <a key={i} href={link.url} target="_blank" rel="noreferrer" className={`w-12 h-12 rounded-full bg-black/40 backdrop-blur-md border border-white/10 flex items-center justify-center hover:scale-110 hover:border-white/30 transition-transform ${colorClass}`} title={link.platform}>
                {SvgIcon ? <SvgIcon className="w-5 h-5" /> : <LinkIcon className="w-5 h-5" />}
              </a>
            )
          })}
          {/* ── FLOATING PWA PHONE ICON ── */}
          {!isInstalled && (
            <PWAFloatingButton
              isRTL={isRTL}
              deferredInstall={deferredInstall}
              onInstall={handleInstallPWA}
            />
          )}

          {/* ── PERSISTENT CURRENCY SWITCHER ── */}
          <CurrencySwitcher variant="compact" className="mt-2" />
        </div>
      )}

      {/* ── BACKGROUND LOGIC ── */}
      {!isStandalone ? (
        <CinematicVideoBackground
          videoSrc={homeContent?.heroVideoUrl || "/videos/hero.mp4"}
          fallbackImage="/images/photo_2026-02-07_22-24-18.jpg"
          mobileImage="/images/hmcar.jpg"
          overlayOpacity={0.55}
          height={videoHeight}
        />
      ) : null}

      {/* ── BACK TO TOP BUTTON ── - مخفي في وضع التطبيق لتجنب التحجب على شريط التنقل السفلي */}
      {!isStandalone && (
        <motion.button
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className="fixed bottom-8 right-8 z-40 w-12 h-12 rounded-2xl bg-accent-gold text-black flex items-center justify-center shadow-lg hover:scale-110 transition-transform"
          title={isRTL ? 'الرجوع للأعلى' : 'Back to Top'}
        >
          <ArrowRight className="-rotate-90 w-5 h-5" />
        </motion.button>
      )}

      {/* ── CONTENT SWITCHER ── */}
      {isStandalone ? (
        // ── واجهة التطبيق الاحترافية (App Interface) ──
        <AppHome 
          isRTL={isRTL} 
          latestCars={latestCars} 
          formatPrice={formatPrice} 
        />
      ) : (
        // ── واجهة الموقع الاستعراضية (Web Showcase) ──
        <>
          {/* 1. HERO SHOWCASE */}
          <LandingShowcase isRTL={isRTL} latestCars={latestCars} />

          {/* 2. LATEST CARS SECTION (RESTORED) */}
          {(homeContent?.showLiveMarket ?? true) && (
            <>
              <section className="relative z-10 py-24 px-4 bg-gradient-to-b from-transparent to-black/20">
                <div className="max-w-7xl mx-auto">
                  <div className="flex items-center justify-between mb-12">
                    <div>
                      <h2 className="text-4xl md:text-6xl font-black text-white italic uppercase tracking-tighter">
                        {isRTL ? 'أحدث السيارات' : 'LATEST ARRIVALS'}
                      </h2>
                      <div className="h-1 w-20 bg-accent-gold mt-2" />
                    </div>
                    <Link href="/gallery" className="group flex items-center gap-2 text-accent-gold font-bold uppercase tracking-widest hover:text-white transition-colors">
                      {isRTL ? 'عرض الكل' : 'VIEW ALL'}
                      <ArrowRight className={cn("w-5 h-5 transition-transform group-hover:translate-x-2", isRTL && "rotate-180 group-hover:-translate-x-2")} />
                    </Link>
                  </div>

                  {loadingCars ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                      {[...Array(4)].map((_, i) => (
                        <div key={i} className="rounded-2xl bg-white/5 border border-white/8 overflow-hidden animate-pulse">
                          <div className="h-52 bg-white/8" />
                          <div className="p-5 space-y-3">
                            <div className="h-4 bg-white/8 rounded-lg w-3/4" />
                            <div className="h-3 bg-white/5 rounded-lg w-1/2" />
                            <div className="h-8 bg-white/8 rounded-xl w-full mt-3" />
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                      {latestCars.slice(0, 8).map((car, i) => (
                        <ModernCarCard key={car.id || i} car={car as any} index={i} formatPrice={formatPrice} />
                      ))}
                    </div>
                  )}
                </div>
              </section>

              {/* ── شريط "وصل حديثاً" - آخر 7 أيام ── */}
              {latestCars.length > 0 && (
                <section className="relative z-10 py-12 px-4">
                  <div className="max-w-7xl mx-auto">
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-3">
                        <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-green-500/10 border border-green-500/20">
                          <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
                          <span className="text-xs font-black text-green-400 uppercase tracking-widest">
                            {isRTL ? 'وصل حديثاً' : 'New Arrivals'}
                          </span>
                        </div>
                        <span className="text-white/30 text-xs">{isRTL ? 'آخر 7 أيام' : 'Last 7 days'}</span>
                      </div>
                      <Link href="/cars" className="text-xs font-bold text-accent-gold hover:text-white transition-colors flex items-center gap-1">
                        {isRTL ? 'عرض الكل' : 'View All'}
                        <ArrowRight className={cn("w-3.5 h-3.5", isRTL && "rotate-180")} />
                      </Link>
                    </div>

                    {/* شريط أفقي قابل للتمرير */}
                    <div className="flex gap-4 overflow-x-auto pb-3 scrollbar-none snap-x snap-mandatory">
                      {latestCars.slice(0, 12).map((car: any, i) => (
                        <motion.div
                          key={car.id || i}
                          initial={{ opacity: 0, x: 20 }}
                          whileInView={{ opacity: 1, x: 0 }}
                          viewport={{ once: true }}
                          transition={{ delay: i * 0.05 }}
                          className="snap-start shrink-0 w-52 sm:w-60 group cursor-pointer"
                          onClick={() => router.push(`/cars/${car.id || car._id}`)}
                        >
                          <div className="relative overflow-hidden rounded-xl border border-white/8 bg-white/3 hover:border-luxury-gold/30 transition-all duration-300 group-hover:shadow-[0_8px_30px_rgba(212,175,55,0.1)]">
                            {/* صورة السيارة */}
                            <div className="relative h-36 overflow-hidden bg-white/5">
                              {car.images?.[0] ? (
                                <Image src={car.images[0]} alt={car.title || car.name || ''} fill className="object-cover transition-transform duration-500 group-hover:scale-105" unoptimized />
                              ) : (
                                <div className="w-full h-full flex items-center justify-center">
                                  <Car className="w-10 h-10 text-white/10" />
                                </div>
                              )}
                              {/* شارة جديد */}
                              <div className="absolute top-2 right-2">
                                <span className="px-2 py-0.5 rounded-full bg-green-500 text-[9px] font-black text-black uppercase tracking-widest">
                                  {isRTL ? 'جديد' : 'New'}
                                </span>
                              </div>
                            </div>
                            {/* بيانات السيارة */}
                            <div className="p-3 space-y-1.5">
                              <p className="text-xs font-black text-white truncate">{car.title || car.name}</p>
                              <div className="flex items-center gap-2 text-[9px] text-white/40 font-bold">
                                {car.year && <span>{car.year}</span>}
                                {car.mileage && <><span>·</span><span>{Number(car.mileage).toLocaleString()} km</span></>}
                              </div>
                              <div className="text-sm font-black text-luxury-gold">
                                {car.priceSar ? `${Number(car.priceSar).toLocaleString()} SAR` : car.price ? `${Number(car.price).toLocaleString()}` : '—'}
                              </div>
                            </div>
                          </div>
                        </motion.div>
                      ))}
                    </div>
                  </div>
                </section>
              )}
            </>
          )}

          {/* 2.5 ANNOUNCEMENT RIBBON REMOVED: Replaced fully by SmartAdBanner */}

          {/* 4. LIVE MARKET TICKER - REMOVED: Now handled fully and robustly by SmartAdBanner */}
        </>
      )}

      {/* 4.5 الشريط الإعلاني الذكي المتحرك */}
      {(homeContent?.showAdvertising ?? true) && (
        <SmartAdBanner />
      )}

      {/* ── 5. THE BUYING JOURNEY - REMOVED AS REQUESTED ── */}

      {/* ── 5.1 PLATFORM FEATURES (DYNAMIC WITH FALLBACK) ── */}
      {(homeContent?.showPlatformFeatures ?? true) && (() => {
        const displayFeatures = features && features.length > 0 ? features : [
          { title: 'موثوقية تامة', titleEn: 'Absolute Trust', desc: 'سيارات مستوردة مفحوصة بالكامل مع ضمان الشفافية للمالك.', descEn: 'Fully inspected imported cars with transparency guaranteed.', icon: 'Shield' },
          { title: 'أسعار تنافسية', titleEn: 'Competitive Pricing', desc: 'مزادات حية تمنحك الأولوية للحصول على أفضل سعر بالسوق.', descEn: 'Live auctions giving you edge for the best market prices.', icon: 'Award' },
          { title: 'شحن عالمي', titleEn: 'Global Shipping', desc: 'نظام رقمي يتتبع مسار رحلة سيارتك حتى باب منزلك.', descEn: 'Digital system tracking your car journey to your doorstep.', icon: 'Globe' }
        ];

        return (
          <section className="relative z-10 py-32 px-4">
            <div className="max-w-7xl mx-auto">
              <div className="text-center mb-24">
                <h2 className="text-5xl md:text-7xl font-black text-white italic uppercase tracking-tighter">{isRTL ? 'لماذا تختارنا؟' : 'WHY CHOOSE US?'}</h2>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {displayFeatures.slice(0, 6).map((feat, i) => {
                  const Icon = (lucideIcons as any)[feat.icon] || Shield;
                  return (
