            {/* ─── 3. Stats ─── */}
            <StatsBar isRTL={isRTL} showroomCount={showroomCars.length} auctionCount={liveAuctions.length} brandCount={brands.length} />

            {/* ─── 4. Showroom Grid ─── */}
            <ShowroomGrid
                isRTL={isRTL}
                cars={displayShowroomCars}
                loading={carsLoading}
                formatCarImage={formatCarImage}
