            {/* ─── 5. Live Auction Ticker ─── */}
            <LiveAuctionTicker
                isRTL={isRTL}
                cars={displayAuctionCars}
                formatCarImage={formatCarImage}
                formatCarTitle={formatCarTitle}
                formatPrice={formatPriceFromUsd}
