'use client';

/**
 * CircularBrandCard - بطاقة الوكالة الدائرية الإبداعية
 * تصميم دائري مذهل مع تأثيرات متقدمة وشعارات واضحة
 */

import React, { useState } from "react";
import { motion, useMotionValue, useTransform } from "framer-motion";
import { Building2, Car, ArrowRight, Star, Crown, Gem, Sparkles } from "lucide-react";
import { useLanguage } from "@/lib/LanguageContext";
import Link from "next/link";
import Image from "next/image";
import { getBrandDisplayName, getBrandLogoUrls, isLocalPath } from "@/lib/brandTranslations";

interface CircularBrandCardProps {
    brand: {
        id: string;
        key: string;
        name: string;
        nameAr?: string;
        logo?: string;
        description?: string;
        descriptionAr?: string;
        carCount?: number;
        isActive?: boolean;
    };
    index: number;
    onClick?: () => void;
}

export default function CircularBrandCard({ brand, index, onClick: _onClick }: CircularBrandCardProps) {
    const { isRTL } = useLanguage();
    // مصادر الشعارات مرتّبة حسب الأولوية
    const logoUrls = React.useMemo(() => {
        const l = brand.logo;
        const fallbacks = getBrandLogoUrls(brand.name || brand.key);
        // إذا كان الشعار موجوداً وليس مساراً محلياً، ضعه في المقدمة
        if (l && !isLocalPath(l)) return [l, ...fallbacks];
        return fallbacks;
    }, [brand.logo, brand.name, brand.key]);

    const [logoIndex, setLogoIndex] = useState(0);
    const [imageError, setImageError] = useState(false);
    const logoSrc = logoUrls[logoIndex] || '';
    // Motion values للتأثيرات ثلاثية الأبعاد
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const rotateX = useTransform(y, [-100, 100], [10, -10]);
    const rotateY = useTransform(x, [-100, 100], [-10, 10]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;
        x.set((e.clientX - centerX) * 0.1);
        y.set((e.clientY - centerY) * 0.1);
    };

    const handleMouseLeave = () => {
        x.set(0);
        y.set(0);
    };

    const handleMouseEnter = () => {
    };

    const displayName = getBrandDisplayName(brand.nameAr || brand.name, isRTL);
    const displayDescription = isRTL ? (brand.descriptionAr || brand.description) : brand.description;


    return (
        <motion.div
            initial={{ opacity: 0, y: 40, scale: 0.9 }}
            whileInView={{ opacity: 1, y: 0, scale: 1 }}
            viewport={{ once: true }}
            transition={{ 
                duration: 0.6, 
                delay: index * 0.1,
                type: "spring",
                stiffness: 100
            }}
            style={{
                rotateX,
                rotateY,
                transformStyle: "preserve-3d",
            }}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
