    // ── السعر بالعملة الصحيحة ────────────────────────────
    const getFormattedPrice = () => {
        if (propFormatPrice) return propFormatPrice(car.price || car.priceSar || 0);

        // إذا كانت سيارة كورية لها سعر بالدولار
        if (isKoreanImport && car.priceUsd && car.priceUsd > 0) {
            return formatPriceFromUsd(car.priceUsd);
        }
        // سيارة عادية لها سعر بالريال
        const sarPrice = car.priceSar || car.price || 0;
        if (sarPrice > 0) return ctxFormatPrice(sarPrice);
        return isRTL ? 'عند الطلب' : 'On Request';
    };

    // ── واتساب ───────────────────────────────────────────
    const wa = whatsappNumber || '+821080880014';
    const carTitle = isRTL ? (car.titleAr || car.title) : car.title;
    const waMsg = encodeURIComponent(
        isRTL
            ? `مرحباً، أريد الاستفسار عن: ${carTitle} (${car.year})\nالسعر: ${getFormattedPrice()}`
            : `Hello, I'm interested in: ${car.title} (${car.year})\nPrice: ${getFormattedPrice()}`
    );
    const waUrl = `https://wa.me/${wa.replace(/\D/g, '')}?text=${waMsg}`;

    const nextImage = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (images.length > 1) setCurrentImageIndex(p => (p + 1) % images.length);
    };
    const prevImage = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (images.length > 1) setCurrentImageIndex(p => (p - 1 + images.length) % images.length);
    };

    const fuelLabel = cleanKoreanText(car.fuelAr || car.fuelType || '', isRTL);
    const transmLabel = cleanKoreanText(car.transmissionAr || car.transmission || '', isRTL);
    const displayTitle = formatCarTitle(car.titleAr || car.title || `${car.makeAr || car.make} ${car.model}`, car.make || '', isRTL);

    return (
        <motion.div
            initial={{ opacity: 0, y: 40 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-40px" }}
            transition={{ duration: 0.5, delay: Math.min(index * 0.07, 0.4) }}
            onHoverStart={() => setShowHoverInfo(true)}
            onHoverEnd={() => setShowHoverInfo(false)}
            className="group relative flex flex-col bg-gradient-to-b from-[#1e1612] to-[#140f0a] rounded-2xl overflow-hidden border border-[#3d2c18]/60 hover:border-amber-500/40 transition-all duration-400 hover:shadow-2xl hover:shadow-amber-900/20 cursor-pointer"
            style={{ willChange: 'transform' }}
        >
            {/* ── منطقة الصورة ─────────────────────────────── */}
            <Link href={`/cars/${car.id}`} className="block">
                <div className="relative h-56 overflow-hidden bg-[#1a1108]">

                    {/* الصورة الرئيسية */}
                    {!imageError && currentImage ? (
                        <WatermarkImage
                            src={currentImage}
                            alt={displayTitle}
                            fill
                            sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                            className="object-cover transition-transform duration-700 group-hover:scale-105"
                            onError={() => setImageError(true)}
                            priority={index < 3}
                            showWatermark={true}
                            watermarkPosition="br"
                        />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-[#2a1e10] to-[#1a1108]">
                            <div className="text-center text-amber-900/60">
                                <Eye className="w-10 h-10 mx-auto mb-2" />
                                <p className="text-xs">{isRTL ? 'لا توجد صورة' : 'No image'}</p>
                            </div>
                        </div>
                    )}

                    {/* تدرج لوني سفلي */}
                    <div className="absolute inset-0 bg-gradient-to-t from-[#1e1612]/80 via-transparent to-transparent" />

                    {/* شارة مباع */}
                    {car.isSold && (
                        <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-20">
                            <div className="px-5 py-2 bg-red-600 text-white text-sm font-black rounded-xl rotate-[-12deg] shadow-xl">
                                {isRTL ? '🔴 تم البيع' : '🔴 SOLD'}
                            </div>
                        </div>
                    )}

                    {/* شارة المصدر */}
                    <div className="absolute top-3 start-3 flex flex-col gap-1.5 z-10">
                        {isKoreanImport && (
                            <span className="px-2.5 py-1 rounded-full bg-black/70 backdrop-blur-sm border border-amber-500/40 text-amber-300 text-[10px] font-bold flex items-center gap-1">
                                🇰🇷 {isRTL ? 'استيراد كوريا' : 'Korean Import'}
                            </span>
                        )}
                    </div>

                    {/* أزرار الإجراءات */}
                    <div className="absolute top-3 end-3 flex flex-col gap-2 z-10">
                        <motion.button
                            whileTap={{ scale: 0.85 }}
                            onClick={e => { e.preventDefault(); setIsLiked(!isLiked); }}
                            className="w-9 h-9 rounded-full bg-black/60 backdrop-blur-sm flex items-center justify-center transition-all"
                        >
                            <Heart className={`w-4 h-4 transition-all duration-300 ${isLiked ? 'fill-red-500 text-red-500' : 'text-white/80'}`} />
                        </motion.button>
                    </div>

                    {/* أسهم التنقل بين الصور */}
                    {images.length > 1 && (
                        <AnimatePresence>
                            {showHoverInfo && (
                                <>
                                    <motion.button
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        exit={{ opacity: 0 }}
                                        onClick={prevImage}
                                        className={`absolute top-1/2 -translate-y-1/2 ${isRTL ? 'end-2' : 'start-2'} w-8 h-8 rounded-full bg-black/70 backdrop-blur-sm flex items-center justify-center text-white z-10`}
                                    >
                                        <ArrowRight className={`w-4 h-4 ${isRTL ? '' : 'rotate-180'}`} />
                                    </motion.button>
                                    <motion.button
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        exit={{ opacity: 0 }}
                                        onClick={nextImage}
                                        className={`absolute top-1/2 -translate-y-1/2 ${isRTL ? 'start-2' : 'end-2'} w-8 h-8 rounded-full bg-black/70 backdrop-blur-sm flex items-center justify-center text-white z-10`}
                                    >
                                        <ArrowRight className={`w-4 h-4 ${isRTL ? 'rotate-180' : ''}`} />
                                    </motion.button>
                                </>
                            )}
                        </AnimatePresence>
                    )}

                    {/* نقاط الصور */}
                    {images.length > 1 && (
                        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1 z-10">
                            {images.slice(0, 6).map((_, idx) => (
                                <button
                                    key={idx}
                                    onClick={e => { e.preventDefault(); setCurrentImageIndex(idx); }}
                                    className={`rounded-full transition-all duration-300 ${idx === currentImageIndex ? 'w-4 h-1.5 bg-amber-400' : 'w-1.5 h-1.5 bg-white/40'}`}
                                />
                            ))}
                        </div>
                    )}

                    {/* عدد الصور */}
                    {images.length > 1 && (
                        <div className="absolute bottom-2 end-3 text-[10px] text-white/60 font-mono z-10">
                            {currentImageIndex + 1}/{images.length}
                        </div>
                    )}
                </div>
            </Link>

            {/* ── محتوى البطاقة ────────────────────────────── */}
            <div className="flex flex-col flex-1 p-4 gap-3">

                {/* العنوان */}
                <Link href={`/cars/${car.id}`}>
                    <h3 className="text-sm font-bold text-white leading-tight line-clamp-2 group-hover:text-amber-300 transition-colors duration-300">
                        {displayTitle}
                    </h3>
                </Link>

                {/* المواصفات السريعة */}
                <div className="flex items-center gap-3 flex-wrap">
                    <span className="flex items-center gap-1 text-[11px] text-amber-200/60">
                        <Calendar className="w-3 h-3" />
                        {car.year}
                    </span>
                    {car.mileage ? (
                        <span className="flex items-center gap-1 text-[11px] text-amber-200/60">
                            <Gauge className="w-3 h-3" />
                            {Number(car.mileage).toLocaleString(isRTL ? 'ar-SA' : 'en-US')}
                            {isRTL ? ' كم' : ' km'}
                        </span>
                    ) : null}
                    {fuelLabel ? (
                        <span className="flex items-center gap-1 text-[11px] text-amber-200/60">
                            <Fuel className="w-3 h-3" />
                            {fuelLabel}
                        </span>
                    ) : null}
                    {transmLabel ? (
                        <span className="flex items-center gap-1 text-[11px] text-amber-200/60">
                            <Settings2 className="w-3 h-3" />
                            {transmLabel}
                        </span>
                    ) : null}
                </div>

                {/* فاصل */}
                <div className="border-t border-[#3d2c18]/60" />

                {/* السعر والأزرار */}
                <div className="flex items-end justify-between gap-2 mt-auto">
                    <div>
                        <p className="text-[10px] text-amber-300/50 font-medium mb-0.5">
                            {isRTL ? 'السعر الإجمالي' : 'Total Price'}
                        </p>
                        <p className="text-xl font-black text-amber-400 leading-none tracking-tight">
                            {getFormattedPrice()}
                        </p>
                        {/* سعر ثانوي بالعملة الأخرى */}
                        {isKoreanImport && car.priceUsd && car.priceUsd > 0 && displayCurrency !== 'USD' && (
                            <p className="text-[10px] text-amber-200/40 mt-0.5">
                                ≈ ${Number(car.priceUsd).toLocaleString('en-US')}
                            </p>
                        )}
                    </div>

                    {/* زر واتساب + زر التفاصيل */}
                    <div className="flex items-center gap-2">
                        <a
                            href={waUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            onClick={e => e.stopPropagation()}
                            className="w-9 h-9 rounded-xl bg-emerald-600/20 border border-emerald-500/30 flex items-center justify-center hover:bg-emerald-600 transition-all duration-300"
                            title={isRTL ? 'تواصل عبر واتساب' : 'WhatsApp'}
                        >
                            <MessageCircle className="w-4 h-4 text-emerald-400" />
                        </a>
                        <Link
                            href={`/cars/${car.id}`}
                            className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-amber-500/15 border border-amber-500/30 hover:bg-amber-500 hover:border-amber-400 text-amber-300 hover:text-black text-xs font-bold transition-all duration-300"
                        >
                            <span>{isRTL ? 'التفاصيل' : 'Details'}</span>
                            <ArrowRight className={`w-3.5 h-3.5 ${isRTL ? 'rotate-180' : ''}`} />
                        </Link>
                    </div>
                </div>
            </div>

            {/* توهج عند الـ hover */}
            <div className="absolute inset-0 rounded-2xl ring-1 ring-amber-500/0 group-hover:ring-amber-500/20 transition-all duration-400 pointer-events-none" />
        </motion.div>
    );
}

'use client';

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { useLanguage } from "@/lib/LanguageContext";
import { 
  Car, Gavel, Wrench, User, LogIn, UserPlus, Globe, 
  MessageCircle, Instagram, Facebook, Youtube, 
  HelpCircle, Menu, X, Play, Pause, Volume2, VolumeX,
  ArrowRight, Shield, Zap, Award
} from "lucide-react";
import { useAuth } from "@/lib/AuthContext";
import { useTenant } from "@/lib/TenantContext";
import { api } from "@/lib/api-original";
import { cn } from "@/lib/utils";
import AuthModals from "./AuthModals";

const PARTICLES = Array.from({ length: 15 }, () => ({
    left: Math.random() * 100,
    top: Math.random() * 100,
    duration: 3 + Math.random() * 2,
    delay: Math.random() * 2,
}));

export default function ModernCarXHome() {
    const { isRTL, toggleLanguage } = useLanguage();
    const { user, isLoggedIn } = useAuth();
    const { tenant } = useTenant();
    const [marqueeItems, setMarqueeItems] = useState<string[]>([]);
    const [showMobileMenu, setShowMobileMenu] = useState(false);
    const [videoPlaying, setVideoPlaying] = useState(true);
    const [videoMuted, setVideoMuted] = useState(true);
    const [showLoginModal, setShowLoginModal] = useState(false);
    const [showRegisterModal, setShowRegisterModal] = useState(false);
    const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

    // تتبع حركة الفأرة للتأثيرات البصرية الفاخرة
    const handleMouseMove = (e: React.MouseEvent) => {
        const { clientX, clientY } = e;
        setMousePosition({ x: clientX, y: clientY });
    };

    // جلب بيانات السيارات للشريط الإعلاني
    useEffect(() => {
        api.cars.list({ limit: 12, status: 'available' })
            .then(res => {
                const cars = res?.data || res?.cars;
                if (cars && Array.isArray(cars) && cars.length > 0) {
                    const labels = cars.map((c: any) => {
                        const make = (isRTL && c.makeAr) ? c.makeAr : c.make;
                        const model = (isRTL && c.modelAr) ? c.modelAr : c.model;
                        const priceStr = c.price ? ` (${c.price.toLocaleString()} ${isRTL ? 'ر.س' : 'SAR'})` : '';
                        return `${make} ${model} ${c.year}${priceStr}`;
                    });
                    setMarqueeItems(labels);
                }
            }).catch(() => {});
    }, [isRTL]);

    const displayItems = marqueeItems.length > 0 
        ? marqueeItems 
        : [isRTL ? 'CAR X — المعرض · المزاد · قطع الغيار' : 'CAR X — SHOWROOM · AUCTIONS · PARTS'];
    
    const repeatedItems = Array(20).fill(0).map((_, i) => displayItems[i % displayItems.length]);

    // الأقسام الرئيسية
    const mainSections = [
        {
            title: isRTL ? 'المعارض' : 'Showrooms',
            desc: isRTL ? 'معرض CAR X المحلي ومعرض السيارات المستوردة' : 'Local CAR X & Imported Car Showrooms',
            icon: Car,
            href: '/showroom',
            color: 'from-red-600 to-red-800',
            hoverColor: 'hover:from-red-500 hover:to-red-700',
        },
        {
            title: isRTL ? 'المزادات المباشرة' : 'Live Auctions',
            desc: isRTL ? 'مزادات حصرية داخلية أو استيراد مزادات عالمية' : 'Exclusive auctions or import global auction links',
            icon: Gavel,
            href: '/auctions',
            color: 'from-gray-700 to-gray-900',
            hoverColor: 'hover:from-gray-600 hover:to-gray-800',
        }
    ];

    // روابط التواصل الاجتماعي
    const socialLinks = [
        { icon: Instagram, href: '#', color: 'text-pink-400 hover:text-pink-300' },
        { icon: Facebook, href: '#', color: 'text-blue-400 hover:text-blue-300' },
        { icon: Youtube, href: '#', color: 'text-red-400 hover:text-red-300' },
        { icon: MessageCircle, href: `https://wa.me/${tenant?.contact?.whatsapp?.replace(/\D/g, '')}`, color: 'text-green-400 hover:text-green-300' },
    ];

    return (
        <main className="relative min-h-screen overflow-x-hidden bg-black text-white" dir={isRTL ? "rtl" : "ltr"}>
            
            {/* ── التنقل العلوي (Luxury Header) ── */}
            <header className="fixed top-0 left-0 right-0 z-50 bg-black/40 backdrop-blur-3xl border-b border-white/5 shadow-[0_10px_30px_rgba(0,0,0,0.5)]">
                <div className="max-w-7xl mx-auto px-6 py-5 flex items-center justify-between">
                    
                    {/* الشعار والاسم بتأثير زجاجي متوهج */}
                    <div className="flex items-center gap-4 group cursor-pointer">
                        <motion.div 
                            whileHover={{ rotate: 360, scale: 1.1 }}
                            transition={{ duration: 0.8 }}
                            className="w-14 h-14 rounded-2xl bg-gradient-to-br from-red-600 via-red-700 to-black flex items-center justify-center shadow-[0_0_20px_rgba(220,38,38,0.4)] group-hover:shadow-red-600/60 transition-all"
                        >
                            <Car className="w-7 h-7 text-white" />
                        </motion.div>
                        <div className="flex flex-col">
                            <h1 className="text-2xl font-black text-white tracking-[0.2em] uppercase group-hover:text-red-500 transition-colors">
                                {tenant?.name?.split(' ')[0] || 'CAR'} <span className="text-red-600 group-hover:text-white transition-colors">{tenant?.name?.split(' ')[1] || 'X'}</span>
                            </h1>
                            <div className="h-0.5 w-0 group-hover:w-full bg-red-600 transition-all duration-500" />
                        </div>
                    </div>

                    {/* أزرار التسجيل والدخول - Desktop */}
                    <div className="hidden md:flex items-center gap-4">
                        {/* زر اللغة */}
                        <button
                            onClick={toggleLanguage}
                            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 hover:bg-white/10 border border-white/10 hover:border-white/20 transition-all"
                        >
                            <Globe className="w-4 h-4" />
                            <span className="text-sm font-bold">{isRTL ? 'EN' : 'عربي'}</span>
                        </button>

                        {/* خدمة العملاء */}
                        <button className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 hover:bg-white/10 border border-white/10 hover:border-white/20 transition-all">
                            <HelpCircle className="w-4 h-4" />
                            <span className="text-sm font-bold">{isRTL ? 'خدمة العملاء' : 'Support'}</span>
                        </button>

                        {!isLoggedIn ? (
                            <>
                                <button
                                    onClick={() => setShowLoginModal(true)}
                                    className="flex items-center gap-2 px-6 py-2 rounded-xl bg-white/10 hover:bg-white/20 border border-white/20 hover:border-white/30 transition-all"
                                >
                                    <LogIn className="w-4 h-4" />
                                    <span className="text-sm font-bold">{isRTL ? 'تسجيل الدخول' : 'Login'}</span>
                                </button>
                                <button
                                    onClick={() => setShowRegisterModal(true)}
                                    className="flex items-center gap-2 px-6 py-2 rounded-xl bg-gradient-to-r from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 transition-all"
                                >
                                    <UserPlus className="w-4 h-4" />
                                    <span className="text-sm font-bold">{isRTL ? 'حساب جديد' : 'Sign Up'}</span>
                                </button>
                            </>
                        ) : (
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-red-600 to-red-800 flex items-center justify-center">
                                    <User className="w-4 h-4 text-white" />
                                </div>
                                <span className="text-sm font-bold">{user?.name}</span>
                            </div>
                        )}
                    </div>

                    {/* زر القائمة - Mobile */}
                    <button
                        onClick={() => setShowMobileMenu(!showMobileMenu)}
                        className="md:hidden w-10 h-10 rounded-xl bg-white/10 flex items-center justify-center"
                    >
                        {showMobileMenu ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
                    </button>
                </div>

                {/* القائمة المنسدلة - Mobile */}
                <AnimatePresence>
                    {showMobileMenu && (
                        <motion.div
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            exit={{ opacity: 0, height: 0 }}
                            className="md:hidden bg-black/95 border-t border-red-600/20 px-4 py-6"
                        >
                            <div className="space-y-4">
                                <button
                                    onClick={toggleLanguage}
                                    className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-white/5 hover:bg-white/10"
                                >
                                    <Globe className="w-5 h-5" />
                                    <span>{isRTL ? 'English' : 'عربي'}</span>
                                </button>
                                
                                <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-white/5 hover:bg-white/10">
                                    <HelpCircle className="w-5 h-5" />
                                    <span>{isRTL ? 'خدمة العملاء' : 'Support'}</span>
                                </button>

                                {!isLoggedIn ? (
                                    <>
                                        <button
                                            onClick={() => {
                                                setShowLoginModal(true);
                                                setShowMobileMenu(false);
                                            }}
                                            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-white/10 hover:bg-white/20"
                                        >
                                            <LogIn className="w-5 h-5" />
                                            <span>{isRTL ? 'تسجيل الدخول' : 'Login'}</span>
                                        </button>
                                        <button
                                            onClick={() => {
                                                setShowRegisterModal(true);
                                                setShowMobileMenu(false);
                                            }}
                                            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-gradient-to-r from-red-600 to-red-700"
                                        >
                                            <UserPlus className="w-5 h-5" />
                                            <span>{isRTL ? 'حساب جديد' : 'Sign Up'}</span>
                                        </button>
                                    </>
                                ) : (
                                    <div className="flex items-center gap-3 px-4 py-3">
                                        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-red-600 to-red-800 flex items-center justify-center">
                                            <User className="w-4 h-4 text-white" />
                                        </div>
                                        <span>{user?.name}</span>
                                    </div>
                                )}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </header>

            {/* ── أيقونات التواصل الاجتماعي الثابتة ── */}
            <div className={`fixed top-1/2 -translate-y-1/2 z-40 flex flex-col gap-3 ${isRTL ? 'right-4' : 'left-4'}`}>
                {socialLinks.map((social, idx) => (
                    <motion.a
                        key={idx}
                        href={social.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        initial={{ opacity: 0, x: isRTL ? 20 : -20 }}
                        animate={{ 
                            opacity: 1, 
                            x: 0,
                            y: [0, -5, 0]
                        }}
                        transition={{ 
                            delay: idx * 0.1,
                            y: {
                                duration: 2,
                                repeat: Infinity,
                                delay: idx * 0.3,
                                ease: "easeInOut"
                            }
                        }}
                        whileHover={{ 
                            scale: 1.2,
                            rotate: 5,
                            boxShadow: "0 0 25px rgba(255,0,0,0.5)"
                        }}
                        className={`w-12 h-12 rounded-2xl bg-black/60 backdrop-blur-md border border-white/10 flex items-center justify-center ${social.color} transition-all duration-300 hover:bg-white/10`}
                    >
                        <social.icon className="w-5 h-5" />
                    </motion.a>
                ))}
            </div>

            {/* ── فيديو الخلفية مع تحكم وتأثير عمق ── */}
            <section 
                className="relative h-[110vh] flex items-center justify-center overflow-hidden"
                onMouseMove={handleMouseMove}
            >
                {/* تأثير الإضاءة الملاحقة (Spotlight) */}
                <div 
                    className="pointer-events-none fixed inset-0 z-30 transition-opacity duration-1000"
                    style={{
                        background: `radial-gradient(circle 600px at ${mousePosition.x}px ${mousePosition.y}px, rgba(220, 38, 38, 0.05), transparent 80%)`
                    }}
                />

                {/* الفيديو بتأثير Parallax */}
                <motion.div 
                    className="absolute inset-0 w-full h-[120%]"
                    style={{ y: -50 }}
                >
                    <video
                        autoPlay
