interface SocialLinksProps {
    className?: string;
    size?: 'sm' | 'md' | 'lg';
    showLabels?: boolean;
    vertical?: boolean;
}

// لا توجد قيم افتراضية - فقط الروابط التي يضيفها الأدمن تظهر
const emptySocialLinks = {
    whatsapp: '',
    instagram: '',
    twitter: '',
    facebook: '',
    youtube: '',
    tiktok: '',
    snapchat: '',
    telegram: '',
    linkedin: ''
};

export default function SocialLinks({
    className,
    size = 'md',
    vertical = false
}: SocialLinksProps) {
    const [socialLinks, setSocialLinks] = useState(emptySocialLinks);

    const loadSocialLinks = async () => {
        try {
            // جلب روابط التواصل الاجتماعي من الإعدادات العامة للموقع
            const response = await api.settings.getPublic();
            if (response.success && response.data.socialLinks) {
                // دمج الروابط المجلوبة مع القائمة الفارغة لضمان وجود جميع الحقول
                setSocialLinks({ ...emptySocialLinks, ...response.data.socialLinks });
            } else {
                setSocialLinks(emptySocialLinks);
            }
        } catch {
            console.error('Failed to load social links');
            setSocialLinks(emptySocialLinks);
        }
    };

    useEffect(() => {
        loadSocialLinks();
    }, []);

    const sizeClasses = {
        sm: 'w-8 h-8 md:w-10 md:h-10',
        md: 'w-10 h-10 md:w-12 md:h-12',
        lg: 'w-12 h-12 md:w-14 md:h-14'
    };

    const iconSizes = {
        sm: 'w-4 h-4 md:w-5 md:h-5',
        md: 'w-5 h-5 md:w-6 md:h-6',
        lg: 'w-6 h-6 md:w-7 md:h-7'
    };

    // نقوم بتعطيل الصور المخصصة للواتساب لتطبيق SVG دائري عصري
    const customIcons: { [key: string]: string } = {
        instagram: '/images/icons/instagram.jpg',
        facebook: '/images/icons/facebook.jpg',
        tiktok: '/images/icons/tiktok.jpg',
    };

    const links = [
        {
            key: 'whatsapp',
            icon: WhatsAppIcon,
            color: 'bg-green-500 hover:bg-green-600 text-white shadow-[0_4px_14px_rgba(37,211,102,0.35)]',
            href: socialLinks.whatsapp ? `https://wa.me/${socialLinks.whatsapp.replace(/[^0-9]/g, '')}` : null,
            label: 'WhatsApp'
        },
        {
            key: 'instagram',
            icon: Instagram,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.instagram,
            label: 'Instagram'
        },
        {
            key: 'twitter',
            icon: XIcon,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.twitter,
            label: 'X'
        },
        {
            key: 'facebook',
            icon: Facebook,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.facebook,
            label: 'Facebook'
        },
        {
            key: 'youtube',
            icon: Youtube,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.youtube,
            label: 'YouTube'
        },
        {
            key: 'tiktok',
            icon: TikTokIcon,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.tiktok,
            label: 'TikTok'
        },
        {
            key: 'snapchat',
            icon: SnapchatIcon,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.snapchat ? `https://snapchat.com/add/${socialLinks.snapchat}` : null,
            label: 'Snapchat'
        },
        {
            key: 'telegram',
            icon: Send,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.telegram,
            label: 'Telegram'
        },
        {
            key: 'linkedin',
            icon: Linkedin,
            color: 'bg-white/5 hover:bg-white/10 border border-white/10 text-white',
            href: socialLinks.linkedin,
            label: 'LinkedIn'
        }
    ].filter(link => link.href);

    if (links.length === 0) return null;

    return (
        <div className={cn(
            "flex gap-3",
            vertical ? "flex-col" : "flex-row flex-wrap",
            className
        )}>
            {links.map((link, i) => (
                <motion.a
                    key={link.key}
                    href={link.href!}
                    target="_blank"
                    rel="noopener noreferrer"
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: i * 0.05 }}
                    whileHover={{ scale: 1.1, y: -4 }}
                    whileTap={{ scale: 0.95 }}
                    className={cn(
                        "flex items-center justify-center rounded-full transition-all shadow-2xl overflow-hidden",
                        sizeClasses[size],
                        link.color
                    )}
                    title={link.label}
                >
                    {/* استخدام الصور المخصصة إذا كانت موجودة، وإلا العودة للأيقونة الافتراضية */}
                    {customIcons[link.key] ? (
                        <>
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                            src={customIcons[link.key]}
                            alt={link.label}
                            className="w-full h-full object-cover"
                        />
                        </>
                    ) : (
                        <link.icon className={iconSizes[size]} />
                    )}
                </motion.a>
            ))}
        </div>
    );
}

/**
 * الزر العائم للواتساب (WhatsApp Floating Action Button)
 * يظهر في زاوية الشاشة ليتيح للمستخدم التواصل المباشر والسريع مع الدعم الفني.
 */
export function WhatsAppFAB() {
    const [whatsappNumber, setWhatsappNumber] = useState('+967781007805');

    useEffect(() => {
        api.settings.getPublic().then((res: { success: boolean; data: { socialLinks?: { whatsapp?: string } } }) => {
            if (res?.success && res.data.socialLinks?.whatsapp) {
                setWhatsappNumber(res.data.socialLinks.whatsapp);
            }
        }).catch(() => { });
    }, []);

    return (
        <motion.a
            href={`https://wa.me/${whatsappNumber.replace(/[^0-9]/g, '')}`}
            target="_blank"
            rel="noopener noreferrer"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.95 }}
            className="fixed bottom-6 right-6 z-50 w-14 h-14 rounded-full flex items-center justify-center shadow-[0_4px_24px_rgba(37,211,102,0.45)] hover:shadow-[0_4px_30px_rgba(37,211,102,0.65)] transition-all border border-white/20"
            style={{
                background: 'linear-gradient(135deg, #25D366, #128C7E)',
                borderRadius: '50%'
            }}
            aria-label="WhatsApp"
        >
            <WhatsAppIcon className="w-7 h-7 text-white" />
        </motion.a>
    );
}

'use client';

/**
 * UltraModernCarCard - بطاقة السيارة الإبداعية المذهلة
 * تصميم ثوري مع تأثيرات ثلاثية الأبعاد وحركات متقدمة
 */

import React, { useState, useRef } from "react";
import { motion, useMotionValue, useTransform, useSpring, AnimatePresence } from "framer-motion";
import { 
    Heart, Share2, Eye, Calendar, Gauge, Fuel, Camera,
    Home, ArrowRight, Sparkles, Crown
} from "lucide-react";
import { useLanguage } from "@/lib/LanguageContext";
import WatermarkImage from "@/components/WatermarkImage";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useTenant } from "@/lib/TenantContext";
import { getTenantApiUrl } from "@/lib/tenant-config";
import { getProxiedImageUrl } from "@/lib/imageUtils";


interface UltraModernCarCardProps {
    car: {
        id: string;
        title: string;
        make: string;
        model: string;
        year: number;
        price: number;
        priceSar?: number;
        priceUsd?: number;
        images: string[];
        imageUrl?: string;
        mileage?: number;
        fuelType?: string;
        transmission?: string;
        category?: string;
        isActive?: boolean;
        isSold?: boolean;
        source?: string;
        isInspected?: boolean;
        condition?: string;
    };
    index: number;
    formatPrice?: (price: number) => string;
    onContact?: (car: UltraModernCarCardProps['car']) => void;
    onViewDetails?: (car: UltraModernCarCardProps['car']) => void;
}

export default function UltraModernCarCard({ 
    car, 
    index, 
    formatPrice, 
    onContact, 
    onViewDetails 
}: UltraModernCarCardProps) {
    const { isRTL } = useLanguage();
    const router = useRouter();
    const cardRef = useRef<HTMLDivElement>(null);
    const { tenant } = useTenant();
    const tenantApiUrl = getTenantApiUrl();
    
    // Motion values للتأثيرات ثلاثية الأبعاد المتقدمة
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const rotateX = useTransform(y, [-300, 300], [15, -15]);
    const rotateY = useTransform(x, [-300, 300], [-15, 15]);
    const scale = useSpring(1, { stiffness: 300, damping: 30 });
    
    const [currentImageIndex, setCurrentImageIndex] = useState(0);
    const [isLiked, setIsLiked] = useState(false);
    const [imageError, setImageError] = useState(false);
    const [showImageGallery, setShowImageGallery] = useState(false);

    const handleBackToHome = () => {
        router.push('/');
    };

    const handleImageError = () => {
        setImageError(true);
    };

    const nextImage = () => {
        if (car.images && car.images.length > 1) {
            setCurrentImageIndex((prev) => (prev + 1) % car.images.length);
        }
    };

    const prevImage = () => {
        if (car.images && car.images.length > 1) {
            setCurrentImageIndex((prev) => (prev - 1 + car.images.length) % car.images.length);
        }
    };

    // إصلاح وعرض صور السيارات مع علامة HM CAR المائية
    const resolveCarImage = (imageUrl: string | undefined): string => {
        return getProxiedImageUrl(imageUrl);
    };

    const currentImage = car.images?.[currentImageIndex] || car.imageUrl || '';
    const resolvedImage = resolveCarImage(currentImage);
    const displayPrice = formatPrice ? formatPrice(car.price) : `${car.price?.toLocaleString()} ${isRTL ? 'ر.س' : 'SAR'}`;

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        if (!cardRef.current) return;
        const rect = cardRef.current.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;
        x.set((e.clientX - centerX) * 0.1);
        y.set((e.clientY - centerY) * 0.1);
    };

    const handleMouseLeave = () => {
        x.set(0);
        y.set(0);
        scale.set(1);
    };

    const handleMouseEnter = () => {
        scale.set(1.02);
    };

    return (
        <motion.div
            ref={cardRef}
            initial={{ opacity: 0, y: 60, rotateX: -10 }}
            whileInView={{ opacity: 1, y: 0, rotateX: 0 }}
            viewport={{ once: true }}
            transition={{ 
                duration: 0.8, 
                delay: index * 0.1,
                type: "spring",
                stiffness: 100
            }}
            style={{
                rotateX,
                rotateY,
                scale,
                transformStyle: "preserve-3d",
            }}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            onMouseEnter={handleMouseEnter}
            className="group relative perspective-1000"
        >
            <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-gray-900/80 via-black to-gray-900/80 border border-white/10 hover:border-red-500/30 transition-all duration-700 shadow-2xl hover:shadow-red-500/20">
                
                {/* خلفية هولوجرافية متحركة */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-1000">
                    <div className="absolute inset-0 bg-gradient-to-br from-red-500/10 via-purple-500/5 to-blue-500/10 animate-pulse" />
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(255,0,0,0.1)_0%,transparent_50%)] animate-pulse" />
                </div>

                {/* شبكة نيون متحركة */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-700">
                    <div className="absolute inset-0 bg-[linear-gradient(rgba(255,0,0,0.1)_1px,transparent_1px),linear-gradient(90deg,rgba(255,0,0,0.1)_1px,transparent_1px)] bg-[size:30px_30px] animate-pulse" />
                </div>

                {/* Status Badge */}
                {car.isSold && (
                    <div className="absolute top-4 start-4 z-30 px-4 py-2 bg-red-600/90 backdrop-blur-md text-white text-xs font-black rounded-2xl border border-red-500/50 shadow-lg">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
                            {isRTL ? 'مباع' : 'SOLD'}
                        </div>
                    </div>
                )}

                {/* Korean Import Badge */}
                {car.source === 'korean_import' && (
                    <div className="absolute top-4 start-4 z-30 px-3 py-1.5 bg-blue-600/90 backdrop-blur-md text-white text-xs font-black rounded-xl border border-blue-500/50 shadow-lg">
                        <div className="flex items-center gap-1">
                            <span>🇰🇷</span>
                            {isRTL ? 'كوري' : 'Korean'}
                        </div>
                    </div>
                )}

                {/* Inspection Badge */}
                {car.isInspected && (
                    <div className="absolute top-16 start-4 z-30 px-3 py-1.5 bg-green-600/90 backdrop-blur-md text-white text-xs font-black rounded-xl border border-green-500/50 shadow-lg">
                        <div className="flex items-center gap-1">
                            <Sparkles className="w-3 h-3" />
                            {isRTL ? 'مفحوص' : 'Inspected'}
                        </div>
                    </div>
                )}

                {/* Image Section */}
                <div className="relative h-64 overflow-hidden">
                    {/* Main Image */}
                    <div className="relative w-full h-full">
                        {!imageError ? (
                            <WatermarkImage
                                src={resolvedImage}
                                alt={car.title}
                                fill
                                className="object-cover transition-all duration-1000 group-hover:scale-110 group-hover:rotate-1"
                                onError={handleImageError}
                                priority={index < 4}
                                showWatermark={true}
                                watermarkPosition="br"
                            />
                        ) : (
                            <div className="w-full h-full bg-gradient-to-br from-gray-800 to-gray-900 flex items-center justify-center">
                                <div className="text-center text-white/40">
                                    <div className="w-20 h-20 mx-auto mb-4 rounded-3xl bg-white/10 flex items-center justify-center">
                                        <Eye className="w-10 h-10" />
                                    </div>
                                    <p className="text-sm font-bold">{isRTL ? 'صورة غير متوفرة' : 'Image not available'}</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* شبكة نيون متحركة */}
                    <div className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-700">
                        <div className="absolute inset-0 bg-[linear-gradient(rgba(255,0,0,0.1)_1px,transparent_1px),linear-gradient(90deg,rgba(255,0,0,0.1)_1px,transparent_1px)] bg-[size:30px_30px] animate-pulse" />
                    </div>

                    {/* Image Navigation */}
                    {car.images && car.images.length > 1 && (
                        <>
                            <button
                                onClick={prevImage}
                                aria-label="Previous image"
                                className={`absolute top-1/2 -translate-y-1/2 ${isRTL ? 'right-3' : 'left-3'} w-10 h-10 rounded-2xl bg-black/70 backdrop-blur-md flex items-center justify-center text-white/80 hover:text-white hover:bg-black/90 transition-all opacity-0 group-hover:opacity-100 border border-white/20`}
                            >
                                <ArrowRight className={`w-5 h-5 ${isRTL ? '' : 'rotate-180'}`} />
                            </button>
                            <button
                                onClick={nextImage}
                                aria-label="Next image"
                                className={`absolute top-1/2 -translate-y-1/2 ${isRTL ? 'left-3' : 'right-3'} w-10 h-10 rounded-2xl bg-black/70 backdrop-blur-md flex items-center justify-center text-white/80 hover:text-white hover:bg-black/90 transition-all opacity-0 group-hover:opacity-100 border border-white/20`}
                            >
                                <ArrowRight className={`w-5 h-5 ${isRTL ? 'rotate-180' : ''}`} />
                            </button>
                        </>
                    )}

                    {/* Image Indicators */}
                    {car.images && car.images.length > 1 && (
                        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-2">
                            {car.images.map((_, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => setCurrentImageIndex(idx)}
                                    aria-label={`Image ${idx + 1}`}
                                    className={`w-2 h-2 rounded-full transition-all ${
                                        idx === currentImageIndex
                                            ? 'bg-red-500 shadow-[0_0_10px_rgba(255,0,0,0.8)]'
                                            : 'bg-white/30 hover:bg-white/50'
                                    }`}
                                />
                            ))}
                        </div>
                    )}

                    {/* زر الرجوع للصفحة الرئيسية */}
                    <div className="absolute top-4 end-4">
                        <motion.button
                            onClick={handleBackToHome}
                            whileHover={{ scale: 1.1, rotate: 5 }}
                            whileTap={{ scale: 0.9 }}
                            className="w-12 h-12 rounded-2xl bg-black/70 backdrop-blur-md border border-white/20 hover:border-red-500/50 flex items-center justify-center text-white/80 hover:text-red-400 hover:bg-black/90 transition-all duration-300 group/back shadow-lg"
                            title={isRTL ? 'العودة للصفحة الرئيسية' : 'Back to Home'}
                        >
                            <Home className="w-6 h-6 group-hover/back:scale-110 transition-transform" />
                        </motion.button>
                    </div>

                    {/* زر المفضلة - أيقونة قلب حرة وأنيقة بدون مربع محدد */}
                    <div className="absolute top-4 end-4 z-30">
                        <motion.button
                            onClick={(e) => {
                                e.stopPropagation();
                                setIsLiked(!isLiked);
                            }}
                            aria-label={isLiked ? 'Unlike' : 'Like'}
                            whileHover={{ scale: 1.2 }}
                            whileTap={{ scale: 0.8 }}
                            animate={isLiked ? { scale: [1, 1.35, 0.9, 1.15, 1] } : { scale: 1 }}
                            transition={{ duration: 0.35 }}
                            className="p-2 border-none bg-transparent hover:scale-115 transition-all duration-300 cursor-pointer shadow-none outline-none focus:outline-none flex items-center justify-center"
                        >
                            <Heart className={`w-6 h-6 transition-all duration-300 ${
                                isLiked
                                    ? 'fill-red-500 text-red-500 drop-shadow-[0_0_12px_rgba(239,68,68,0.95)]'
                                    : 'text-white/90 drop-shadow-[0_2px_8px_rgba(0,0,0,0.9)] hover:text-red-400'
                            }`} />
                        </motion.button>
                    </div>
                        
                        <motion.button
                            aria-label="Share"
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 0.9 }}
                            className="w-12 h-12 rounded-2xl bg-black/70 backdrop-blur-md border border-white/20 hover:border-blue-400/50 flex items-center justify-center text-white/80 hover:text-blue-400 hover:bg-blue-500/20 transition-all duration-300 shadow-lg"
                        >
                            <Share2 className="w-5 h-5" />
                        </motion.button>

                        <motion.button
                            onClick={() => setShowImageGallery(true)}
                            aria-label="View gallery"
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 0.9 }}
                            className="w-12 h-12 rounded-2xl bg-black/70 backdrop-blur-md border border-white/20 hover:border-purple-400/50 flex items-center justify-center text-white/80 hover:text-purple-400 hover:bg-purple-500/20 transition-all duration-300 shadow-lg"
                        >
                            <Camera className="w-5 h-5" />
                        </motion.button>
                    </div>

                    {/* Gradient Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent" />
                </div>

                {/* Content Section */}
                <div className="p-6 space-y-4">
                    {/* Title and Year */}
                    <div className="space-y-2">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Crown className="w-4 h-4 text-yellow-400" />
                                <span className="text-xs font-black text-yellow-400 uppercase tracking-wider">
                                    {car.make}
                                </span>
                            </div>
                            <div className="flex items-center gap-1">
                                <Calendar className="w-4 h-4 text-white/60" />
                                <span className="text-sm font-bold text-white/80">{car.year}</span>
                            </div>
                        </div>
                        
                        <h3 className="text-xl font-black text-white group-hover:text-red-100 transition-colors duration-300 line-clamp-2 leading-tight">
                            {car.title}
                        </h3>
                    </div>

                    {/* Car Details */}
                    <div className="grid grid-cols-2 gap-4">
                        {car.mileage && (
                            <div className="flex items-center gap-2 p-3 bg-white/5 rounded-xl border border-white/10 group-hover:border-red-500/30 transition-all">
                                <Gauge className="w-4 h-4 text-blue-400" />
                                <div>
                                    <p className="text-xs text-white/50 font-medium">{isRTL ? 'المسافة' : 'Mileage'}</p>
                                    <p className="text-sm font-bold text-white">{car.mileage?.toLocaleString()}</p>
                                </div>
                            </div>
                        )}
                        
                        {car.fuelType && (
                            <div className="flex items-center gap-2 p-3 bg-white/5 rounded-xl border border-white/10 group-hover:border-red-500/30 transition-all">
                                <Fuel className="w-4 h-4 text-green-400" />
                                <div>
                                    <p className="text-xs text-white/50 font-medium">{isRTL ? 'الوقود' : 'Fuel'}</p>
                                    <p className="text-sm font-bold text-white">{car.fuelType}</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Price and Action */}
                    <div className="flex items-center justify-between pt-4 border-t border-white/10">
                        <div>
                            <p className="text-xs text-white/50 font-medium mb-1">{isRTL ? 'السعر' : 'Price'}</p>
                            <p className="text-2xl font-black text-red-400">{displayPrice}</p>
                        </div>
                        
                        <div className="flex gap-2">
                            {onContact && (
                                <motion.button
                                    onClick={() => onContact(car)}
                                    whileHover={{ scale: 1.05 }}
                                    whileTap={{ scale: 0.95 }}
                                    className="px-4 py-2 bg-white/10 hover:bg-white/20 border border-white/20 hover:border-white/40 rounded-xl font-bold text-sm text-white transition-all"
                                >
                                    {isRTL ? 'تواصل' : 'Contact'}
                                </motion.button>
                            )}
                            
                            <motion.button
                                onClick={() => onViewDetails?.(car)}
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                className="px-6 py-2 bg-gradient-to-r from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 rounded-xl font-bold text-sm text-white transition-all flex items-center gap-2 shadow-lg"
                            >
                                <span>{isRTL ? 'التفاصيل' : 'Details'}</span>
                                <ArrowRight className={`w-4 h-4 ${isRTL ? 'rotate-180' : ''}`} />
                            </motion.button>
                        </div>
                    </div>
                </div>

                {/* Hover Glow Effect */}
                <div className="absolute inset-0 rounded-3xl bg-gradient-to-br from-red-500/0 via-red-500/0 to-red-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
                
                {/* Holographic Border */}
                <div className="absolute inset-0 rounded-3xl border border-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none [background:linear-gradient(45deg,transparent,rgba(255,0,0,0.3),transparent)] [mask:linear-gradient(#fff_0_0)_content-box,linear-gradient(#fff_0_0)] [mask-composite:xor]" />

            {/* Image Gallery Modal */}
            <AnimatePresence>
                {showImageGallery && car.images && car.images.length > 0 && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4"
                        onClick={() => setShowImageGallery(false)}
                    >
                        <motion.div
                            initial={{ scale: 0.8, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.8, opacity: 0 }}
                            className="relative max-w-4xl w-full aspect-video bg-black rounded-2xl overflow-hidden"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <Image
                                src={resolveCarImage(car.images[currentImageIndex])}
                                alt={`${car.title} - Image ${currentImageIndex + 1}`}
                                fill
                                className="object-contain"
                            />
                            
                            <button
                                onClick={() => setShowImageGallery(false)}
                                aria-label="Close gallery"
                                className="absolute top-4 right-4 w-10 h-10 bg-black/50 hover:bg-black/70 rounded-full flex items-center justify-center text-white transition-all"
                            >
                                ×
                            </button>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
}

'use client';

/**
 * UltraModernPartCard - بطاقة قطعة الغيار الإبداعية المذهلة
 * تصميم ثوري مع تأثيرات ثلاثية الأبعاد وحركات متقدمة
 */

import React, { useState, useCallback } from 'react';
import Image from 'next/image';
import WatermarkImage from '@/components/WatermarkImage';
import { motion, useMotionValue, useTransform, useSpring } from 'framer-motion';
import { 
    Heart, ShoppingCart, Check, Wrench, Package, Coins, FileText, 
    Home, Star, Crown, Settings, Cog, Diamond, Flame
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useLanguage } from '@/lib/LanguageContext';
import { useAuth } from '@/lib/AuthContext';
import { useSettings } from '@/lib/SettingsContext';
import { useRouter } from 'next/navigation';
import type { CartItem } from '@/types';
import CurrencySwitcher from '@/components/CurrencySwitcher';

const FAVORITES_KEY = 'hm_favorites';
const CART_KEY = 'hm_cart';

function getFavorites(): string[] {
    try { return JSON.parse(localStorage.getItem(FAVORITES_KEY) || '[]'); } catch { return []; }
}
function getCart(): CartItem[] {
    try { return JSON.parse(localStorage.getItem(CART_KEY) || '[]'); } catch { return []; }
}
function dispatchCartUpdate() {
    window.dispatchEvent(new CustomEvent('cart_updated'));
}

interface UltraModernPartCardProps {
    part: {
        id?: string;
        _id?: string;
        name: string;
        nameAr?: string;
        img?: string;
        images?: string[];
        price?: number;
        priceSar?: number;
        priceUsd?: number;
        stockQty?: number;
        stock?: number;
        brand?: string;
        brandName?: string;
        category?: string;
        categoryAr?: string;
        condition?: string;
        description?: string;
        descriptionAr?: string;
    };
    index?: number;
    onClick?: () => void;
    onLoginRequired?: () => void;
}

function resolvePartCardImg(part: any): string {
    const raw = part.img || part.image || (Array.isArray(part.images) && part.images.length > 0 ? part.images[0] : '') || '';
    if (!raw || typeof raw !== 'string') return 'https://images.unsplash.com/photo-1486262715619-67b85e0b08d3?q=80&w=1000';
    let url = raw.trim();
    if (url.startsWith('//')) url = `https:${url}`;
    else if (url.startsWith('/')) {
        if (url.startsWith('/uploads') || url.startsWith('/images')) return url;
        url = `https://autospare.com.eg${url}`;
    } else if (!url.startsWith('http')) {
        url = `https://autospare.com.eg/${url}`;
    }
    if (url.includes('autospare.com.eg') || url.includes('encar.com')) {
        return `/api/v2/image-proxy?url=${encodeURIComponent(url)}`;
    }
    return url;
}

export default function UltraModernPartCard({ 
    part, 
    index = 0, 
    onClick, 
    onLoginRequired 
}: UltraModernPartCardProps) {
    const { isRTL } = useLanguage();
    const { isLoggedIn } = useAuth();
    const { formatPrice, socialLinks } = useSettings() as any;
    const router = useRouter();

    const cardKey = String(part.id || part._id || `part-${index}`);
    const imageSrc = resolvePartCardImg(part);
    const name = isRTL ? (part.nameAr || part.name) : (part.name || part.nameAr);
    const stock = part.stockQty ?? part.stock ?? 0;

    // Motion values للتأثيرات ثلاثية الأبعاد المتقدمة
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const rotateX = useTransform(y, [-200, 200], [15, -15]);
    const rotateY = useTransform(x, [-200, 200], [-15, 15]);
    const scale = useSpring(1, { stiffness: 300, damping: 30 });

    const [imgError, setImgError] = useState(false);
    const [isFav, setIsFav] = useState(() => getFavorites().includes(cardKey));
    const [inCart, setInCart] = useState(() => getCart().some((i: CartItem) => i.id === cardKey));
    const [cartAdded, setCartAdded] = useState(false);

    const handleBackToHome = () => {
        router.push('/');
    };

    const toggleFav = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isLoggedIn) { onLoginRequired?.(); return; }
        const favs = getFavorites();
        const next = favs.includes(cardKey)
            ? favs.filter(id => id !== cardKey)
            : [...favs, cardKey];
        localStorage.setItem(FAVORITES_KEY, JSON.stringify(next));
        setIsFav(!isFav);
        window.dispatchEvent(new CustomEvent('favorites_updated'));
    }, [cardKey, isFav, isLoggedIn, onLoginRequired]);

    const addToCart = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isLoggedIn) { onLoginRequired?.(); return; }
        if (inCart || stock === 0) return;
        const cart = getCart();
        cart.push({ ...part, price: part.price ?? part.priceSar ?? 0, id: cardKey, type: 'part', quantity: 1 });
        localStorage.setItem(CART_KEY, JSON.stringify(cart));
        dispatchCartUpdate();
        setInCart(true);
        setCartAdded(true);
        setTimeout(() => setCartAdded(false), 2000);
    }, [part, cardKey, inCart, stock, isLoggedIn, onLoginRequired]);

    const price = Number(part.price || part.priceSar || 0);
    const displayPrice = formatPrice ? formatPrice(price) : `${price.toLocaleString()} SAR`;

    const stockColor = stock > 5 ? 'text-emerald-400' : stock > 0 ? 'text-amber-400' : 'text-red-400';
    const stockBg = stock > 5 ? 'bg-emerald-500/10' : stock > 0 ? 'bg-amber-500/10' : 'bg-red-500/10';
    const stockBorder = stock > 5 ? 'border-emerald-500/30' : stock > 0 ? 'border-amber-500/30' : 'border-red-500/30';
    const stockLabel = stock > 5
        ? (isRTL ? 'متوفر' : 'Available')
        : stock > 0
            ? (isRTL ? `${stock} فقط` : `${stock} left`)
            : (isRTL ? 'نفد' : 'Sold Out');

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;
        x.set((e.clientX - centerX) * 0.1);
        y.set((e.clientY - centerY) * 0.1);
    };

    const handleMouseLeave = () => {
        x.set(0);
        y.set(0);
        scale.set(1);
    };

    const handleMouseEnter = () => {
        scale.set(1.02);
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 50, rotateX: -10 }}
            whileInView={{ opacity: 1, y: 0, rotateX: 0 }}
            viewport={{ once: true }}
            transition={{ 
                delay: (index % 4) * 0.1, 
                duration: 0.7,
                type: "spring",
                stiffness: 100
            }}
            style={{
                rotateX,
                rotateY,
                scale,
                transformStyle: "preserve-3d",
            }}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            onMouseEnter={handleMouseEnter}
            className="group relative perspective-1000"
        >
            <div
                onClick={onClick}
                className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-gray-900/90 via-black to-gray-900/90 border border-white/10 hover:border-amber-400/40 transition-all duration-700 cursor-pointer shadow-2xl hover:shadow-amber-400/20"
            >
                {/* خلفية هولوجرافية متحركة */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-1000">
                    <div className="absolute inset-0 bg-gradient-to-br from-amber-500/10 via-orange-500/5 to-yellow-500/10 animate-pulse" />
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_70%,rgba(245,158,11,0.15)_0%,transparent_70%)] animate-pulse" />
                </div>

                {/* شبكة نيون متحركة */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-15 transition-opacity duration-700">
                    <div className="absolute inset-0 bg-[linear-gradient(rgba(245,158,11,0.1)_1px,transparent_1px),linear-gradient(90deg,rgba(245,158,11,0.1)_1px,transparent_1px)] bg-[size:20px_20px] animate-pulse" />
                </div>

                {/* جسيمات متحركة */}
                <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-1000">
                    {[...Array(12)].map((_, i) => (
                        <motion.div
                            key={i}
                            className="absolute w-1 h-1 bg-amber-400 rounded-full"
                            style={{
                                left: `${15 + i * 7}%`,
                                top: `${20 + i * 6}%`,
                            }}
                            animate={{
                                y: [-15, -40, -15],
                                opacity: [0, 1, 0],
                                scale: [0, 1.5, 0],
                            }}
                            transition={{
                                duration: 2.5,
                                repeat: Infinity,
                                delay: i * 0.15,
                            }}
                        />
                    ))}
                </div>

                {/* ── صورة القطعة ── */}
                <div className="relative aspect-square bg-gradient-to-br from-white/5 to-transparent overflow-hidden">
                    {!imgError && imageSrc ? (
                        <WatermarkImage
                            src={imageSrc}
                            alt={name || ''}
                            fill
                            className="object-cover group-hover:scale-110 transition-transform duration-1000 group-hover:rotate-2"
                            onError={() => setImgError(true)}
                            unoptimized
                            watermarkPosition="br"
                        />
                    ) : (
                        <div className="absolute inset-0 flex items-center justify-center">
                            <div className="relative">
                                <Wrench className="w-20 h-20 text-white/10 group-hover:text-amber-500/30 transition-colors duration-500" />
                                {/* تأثير التوهج للأيقونة */}
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <Wrench className="w-20 h-20 text-amber-500/0 group-hover:text-amber-500/20 transition-colors duration-500 blur-sm" />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* تدرج متقدم */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                    
                    {/* تأثير الإضاءة */}
                    <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-700">
                        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-3/4 h-3/4 bg-amber-500/15 blur-3xl" />
                    </div>

                    {/* ── شارة الحالة ── */}
                    <div className="absolute top-4 left-4">
                        <motion.div 
                            whileHover={{ scale: 1.1 }}
                            className="flex items-center gap-2 bg-black/80 backdrop-blur-xl border border-white/20 px-3 py-2 rounded-2xl shadow-lg"
                        >
                            <Settings className="w-3 h-3 text-amber-400" />
                            <span className="text-xs font-black uppercase tracking-wider text-amber-400">
                                {part.condition || 'NEW'}
                            </span>
                        </motion.div>
                    </div>

                    {/* زر المفضلة - أيقونة قلب حرة وشفافة فوق الصورة */}
                    <div className="absolute top-4 end-4 z-30 flex items-center gap-2">
                        <motion.button
                            whileHover={{ scale: 1.2 }}
                            whileTap={{ scale: 0.8 }}
                            onClick={(e) => {
                                e.stopPropagation();
                                toggleFav(e);
                            }}
                            className="p-1.5 border-none bg-transparent hover:scale-115 transition-all duration-300 cursor-pointer shadow-none outline-none focus:outline-none flex items-center justify-center"
                            title={isRTL ? 'المفضلة' : 'Favorite'}
                        >
                            <Heart className={cn(
                                "w-6 h-6 transition-all duration-300",
                                isFav
                                    ? "fill-red-500 text-red-500 drop-shadow-[0_0_12px_rgba(239,68,68,0.95)]"
                                    : "text-white/90 drop-shadow-[0_2px_8px_rgba(0,0,0,0.9)] hover:text-red-400"
                            )} />
                        </motion.button>
                    </div>

                    {/* ── حالة المخزون ── */}
                    <div className="absolute bottom-4 left-4">
                        <motion.div 
                            whileHover={{ scale: 1.05 }}
                            className={cn(
                                "flex items-center gap-2 px-4 py-2 rounded-2xl backdrop-blur-xl border shadow-lg transition-all duration-300",
                                stockBg,
                                stockBorder,
                                stock > 0 ? "hover:scale-105" : ""
                            )}
                        >
                            <Package className={cn("w-4 h-4", stockColor)} />
                            <span className={cn("text-xs font-black uppercase tracking-wider", stockColor)}>
                                {stockLabel}
                            </span>
                            {stock > 0 && (
                                <motion.div
                                    animate={{ scale: [1, 1.2, 1] }}
                                    transition={{ duration: 2, repeat: Infinity }}
                                    className={cn("w-2 h-2 rounded-full", 
                                        stock > 5 ? "bg-emerald-400" : "bg-amber-400"
                                    )}
                                />
                            )}
                        </motion.div>
                    </div>

                    {/* شارات مميزة */}
                    <div className="absolute bottom-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity duration-700">
                        <div className="flex items-center gap-1 px-2 py-1 bg-purple-500/20 border border-purple-500/30 rounded-lg backdrop-blur-md">
                            <Crown className="w-3 h-3 text-purple-400" />
                            <span className="text-xs font-bold text-purple-400">{isRTL ? 'أصلي' : 'Original'}</span>
                        </div>
                    </div>
                </div>

                {/* ── معلومات القطعة ── */}
                <div className="p-6 space-y-5">
                    {/* الماركة */}
                    {(part.brand || part.brandName) && (
                        <div className="flex items-center gap-3">
                            <div className="h-px flex-1 bg-gradient-to-r from-transparent via-amber-500/30 to-transparent" />
                            <div className="flex items-center gap-2 px-3 py-1 bg-amber-500/10 border border-amber-500/20 rounded-xl">
                                <Diamond className="w-3 h-3 text-amber-400" />
                                <p className="text-xs font-black text-amber-400/80 tracking-[0.2em] uppercase">
                                    {part.brand || part.brandName}
                                </p>
                            </div>
                            <div className="h-px flex-1 bg-gradient-to-r from-transparent via-amber-500/30 to-transparent" />
                        </div>
                    )}

                    {/* الاسم */}
                    <div className="space-y-2">
                        <h3 className="text-lg font-black leading-tight line-clamp-2 group-hover:text-amber-400 transition-colors duration-300 min-h-[3rem] flex items-center">
                            {name}
                        </h3>
                        
                        {/* الفئة */}
                        {(part.categoryAr || part.category) && (
                            <div className="flex items-center gap-2">
                                <Cog className="w-3 h-3 text-white/40" />
                                <p className="text-xs text-white/50 uppercase tracking-widest font-bold">
                                    {part.categoryAr || part.category}
                                </p>
                            </div>
                        )}
                    </div>

                    {/* زر الطلب عبر الواتساب مع الفاتورة المرفقة */}
                    <div className="flex items-center justify-between gap-3 pt-4 border-t border-white/10">
                        <div className="flex-1 overflow-hidden">
                            <div className="flex items-center gap-2 mb-1">
                                <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
                                <p className="text-[10px] text-emerald-400 font-black uppercase tracking-widest">
                                    {isRTL ? 'متاح للطلب المباشر' : 'AVAILABLE UPON REQUEST'}
                                </p>
                            </div>
                            <p className="text-xs font-bold text-white/70 line-clamp-1">
                                {isRTL ? 'اطلب وتواصل فورياً' : 'Order via WhatsApp'}
                            </p>
                        </div>

                        {/* زر الطلب عبر الواتساب */}
                        <motion.button
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={(e) => {
                                e.stopPropagation();
                                const phone = (socialLinks?.whatsapp || '+821080880014').replace(/\D/g, '');
                                const imgUrl = imageSrc.startsWith('http') ? imageSrc : `${window.location.origin}${imageSrc}`;
                                const invoiceMsg = isRTL
                                    ? `📋 *فاتورة طلب قطعة غيار - HM CAR*\n───────────────\n📦 *القطعة:* ${name}\n🏢 *الوكالة:* ${part.brand || part.brandName || 'غير محدد'}\n🏷️ *التصنيف:* ${part.categoryAr || part.category || 'عام'}\n🖼️ *صورة القطعة:* ${imgUrl}\n───────────────\nالسلام عليكم، أرجو تزويدي بالسعر وتأكيد إمكانية شحن هذه القطعة.`
                                    : `📋 *SPARE PART ORDER INVOICE - HM CAR*\n───────────────\n📦 *Part:* ${name}\n🏢 *Brand:* ${part.brand || part.brandName || 'General'}\n🏷️ *Category:* ${part.category || 'General'}\n🖼️ *Part Image:* ${imgUrl}\n───────────────\nHello, please provide the price and confirm shipping availability for this part.`;
                                window.open(`https://wa.me/${phone}?text=${encodeURIComponent(invoiceMsg)}`, '_blank');
                            }}
                            className="h-11 px-5 rounded-2xl bg-gradient-to-r from-emerald-600 to-emerald-500 text-white font-black text-xs uppercase tracking-wider hover:brightness-110 transition-all shadow-[0_0_20px_rgba(16,185,129,0.3)] flex items-center gap-2"
                        >
                            <span>{isRTL ? 'طلب عبر الواتساب' : 'Order via WhatsApp'}</span>
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 24 24">
