'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Download, X, RefreshCw, CheckCircle2, AlertCircle,
  Car, Layers, Gavel, ExternalLink, Sparkles
} from 'lucide-react';
import { useLanguage } from '@/lib/LanguageContext';
import { useToast } from '@/lib/ToastContext';

interface InlineImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  type: 'car' | 'part' | 'auction';
  onSuccess: () => void;
}

export default function InlineImportModal({ isOpen, onClose, type, onSuccess }: InlineImportModalProps) {
  const { isRTL } = useLanguage();
  const { showToast } = useToast();

  const [url, setUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [previewData, setPreviewData] = useState<any>(null);
  const [isDuplicate, setIsDuplicate] = useState(false);

  if (!isOpen) return null;

  const titles = {
    car: isRTL ? 'استيراد سيارة من رابط (كوري / خارجي)' : 'Import Car from URL',
    part: isRTL ? 'استيراد قطعة غيار من رابط' : 'Import Spare Part from URL',
    auction: isRTL ? 'استيراد جلسة مزاد مباشر من رابط' : 'Import Auction Session from URL'
  };

  const icons = {
    car: Car,
    part: Layers,
    auction: Gavel
  };

  const IconComp = icons[type];

  const getToken = () => {
    if (typeof window === 'undefined') return '';
    return localStorage.getItem('hm_token') || localStorage.getItem('carx_token') || localStorage.getItem('token') || '';
  };

  const handlePreview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!url || !url.startsWith('http')) {
      showToast(isRTL ? 'يرجى إدخال رابط صحيح يبدأ بـ http' : 'Please enter a valid HTTP URL', 'error');
      return;
    }

    setLoading(true);
    setPreviewData(null);
    setIsDuplicate(false);

    try {
      const token = getToken();
      if (!token) {
        showToast(isRTL ? '⚠️ انتهت الجلسة. يرجى تسجيل الدخول مجدداً' : 'Session expired. Please log in again', 'error');
        setTimeout(() => { window.location.href = '/login?role=admin'; }, 1000);
        return;
      }

      const res = await fetch('/api/v2/import/preview', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
          'X-Tenant-ID': process.env.NEXT_PUBLIC_TENANT_ID || 'hmcar'
        },
        body: JSON.stringify({ url, type })
      });

      const data = await res.json();
      if (res.status === 401) {
        showToast(isRTL ? '⚠️ انتهت صلاحية الجلسة (Token Expired). يرجى إعادة تسجيل الدخول' : 'Token expired. Please log in again', 'error');
        setTimeout(() => { window.location.href = '/login?role=admin'; }, 1500);
        return;
      }

      if (res.ok && data.success) {
        setPreviewData(data.data);
        setIsDuplicate(!!data.duplicate);
        showToast(isRTL ? '✅ تم معاينة البيانات وتعريبها بنجاح' : 'Data previewed successfully', 'success');
      } else {
        throw new Error(data.error || data.message || 'فشل الاستخراج');
      }
    } catch (err: any) {
      showToast(err.message || (isRTL ? '❌ فشل الاستخراج من الرابط' : 'Failed to extract data'), 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleConfirmSave = async () => {
    if (!previewData) return;
    setSaving(true);

    try {
      const token = getToken();
      let endpoint = '/api/v2/import/save';

      if (type === 'car') endpoint = '/api/v2/import/korean-cars';
      else if (type === 'part') endpoint = '/api/v2/import/parts';
      else if (type === 'auction') endpoint = '/api/v2/import/live-auctions';

      const bodyPayload = type === 'auction' 
        ? { targetUrl: url, limit: 20 } 
        : previewData;

      const res = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
          'X-Tenant-ID': process.env.NEXT_PUBLIC_TENANT_ID || 'hmcar'
        },
        body: JSON.stringify(bodyPayload)
      });

      const data = await res.json();
      if (res.status === 401) {
        showToast(isRTL ? '⚠️ انتهت الجلسة. يرجى إعادة تسجيل الدخول' : 'Session expired. Please log in again', 'error');
        setTimeout(() => { window.location.href = '/login?role=admin'; }, 1500);
        return;
      }

      if (res.ok && (data.success !== false)) {
        showToast(isRTL ? '🎉 تم الاستيراد والتوقيع بالعلامة المائية وتحديث القائمة فوراً!' : 'Imported & saved successfully!', 'success');
        onSuccess();
        onClose();
      } else {
        throw new Error(data.error || data.message || 'فشل الحفظ');
      }
    } catch (err: any) {
      showToast(err.message || (isRTL ? '❌ فشل حفظ البيانات' : 'Failed to save'), 'error');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md" dir={isRTL ? 'rtl' : 'ltr'}>
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="w-full max-w-2xl bg-[#0c0c1e] border border-orange-500/30 rounded-3xl p-6 md:p-8 shadow-2xl space-y-6 text-white relative overflow-hidden"
      >
        <div className="flex items-center justify-between border-b border-white/10 pb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-orange-500/10 border border-orange-500/30 flex items-center justify-center">
              <IconComp className="w-5 h-5 text-orange-400" />
            </div>
            <div>
              <h3 className="text-lg font-bold">{titles[type]}</h3>
              <p className="text-xs text-white/40">{isRTL ? 'استيراد فوري بدون الخروج من الصفحة' : 'Instant inline import'}</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 rounded-xl hover:bg-white/10 text-white/60 hover:text-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handlePreview} className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-white/60 mb-2">
              {isRTL ? 'رابط الموقع المستهدف (Encar / رابط خارجي):' : 'Target URL:'}
            </label>
            <div className="flex gap-2">
              <input
                type="url"
                required
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder={type === 'car' ? 'https://www.encar.com/dc/dc_cardetailview.do...' : 'https://...'}
                className="flex-1 bg-black/60 border border-white/15 rounded-2xl px-4 py-3 text-sm text-white focus:border-orange-500 focus:outline-none transition-colors dir-ltr"
              />
              <button
                type="submit"
                disabled={loading}
                className="px-5 py-3 rounded-2xl bg-orange-500 text-black font-bold text-xs hover:bg-orange-400 transition-all flex items-center gap-2 disabled:opacity-50 shrink-0"
              >
                {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                {isRTL ? 'معاينة واستخراج' : 'Extract Preview'}
              </button>
            </div>
          </div>
        </form>

        {/* Duplicate Warning */}
        {isDuplicate && (
          <div className="p-3 rounded-2xl bg-yellow-500/10 border border-yellow-500/30 text-yellow-400 text-xs flex items-center gap-2 font-bold">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>{isRTL ? '⚠️ تنبيه: تم استيراد هذا الرابط سابقاً. يمكن إعادة استيراده لطلب تحديث.' : '⚠️ Warning: Previously imported.'}</span>
          </div>
        )}

        {/* Preview Container */}
        {previewData && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-4 bg-white/[0.03] border border-white/10 p-5 rounded-2xl">
            <div className="flex items-start justify-between gap-4">
              <div>
                <span className="text-[10px] uppercase font-black px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">
                  {isRTL ? 'معرب ومفحوص جاهز' : 'Translated & Ready'}
                </span>
                <h4 className="text-base font-bold text-white mt-1">{previewData.title || previewData.name}</h4>
                <p className="text-xs text-white/50 line-clamp-2 mt-1">{previewData.description || (isRTL ? 'لا يوجد وصف متاح' : 'No description')}</p>
              </div>
              {previewData.price > 0 && (
                <div className="text-left shrink-0">
                  <span className="text-xs text-white/40 block">{isRTL ? 'السعر التقديري' : 'Est. Price'}</span>
                  <span className="text-lg font-black text-orange-400">{previewData.price.toLocaleString('ar-SA')} SAR</span>
                </div>
              )}
            </div>

            {/* Images Preview */}
            {previewData.images && previewData.images.length > 0 && (
              <div>
                <p className="text-xs text-white/40 font-bold mb-2">{isRTL ? `الصور المستخرجة (${previewData.images.length}) مع العلامة المائية:` : 'Images:'}</p>
                <div className="flex gap-2 overflow-x-auto pb-2">
                  {previewData.images.slice(0, 6).map((imgUrl: string, idx: number) => (
                    <img key={idx} src={imgUrl} alt="preview" className="w-16 h-16 object-cover rounded-xl border border-white/10 shrink-0" />
                  ))}
                </div>
              </div>
            )}

            <button
              onClick={handleConfirmSave}
              disabled={saving}
              className="w-full py-3.5 rounded-2xl bg-emerald-500 text-black font-black text-xs uppercase tracking-widest hover:bg-emerald-400 transition-all flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(16,185,129,0.3)] disabled:opacity-50"
            >
              {saving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
              {isRTL ? 'تأكيد الحفظ المباشر وتظليل الصورة' : 'Confirm Import & Apply Watermark'}
            </button>
          </motion.div>
        )}
      </motion.div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link2, Sparkles, RefreshCw, CheckCircle2, ArrowRight, X, Image as ImageIcon } from 'lucide-react';
import { useLanguage } from '@/lib/LanguageContext';
import { useToast } from '@/lib/ToastContext';

interface QuickImportBarProps {
    type: 'car' | 'part' | 'auction';
    onSuccess: () => void;
    placeholder?: string;
    className?: string;
}

export default function QuickImportBar({ type, onSuccess, placeholder, className = '' }: QuickImportBarProps) {
    const { isRTL } = useLanguage();
    const { showToast } = useToast();

    const [url, setUrl] = useState('');
    const [loading, setLoading] = useState(false);
    const [previewData, setPreviewData] = useState<any>(null);
    const [saving, setSaving] = useState(false);
    const [isDuplicate, setIsDuplicate] = useState(false);

    const defaultPlaceholders = {
        car: isRTL ? 'ضع رابط سيارة Encar أو رابط خارجي للاستيراد السريع هنا...' : 'Paste Encar or external car URL here for quick import...',
        part: isRTL ? 'ضع رابط قطعة غيار لاستيرادها فوراً...' : 'Paste spare part URL for instant import...',
        auction: isRTL ? 'ضع رابط سيارة لإدراجها في المزاد الفوري المباشر...' : 'Paste car URL to create live auction instantly...'
    };

    const getToken = () => {
        if (typeof window === 'undefined') return '';
        return localStorage.getItem('hm_token') || localStorage.getItem('carx_token') || localStorage.getItem('token') || '';
    };

    const handleFetch = async (e: React.FormEvent) => {
        e.preventDefault();
        const trimmedUrl = url.trim();
        if (!trimmedUrl || !trimmedUrl.startsWith('http')) {
            showToast(isRTL ? 'يرجى وضع رابط صحّيح يبدأ بـ http:// أو https://' : 'Please enter a valid URL starting with http:// or https://', 'error');
            return;
        }

        // تنبيه ذكي إذا كان الرابط رابط قائمة وليس سيارة منفردة
        const lowerUrl = trimmedUrl.toLowerCase();
        if (type === 'car' && (lowerUrl.includes('list/car') || lowerUrl.includes('search=') || lowerUrl.includes('list.do'))) {
            showToast(isRTL ? '⚠️ تنبيه: هذا رابط (قائمة بحث). لاستيراد سيارة محددة بكامل صورها ومواصفاتها، افتح صفحة السيارة نفسها وانسخ رابطها المباشر (مثل encar.com/cars/detail/1234)' : '⚠️ Warning: This is a search list URL. Please open a specific car and paste its direct detail URL (e.g. encar.com/cars/detail/1234)', 'info');
        }

        setLoading(true);
        setPreviewData(null);
        setIsDuplicate(false);

        try {
            const token = getToken();
            const res = await fetch('/api/v2/import/preview', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': token ? `Bearer ${token}` : '',
                    'X-Tenant-ID': process.env.NEXT_PUBLIC_TENANT_ID || 'hmcar'
                },
                body: JSON.stringify({ url: trimmedUrl, type })
            });

            let json: any = null;
            try { json = await res.json(); } catch {}

            if (res.ok && json?.success) {
                setPreviewData(json.data);
                setIsDuplicate(!!json.duplicate);
                showToast(isRTL ? '✨ تم استخراج ومعاينة البيانات بنجاح! راجعها ثم اضغط حفظ' : 'Data extracted successfully! Review and confirm save', 'success');
            } else {
                const errMsg = json?.error || json?.message || (isRTL ? 'فشل استخراج البيانات من الرابط. تأكد من استخدام رابط صفحة تفاصيل عنصر محدد' : 'Failed to extract data. Use a specific item page URL');
                throw new Error(errMsg);
            }
        } catch (err: any) {
            const raw = String(err?.message || err || '');
            const friendly = (raw.includes('TypeError') || raw.includes('fetch'))
                ? (isRTL ? '❌ متعذر معالجة هذه الصفحة. يرجى تجربة رابط صفحة سيارة تفصيلية بدلاً من رابط قائمة البحث' : 'Unable to process page. Use direct car detail URL')
                : raw;
            showToast(friendly, 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleConfirmSave = async () => {
        if (!previewData) return;
        setSaving(true);
        try {
            const token = getToken();
            const res = await fetch('/api/v2/import/save', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': token ? `Bearer ${token}` : '',
                    'X-Tenant-ID': process.env.NEXT_PUBLIC_TENANT_ID || 'hmcar'
                },
                body: JSON.stringify({
                    type,
                    data: {
                        ...previewData,
                        sourceUrl: url
                    }
                })
            });

            let json: any = null;
            try { json = await res.json(); } catch {}

            if (res.ok && json?.success) {
                showToast(isRTL ? '🎉 تم الحفظ وإدراج البيانات بنجاح في الصفحة!' : '🎉 Saved & inserted into page!', 'success');
                setUrl('');
                setPreviewData(null);
                onSuccess();
            } else {
                const errMsg = json?.error || json?.message || (isRTL ? 'فشل حفظ البيانات. تأكد من إدخال اسم ومواصفات صالحة' : 'Failed to save data');
                throw new Error(errMsg);
            }
        } catch (err: any) {
            const raw = String(err?.message || err || '');
            const friendly = (raw.includes('TypeError') || raw.includes('fetch'))
                ? (isRTL ? '❌ حدث خطأ أثناء الحفظ. جرب استخدام رابط صفحة سيارة منفردة' : 'Save Error')
                : raw;
            showToast(friendly, 'error');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className={`w-full space-y-3 ${className}`}>
            {/* شريط الإدخال المباشر في الصفحة */}
            <form onSubmit={handleFetch} className="relative flex items-center gap-2 p-1.5 rounded-2xl bg-[#141625] border border-orange-500/30 hover:border-orange-500/60 transition-all shadow-xl backdrop-blur-md">
                <div className="flex items-center gap-2.5 px-3 text-orange-400">
                    <Link2 className="w-5 h-5 animate-pulse" />
                </div>
                <input
                    type="url"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                    placeholder={placeholder || defaultPlaceholders[type]}
                    className="flex-1 bg-transparent text-white text-xs sm:text-sm font-medium placeholder-white/40 focus:outline-none py-2"
                />
                {url && (
                    <button type="button" onClick={() => { setUrl(''); setPreviewData(null); }} className="p-1 rounded-full text-white/40 hover:text-white">
                        <X className="w-4 h-4" />
                    </button>
                )}
                <button
                    type="submit"
                    disabled={loading || !url.trim()}
                    className="h-10 px-5 rounded-xl bg-gradient-to-r from-orange-500 to-amber-500 text-black font-black text-xs uppercase tracking-wider hover:brightness-110 transition-all flex items-center gap-2 disabled:opacity-40 shadow-lg shadow-orange-500/20 shrink-0"
                >
                    {loading ? (
                        <>
                            <RefreshCw className="w-4 h-4 animate-spin" />
                            <span>{isRTL ? 'جاري التجريف...' : 'EXTRACTING...'}</span>
                        </>
                    ) : (
                        <>
                            <Sparkles className="w-4 h-4" />
                            <span>{isRTL ? 'استيراد فوراً' : 'IMPORT NOW'}</span>
                        </>
                    )}
                </button>
            </form>

            {/* شريط المعاينة والتأكيد الفوري أسفل الشريط */}
            <AnimatePresence>
                {previewData && (
                    <motion.div
                        initial={{ opacity: 0, y: -10, scale: 0.98 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: -10, scale: 0.98 }}
                        className="p-4 rounded-2xl bg-[#1b1e33] border border-emerald-500/40 shadow-2xl space-y-3"
                    >
                        <div className="flex items-center justify-between border-b border-white/10 pb-2">
                            <div className="flex items-center gap-2">
                                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                                <span className="font-black text-xs text-emerald-300 uppercase tracking-wider">
                                    {isRTL ? 'معاينة العنصر المستورد قبل الاعتماد النهائي' : 'Imported Item Preview'}
                                </span>
                                {isDuplicate && (
                                    <span className="px-2 py-0.5 rounded-md bg-amber-500/20 text-amber-300 text-[10px] font-bold border border-amber-500/30">
                                        {isRTL ? 'موجود مسبقاً (سيُحدَّث)' : 'Existing Item (Will Update)'}
                                    </span>
                                )}
                            </div>
                            <button onClick={() => setPreviewData(null)} className="p-1 rounded-full text-white/40 hover:text-white">
                                <X className="w-4 h-4" />
                            </button>
                        </div>

                        <div className="flex flex-col sm:flex-row items-center gap-4">
                            {/* معاينة الصورة */}
                            <div className="w-24 h-20 rounded-xl overflow-hidden bg-black/50 border border-white/10 relative shrink-0">
                                {(previewData.images?.[0] || previewData.imageUrl || previewData.img) ? (
                                    <img
                                        src={previewData.images?.[0] || previewData.imageUrl || previewData.img}
                                        alt={previewData.title || previewData.name || ''}
                                        className="w-full h-full object-cover"
                                    />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-white/30">
                                        <ImageIcon className="w-6 h-6" />
                                    </div>
