'use client';

/**
 * سياق الهوية والتوثيق (AuthContext)
 * المسؤول عن إدارة بيانات المستخدم المسجل، الصلاحيات، وعمليات تسجيل الخروج.
 * يحفظ الجلسة بشكل دائم ويتحقق من صلاحية التوكن عند كل تحميل للصفحة.
 */

import { useEffect, useState, createContext, useContext, ReactNode, useCallback } from 'react';
import { api } from '@/lib/api-original';
import { apiCache } from './api-cache';

/**
 * واجهة بيانات المستخدم
 */
interface User {
    _id: string;
    name: string;
    username?: string;
    email?: string;
    role: string;
    phone?: string;
}

interface AuthContextType {
    user: User | null;
    isLoggedIn: boolean;
    isLoading: boolean;
    isAdmin: boolean;
    login: (token: string, userData: User) => void;
    logout: () => void;
    refreshUser: () => void;
}

const AuthContext = createContext<AuthContextType | null>(null);

/**
 * خطاف مخصص لاستخدام سياق التوثيق في أي مكون
 */
export function useAuth() {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within AuthProvider');
    }
    return context;
}

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    const isLoggedIn = !!user;
    const isAdmin = user?.role === 'admin' || user?.role === 'super_admin' || user?.role === 'manager';

    /**
     * مسح ملفات تعريف الارتباط (Cookies) الخاصة بالتوثيق
     */
    const clearCookies = useCallback(() => {
        if (typeof document !== 'undefined') {
            document.cookie = 'hm_token=; path=/; max-age=0; SameSite=Lax';
            document.cookie = 'hm_user_role=; path=/; max-age=0; SameSite=Lax';
        }
    }, []);

    /**
     * مسح جميع بيانات التوثيق من التخزين المحلي والمتصفح
     */
    const clearAuth = useCallback(() => {
        if (typeof window !== 'undefined') {
            localStorage.removeItem('hm_token');
            localStorage.removeItem('hm_user');
            localStorage.removeItem('hm_user_role');
        }
        clearCookies();
        setUser(null);
    }, [clearCookies]);

    /**
     * تسجيل دخول جديد - يحفظ البيانات في localStorage والكوكيز
     */
    const login = useCallback((token: string, userData: User) => {
        if (typeof window !== 'undefined') {
            localStorage.setItem('hm_token', token);
            localStorage.setItem('hm_user', JSON.stringify(userData));
            const role = userData.role || 'buyer';
            localStorage.setItem('hm_user_role', role);

            // حفظ في Cookie للـ middleware - سنة كاملة للاستمرارية
            const maxAge = 60 * 60 * 24 * 365;
            document.cookie = `hm_token=${token}; path=/; max-age=${maxAge}; SameSite=Lax`;
            document.cookie = `hm_user_role=${role}; path=/; max-age=${maxAge}; SameSite=Lax`;
        }
        setUser(userData);
    }, []);

    /**
     * التحقق من صلاحية التوكن مع الخادم وتحديث بيانات المستخدم
     * يُستخدم عند تحميل الصفحة للتأكد من أن الجلسة لا تزال صالحة
     */
    const verifyTokenWithServer = useCallback(async () => {
        const token = typeof window !== 'undefined' ? localStorage.getItem('hm_token') : null;
        if (!token) {
            setIsLoading(false);
            return;
        }

        try {
            // استخدام fetch مباشرة للتحكم الكامل في الاستجابة
            const apiBase = (typeof window !== 'undefined' && (window as any).__NEXT_PUBLIC_API_URL__) ||
                process.env.NEXT_PUBLIC_API_URL || '';
            const tenantId = process.env.NEXT_PUBLIC_TENANT_ID || 'hmcar';

            // استخدام AbortController يدوي لدعم جميع البيئات (Vercel Edge + قديم)
            const authController = new AbortController();
            const authTimeout = setTimeout(() => authController.abort(), 5000); // 5 ثواني كافية

            const response = await fetch(`${apiBase}/v2/auth/verify`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'X-Tenant-ID': tenantId,
                },
                signal: authController.signal,
            });
            clearTimeout(authTimeout);

            // ⚠️ فقط عند 401 صريح نطرد المستخدم - أي شيء آخر نحافظ على الجلسة
            if (response.status === 401) {
                console.warn('[Auth] Token expired (401) - clearing session');
                clearAuth();
                setIsLoading(false);
                return;
            }

            if (!response.ok) {
                // 500, 503, network error → احتفظ بالجلسة المحلية
                console.warn(`[Auth] Server returned ${response.status} - keeping local session`);
                setIsLoading(false);
                return;
            }

            const data = await response.json().catch(() => null);

            if (data?.success && data?.user) {
                const freshUser = data.user;
                setUser(freshUser);
                localStorage.setItem('hm_user', JSON.stringify(freshUser));
                localStorage.setItem('hm_user_role', freshUser.role || 'buyer');
                // تحديث الكوكيز للـ middleware
                const maxAge = 60 * 60 * 24 * 365;
                document.cookie = `hm_token=${token}; path=/; max-age=${maxAge}; SameSite=Lax`;
                document.cookie = `hm_user_role=${freshUser.role || 'buyer'}; path=/; max-age=${maxAge}; SameSite=Lax`;
            } else if (data?._id) {
                setUser(data);
                localStorage.setItem('hm_user', JSON.stringify(data));
                localStorage.setItem('hm_user_role', data.role || 'buyer');
            }
            // أي استجابة أخرى → لا نمسح الجلسة، نحافظ عليها
        } catch (err: any) {
            // خطأ في الشبكة أو timeout → نحافظ على الجلسة المحلية تماماً
            console.warn('[Auth] Network error during verify - keeping local session:', err?.message || err);
        } finally {
            setIsLoading(false);
        }
    }, [clearAuth]);

    /**
     * التحقق من وجود جلسة دخول سابقة عند تحميل الموقع
     * يقرأ من localStorage فوراً للسرعة، ثم يتحقق من الخادم في الخلفية
     */
    const checkExistingLogin = useCallback(() => {
        setIsLoading(true);
        try {
            if (typeof window === 'undefined') {
                setIsLoading(false);
                return;
            }

            const token = localStorage.getItem('hm_token');
            const userStr = localStorage.getItem('hm_user');

            if (!token) {
                // لا توكن = لم يسجل دخول مطلقاً
                clearCookies();
                setIsLoading(false);
                return;
            }

            // التوكن موجود - نستعيد بيانات المستخدم من localStorage فوراً
            if (userStr) {
                try {
                    const userData = JSON.parse(userStr);
                    if (userData && (userData.role || userData._id || userData.id)) {
                        // بيانات صالحة → نعيّنها فوراً ثم نتحقق في الخلفية
                        setUser(userData);
                        // تحديث الكوكيز للـ middleware
                        const maxAge = 60 * 60 * 24 * 365;
                        const role = userData.role || 'buyer';
                        document.cookie = `hm_token=${token}; path=/; max-age=${maxAge}; SameSite=Lax`;
                        document.cookie = `hm_user_role=${role}; path=/; max-age=${maxAge}; SameSite=Lax`;
                        localStorage.setItem('hm_user_role', role);
                        // تحقق في الخلفية (لا يطرد المستخدم عند فشله)
                        verifyTokenWithServer();
                        return;
                    }
                } catch {
                    // JSON تالف - نتجاهله ونتحقق من السيرفر
                }
            }

            // التوكن موجود لكن بيانات المستخدم غير متوفرة → نتحقق من السيرفر
            verifyTokenWithServer();

        } catch (error) {
            console.error('Auth check failed:', error);
            setIsLoading(false);
        }
    }, [clearAuth, clearCookies, verifyTokenWithServer]);

    // التحقق من الجلسة مرة واحدة عند التحميل
    useEffect(() => {
        checkExistingLogin();
    }, [checkExistingLogin]);

    // إرسال إشارة نبض كل 5 دقائق لإبلاغ السيرفر أن المستخدم متصل
    useEffect(() => {
        let heartbeatInterval: NodeJS.Timeout;
        let initialTimeout: NodeJS.Timeout;

        if (user) {
            const sendHeartbeat = () => {
                api.users.heartbeat().catch(() => {});
            };
            initialTimeout = setTimeout(sendHeartbeat, 3000);
            heartbeatInterval = setInterval(sendHeartbeat, 5 * 60 * 1000);
        }

        return () => {
            if (initialTimeout) clearTimeout(initialTimeout);
            if (heartbeatInterval) clearInterval(heartbeatInterval);
        };
    }, [user]);

    // الاستماع لتغييرات localStorage من تابات أخرى
    useEffect(() => {
        const handleStorage = (e: StorageEvent) => {
            if (e.key === 'hm_token') {
                if (!e.newValue) {
                    setUser(null);
                } else if (e.newValue !== e.oldValue) {
                    checkExistingLogin();
                }
            }
        };
        window.addEventListener('storage', handleStorage);
        return () => window.removeEventListener('storage', handleStorage);
    }, [checkExistingLogin]);

    function refreshUser() {
        checkExistingLogin();
    }

    /**
     * تسجيل الخروج - ذكي حسب نوع الحساب
     */
    async function logout() {
        await api.auth.logout().catch(() => {});
        apiCache.clear();
        // نحفظ نوع الحساب قبل المسح لنوجّه بشكل صحيح
        const role = user?.role || (typeof window !== 'undefined' ? localStorage.getItem('hm_user_role') : null);
        const isAdminRole = role === 'admin' || role === 'super_admin' || role === 'manager';
        clearAuth();
        if (typeof window !== 'undefined') {
            window.location.href = isAdminRole ? '/login?role=admin' : '/login';
        }
    }


    return (
        <AuthContext.Provider value={{
            user,
            isLoggedIn,
            isLoading,
            isAdmin,
            login,
            logout,
            refreshUser
        }}>
            {children}
        </AuthContext.Provider>
    );
}

'use client';

import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  getTenantConfig, 
  getTenantApiUrl,
  TENANT_CONFIGS,
  DEFAULT_TENANT_ID 
} from './tenant-config';

// ── Types ──
export interface TenantTheme {
  primaryColor: string;
  secondaryColor: string;
  accentColor: string;
  backgroundColor: string;
  textColor: string;
}

export interface TenantContact {
  whatsapp: string;
  email: string;
  phone: string;
}

export interface TenantSettings {
  currency: string;
  language: string;
  direction: 'rtl' | 'ltr';
}

export interface TenantData {
  id: string;
  name: string;
  nameEn: string;
  description?: string;
  descriptionEn?: string;
  logo: string;
  favicon: string;
  theme: TenantTheme;
  contact: TenantContact;
  settings: TenantSettings;
  domains?: string[];
}

interface TenantContextType {
  tenant: TenantData | null;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

// ── Context ──
const TenantContext = createContext<TenantContextType>({
  tenant: null,
  loading: true,
  error: null,
  refetch: async () => {},
});

// ── Provider ──
export function TenantProvider({ children }: { children: React.ReactNode }) {
  // Initialize with domain-detected tenant config for immediate availability
  const initialTenant = typeof window !== 'undefined' ? getTenantConfig() : null;
  
  const [tenant, setTenant] = useState<TenantData | null>(initialTenant);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTenant = async () => {
    // الحصول على إعدادات الـ domain مسبقاً كـ fallback آمن
    const domainConfig = typeof window !== 'undefined'
      ? getTenantConfig()
      : getDefaultTenant();

    try {
      setLoading(true);
      setError(null);

      // تطبيق إعدادات الـ domain فوراً للحصول على أفضل تجربة (بدون انتظار API)
      setTenant(domainConfig);
      if (typeof document !== 'undefined') {
        applyTheme(domainConfig.theme, domainConfig.id);
        updateFavicon(domainConfig.favicon);
        document.title = domainConfig.name || 'HM CAR';
      }

      const baseUrl = getTenantApiUrl();

      // مهلة زمنية للطلب: 5 ثوانٍ فقط لتجنب تعليق الواجهة
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      let response: Response;
      try {
        response = await fetch(`${baseUrl}/api/v2/tenant/info`, {
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          signal: controller.signal,
        });
        clearTimeout(timeoutId);
      } catch (fetchErr) {
        clearTimeout(timeoutId);
        // فشل الشبكة أو انتهت المهلة — نستمر بإعدادات الـ domain (لا نرمي خطأ)
        console.warn('[Tenant] API unreachable, using domain config:', (fetchErr as Error).message);
        return;
      }

      // إذا كان الـ response غير ناجح، نستمر بإعدادات الـ domain بهدوء
      if (!response.ok) {
        console.warn('[Tenant] API returned', response.status, '— using domain config fallback');
        return;
      }

      let data: any;
      try {
        data = await response.json();
      } catch {
        console.warn('[Tenant] Invalid JSON from API — using domain config fallback');
        return;
      }

      if (data?.success && data?.data) {
        // دمج بيانات الـ API مع إعدادات الـ domain (الـ API له الأولوية)
        const mergedTenant = { ...domainConfig, ...data.data };
        setTenant(mergedTenant);
        if (typeof document !== 'undefined') {
          applyTheme(mergedTenant.theme, mergedTenant.id);
          updateFavicon(mergedTenant.favicon);
          document.title = mergedTenant.name || 'HM CAR';
        }
      }
    } catch (err) {
      // أي خطأ غير متوقع — نسجله فقط ولا نرميه للـ ErrorBoundary
      console.warn('[Tenant] Unexpected error in fetchTenant:', err);
      // ضمان وجود tenant دائماً
      setTenant(prev => prev ?? domainConfig);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTenant();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <TenantContext.Provider value={{ tenant, loading, error, refetch: fetchTenant }}>
      {children}
    </TenantContext.Provider>
  );
}

// ── Hook ──
export function useTenant() {
  const context = useContext(TenantContext);
  if (!context) {
    throw new Error('useTenant must be used within TenantProvider');
  }
  return context;
}

// ── Helper Functions ──

function applyTheme(theme: TenantTheme, tenantId?: string) {
  if (typeof document === 'undefined') return;

  const root = document.documentElement;
  
  if (tenantId) {
    root.setAttribute('data-tenant', tenantId);
  }
  
  // تطبيق CSS Variables
  root.style.setProperty('--color-primary', theme.primaryColor);
  root.style.setProperty('--color-secondary', theme.secondaryColor);
  root.style.setProperty('--color-accent', theme.accentColor);
  root.style.setProperty('--color-background', theme.backgroundColor);
  root.style.setProperty('--color-text', theme.textColor);
  
  // تحديث meta theme-color
  let metaTheme = document.querySelector('meta[name="theme-color"]');
  if (!metaTheme) {
    metaTheme = document.createElement('meta');
    metaTheme.setAttribute('name', 'theme-color');
    document.head.appendChild(metaTheme);
  }
  metaTheme.setAttribute('content', theme.backgroundColor);
}

function updateFavicon(faviconUrl: string) {
  if (typeof document === 'undefined') return;

  const baseUrl = getTenantApiUrl();

  const fullUrl = faviconUrl.startsWith('http') ? faviconUrl : `${baseUrl}${faviconUrl}`;

  let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
  if (!link) {
    link = document.createElement('link');
    link.rel = 'icon';
    document.head.appendChild(link);
  }
  link.href = fullUrl;
}

function getDefaultTenant(): TenantData {
  // Use the tenant config from tenant-config.ts for consistency
  return TENANT_CONFIGS[DEFAULT_TENANT_ID];
}

/**
 * نظام ذاكرة التخزين المؤقت للعميل (Client-side API Cache)
 * يدعم TTL ذكي حسب نوع البيانات، stale-while-revalidate، وإبطال الأنماط
 */

type CacheEntry = { data: unknown; timestamp: number; tags: string[] };

const memoryCache = new Map<string, CacheEntry>();

/** مستويات TTL حسب نوع البيانات */
export const CACHE_TTL = {
    STATIC:   60 * 60 * 1000,  // 1 ساعة  — brands, settings, public
    MEDIUM:    5 * 60 * 1000,  // 5 دقائق — cars, parts, catalog
    SHORT:     1 * 60 * 1000,  // 1 دقيقة — orders, comparisons
    REALTIME:     15 * 1000,   // 15 ثانية — live auctions, bids
} as const;

const DEFAULT_TTL = CACHE_TTL.MEDIUM;

/** يختار TTL تلقائياً بناءً على المسار */
export function getTTLForEndpoint(endpoint: string): number {
    if (/\/live-auctions|\/live\/|\/bids/.test(endpoint)) return CACHE_TTL.REALTIME;
    if (/\/orders|\/comparisons|\/notifications|\/messages/.test(endpoint)) return CACHE_TTL.SHORT;
    if (/\/settings|\/brands|\/public/.test(endpoint)) return CACHE_TTL.STATIC;
    return CACHE_TTL.MEDIUM;
}

export const apiCache = {
    set: (key: string, data: unknown, { ttl, tags = [] as string[] }: { ttl?: number; tags?: string[] } = {}) => {
        const resolvedTTL = ttl ?? getTTLForEndpoint(key);
        const expiresAt = Date.now() + resolvedTTL;
        const entry: CacheEntry = { data, timestamp: expiresAt, tags };
        memoryCache.set(key, entry);

        if (typeof window !== 'undefined') {
            try {
                sessionStorage.setItem(`api_cache_${key}`, JSON.stringify(entry));
            } catch {}
        }
    },

    get: (key: string) => {
        const memEntry = memoryCache.get(key);
        if (memEntry) {
            if (Date.now() <= memEntry.timestamp) return memEntry.data;
            memoryCache.delete(key);
        }

        if (typeof window !== 'undefined') {
            try {
                const stored = sessionStorage.getItem(`api_cache_${key}`);
                if (stored) {
                    const parsed: CacheEntry = JSON.parse(stored);
                    if (Date.now() <= parsed.timestamp) {
                        memoryCache.set(key, parsed);
                        return parsed.data;
                    }
                    sessionStorage.removeItem(`api_cache_${key}`);
                }
            } catch {}
        }
        return null;
    },

    invalidate: (pattern: string | RegExp) => {
        const isRegex = pattern instanceof RegExp;
        for (const key of memoryCache.keys()) {
            if (isRegex ? (pattern as RegExp).test(key) : key.startsWith(pattern as string)) {
                memoryCache.delete(key);
            }
        }
        if (typeof window !== 'undefined') {
            try {
                Object.keys(sessionStorage).forEach(k => {
                    if (k.startsWith('api_cache_')) {
                        const key = k.replace('api_cache_', '');
                        if (isRegex ? (pattern as RegExp).test(key) : key.startsWith(pattern as string)) {
                            sessionStorage.removeItem(k);
                        }
                    }
                });
            } catch {}
        }
    },

    invalidateByTag: (tag: string) => {
        for (const [key, entry] of memoryCache.entries()) {
            if (entry.tags.includes(tag)) {
                memoryCache.delete(key);
                if (typeof window !== 'undefined') sessionStorage.removeItem(`api_cache_${key}`);
            }
        }
    },

    clear: () => {
        memoryCache.clear();
        if (typeof window !== 'undefined') {
            try {
                Object.keys(sessionStorage).forEach(k => {
                    if (k.startsWith('api_cache_')) sessionStorage.removeItem(k);
                });
            } catch {}
        }
    },

    /** حجم الكاش الحالي */
    size: () => memoryCache.size,
};
